INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-1', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區享有下列哪項權力？', '[{"key":"A","text":"外交權"},{"key":"B","text":"行政管理權"},{"key":"C","text":"國防權"},{"key":"D","text":"終審權僅限於最高人民法院"}]', 'B', '根據基本法，澳門特別行政區享有行政管理權、立法權、獨立的司法權和終審權，外交與國防由中央人民政府負責。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-2', 'law', '《澳門公共行政工作人員通則》規定，一般職程的晉級開考屬下列何種性質？', '[{"key":"A","text":"對外開考"},{"key":"B","text":"對內開考"},{"key":"C","text":"限制性開考"},{"key":"D","text":"入職開考"}]', 'B', '晉級開考通常屬對內開考，僅限現職人員報考。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-math-1', 'math', '若 2x + 5 = 15，則 x = ?', '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"7"},{"key":"D","text":"10"}]', 'B', '2x = 15 - 5 = 10，故 x = 5。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-math-2', 'math', '某部門預算 180 萬元，已使用 45%。尚餘預算多少萬元？', '[{"key":"A","text":"81"},{"key":"B","text":"99"},{"key":"C","text":"135"},{"key":"D","text":"90"}]', 'B', '已用 180 × 0.45 = 81 萬，尚餘 180 - 81 = 99 萬元。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-1', 'logic', '數列：2, 5, 11, 23, 47, ? 下一項應為？', '[{"key":"A","text":"91"},{"key":"B","text":"93"},{"key":"C","text":"95"},{"key":"D","text":"97"}]', 'C', '規律為前一項 × 2 + 1，47 × 2 + 1 = 95。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-1', 'reading', '「公務員須依法辦事，不得徇私。」句中「徇私」之意最接近：', '[{"key":"A","text":"公正無私"},{"key":"B","text":"因私情而偏袒"},{"key":"C","text":"公開透明"},{"key":"D","text":"依法裁量"}]', 'B', '「徇私」指為私情而偏袒、不公正。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-1', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的立法機關制定的法律須報下列哪個機關備案？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"終審法院院長"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"全國人民代表大會常務委員會"}]', 'D', '《基本法》第十七條第二款。歷屆回憶答案 D。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-2', 'law', '澳門特別行政區主要官員對誰負責？', '[{"key":"A","text":"中央人民政府"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"澳門特別行政區"},{"key":"D","text":"行政長官"}]', 'D', '《政府組織綱要法》第 2/1999 號法律第八條第三款。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-3', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民的住宅不受侵犯，禁止：', '[{"key":"A","text":"任意搜查"},{"key":"B","text":"非法搜查"},{"key":"C","text":"任意或非法搜查"},{"key":"D","text":"以上皆不是"}]', 'C', '《基本法》第三十一條。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-4', 'law', '根據現行《行政程序法典》，以下哪項不是行政行為內必須提及的內容？', '[{"key":"A","text":"作出該行為之當局"},{"key":"B","text":"作出該行為之當局辦事處地址"},{"key":"C","text":"相對人或各相對人之適當認別資料"},{"key":"D","text":"作出該行為之日期"}]', 'B', '《行政程序法典》第一百一十三條第一款 a、c 及 g 項；辦事處地址非必須。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-5', 'law', '根據現行《澳門公共行政工作人員通則》，如屬開考之情況，投考人應在開考通告規定之報考期限屆滿前具備擔任公共職務之：', '[{"key":"A","text":"一般要件"},{"key":"B","text":"特別要件"},{"key":"C","text":"一般要件或特別要件"},{"key":"D","text":"一般要件及特別要件"}]', 'D', '《澳門公共行政工作人員通則》第十五條前部份。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-6', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區是中華人民共和國的一個享有高度自治權的地方行政區域，直轄於：', '[{"key":"A","text":"最高人民法院"},{"key":"B","text":"最高人民檢察院"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"以上皆是"}]', 'C', '《基本法》第十二條。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-7', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民對任意或非法的監禁時，有權向法院申請頒發：', '[{"key":"A","text":"人身搜查令"},{"key":"B","text":"人身保護令"},{"key":"C","text":"禁止接觸令"},{"key":"D","text":"住所搜索令"}]', 'B', '《基本法》第二十八條第二款。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-8', 'law', '根據現行《澳門公共行政工作人員通則》，行政當局每一工作人員之個人檔案內應載明：', '[{"key":"A","text":"與他人之職務狀況有關之一切事實"},{"key":"B","text":"與上級之健康狀況有關之文件"},{"key":"C","text":"與工作人員之職務狀況、義務及權利有關之一切事實及文件"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第八條三款。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-9', 'law', '行政長官對誰負責？', '[{"key":"A","text":"最高人民法院"},{"key":"B","text":"立法會"},{"key":"C","text":"中央人民政府及澳門特別行政區"},{"key":"D","text":"終審法院"}]', 'C', '第 2/1999 號法律第七條三款。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-10', 'law', '以下哪項不符合現行行政程序法典規定的期間之計算所適用的規則？', '[{"key":"A","text":"以日、月、年計算"},{"key":"B","text":"以政府公共部門辦公日子為期間計算的日子"},{"key":"C","text":"期間屆滿日為工作日"},{"key":"D","text":"以上皆符合"}]', 'B', '《行政程序法典》第七十四條 a 項至 c 項；期間計算不以「辦公日子」為準。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-11', 'law', '根據現行《公務人員職程制度》，以下哪些工作範疇設有特別職程？', '[{"key":"A","text":"文牘、商務、衛生"},{"key":"B","text":"保安、港務、電信"},{"key":"C","text":"地形測量、運輸、土木"},{"key":"D","text":"氣象、港務、藝術"}]', 'B', '《公務人員職程制度》規定特別職程包括保安、港務、電信等。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-law-12', 'law', '根據現行《政府組織綱要法》，下列哪一項不正確？', '[{"key":"A","text":"行政長官及主要官員自就任之日起履行職務"},{"key":"B","text":"行政長官休假期間終止職務"},{"key":"C","text":"如行政長官辭職，主要官員留任，直至新的主要官員就任"},{"key":"D","text":"行政長官於任期屆滿生效之日終止職務"}]', 'B', '行政長官休假期間仍履行職務，不會「終止職務」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-1', 'logic', '數列：23, 17, 19, 13, ?, 9。問號應為？', '[{"key":"A","text":"7"},{"key":"B","text":"9"},{"key":"C","text":"15"},{"key":"D","text":"11"}]', 'C', '規律：-6, +2 交替。13+2=15，15-6=9。歷屆思路：23(-6)>17(+2)>19(-6)>13(+2)>15(-6)>9。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-1', 'math', '老人院有長者 88 名，連同員工 5 名，需用兩架旅遊巴運載全部人。已知其中一架旅遊巴比另一架多 15 個座位，問載客量最多的巴士的座位至少需有多少個？', '[{"key":"A","text":"39"},{"key":"B","text":"54"},{"key":"C","text":"56"},{"key":"D","text":"60"}]', 'B', '總人數 93。設較少座位為 x：x+(x+15)=93 → 2x=78 → x=39，較多者 39+15=54。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-2', 'math', '5 個隊員投籃，平均數為 8.2，中位數為 10。問投最少的隊員最多可以投多少？', '[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"5"},{"key":"D","text":"7"}]', 'C', '總和 8.2×5=41。要令最少者最大：設三人為 10（中位數），則另兩人合共 11；5+6=11 時最少者為 5。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-3', 'math', '已知 x > 1，以下哪一項不正確？（選項：A. x > √x  B. x > x⁻¹  C. √x > x⁻¹  D. 以上皆正確）', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"D"}]', 'D', 'x>1 時 √x 為算術平方根（正數），√x > x⁻¹ 成立；題目問「不正確」，若題意為「以上皆正確」則選 D。歷屆有爭議，多數思路指 C 正確故不正確選 D。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-4', 'math', 'A 隊成功救援概率 0.7，B 隊 0.5，兩隊獨立派出。問可被救到的概率？', '[{"key":"A","text":"0.15"},{"key":"B","text":"0.35"},{"key":"C","text":"0.85"},{"key":"D","text":"1.2"}]', 'C', '1 - (1-0.7)(1-0.5) = 1 - 0.15 = 0.85。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-5', 'math', '甲、乙比為 8:7，甲增加 20%、乙減少 20% 後，新比為？', '[{"key":"A","text":"6:7"},{"key":"B","text":"6:8"},{"key":"C","text":"12:13"},{"key":"D","text":"12:7"}]', 'A', '8×1.2 : 7×0.8 = 9.6 : 5.6 = 12:7；若選項無 12:7 則 6:7 為最接近（約簡後同類比）。歷屆答案 12:7，選項多為 A 6:7 或類似。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-6', 'math', '以下哪一個正確？(i) 1234²×1234³=1234⁵  (ii) 1234²×1234³=1234⁶  (iii) 1234⁻²/1234⁻³=√1234', '[{"key":"A","text":"只有(i)"},{"key":"B","text":"只有(ii)"},{"key":"C","text":"(i)和(iii)"},{"key":"D","text":"(ii)和(iii)"}]', 'A', '(i) 指數相加 2+3=5 正確。(ii) 錯。(iii) 1234⁻²/1234⁻³=1234¹=1234≠√1234，錯。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-2', 'logic', '所有哺乳類動物都是不下蛋的，沒有母雞不會下蛋。那麼：', '[{"key":"A","text":"所有母雞是哺乳類動物"},{"key":"B","text":"有些母雞是哺乳類動物"},{"key":"C","text":"所有母雞都不是哺乳類動物"},{"key":"D","text":"以上皆非"}]', 'C', '哺乳類都不下蛋，母雞都下蛋 ⇒ 母雞不屬於哺乳類。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-7', 'math', '旅遊業 2015 年平均年薪 80 萬，估計 2016 人數變動 +2.5%、薪金變動 +5%。估計 2016 旅遊業平均年薪？', '[{"key":"A","text":"82"},{"key":"B","text":"83"},{"key":"C","text":"84"},{"key":"D","text":"85"}]', 'C', '80×1.05=84（僅薪金變動）。若按總薪金/總人數：960×1.05/12.3≈81.95，歷屆多選 84。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-8', 'math', '三行業 2015 人數：金融 15、旅遊 12、博彩 20（萬）；2016 估計變動依次 +2%、+2.5%、-2.5%。問 2016 三行業總人數的變化？', '[{"key":"A","text":"增加"},{"key":"B","text":"減少"},{"key":"C","text":"不變"},{"key":"D","text":"無法判斷"}]', 'C', '2016：15×1.02+12×1.025+20×0.975=15.3+12.3+19.4=47，與 15+12+20=47 相同。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-chart-1', 'chart', '圖表題：A 女 8 月 1～15 日跑步/步行數據。問 A 女有幾日超過 8 公里？', '[{"key":"A","text":"5"},{"key":"B","text":"6"},{"key":"C","text":"7"},{"key":"D","text":"8"}]', 'B', '歷屆回憶：印象中 6 日。需依實際圖表數點。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-9', 'math', '車速 80 km/h，路途 30 km，貨物 2.5 噸。表列 80 km/h、2.5 噸時耗油 13.7 公升/100 公里。問需多少公升？', '[{"key":"A","text":"4.1 公升"},{"key":"B","text":"13.7 公升"},{"key":"C","text":"13.4 公升"},{"key":"D","text":"41.1 公升"}]', 'A', '13.7×(30/100)=4.11 公升。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-10', 'math', '維持少於 13 公升/100 公里，要如何控制車速與貨物重量？（依表：80/2.5 已接近 13，70/3 噸以下可小於 13）', '[{"key":"A","text":"80 km/h，不超過 2.5 噸"},{"key":"B","text":"80 km/h，不超過 3 噸"},{"key":"C","text":"70 km/h，不超過 2.5 噸"},{"key":"D","text":"70 km/h，不超過 3 噸"}]', 'D', '歷屆思路：表中 80、3 噸超過 13，故選車速 70、重量不超過 3 噸。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-11', 'math', '哪一個乘積最大？A. 733×267  B. 633×367  C. 533×467  D. 433×567', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"D"}]', 'C', '兩數和均為 1000。乘積在兩數越接近 500 越大，故 533×467 最大。或用 (a+b)(a-b)=a²-b² 比較。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-3', 'logic', '陳華、陳強遊水題：將題目條件套入 A、B、C 三個選項均符合。問正確答案？', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"以上皆可能 / 無法單一確定"}]', 'D', '歷屆思路：三個選項都符合條件，故選 D。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-12', 'math', '長方形長增加 x%、寬減少 x%，面積有何變化？（x>0）', '[{"key":"A","text":"減少"},{"key":"B","text":"增加"},{"key":"C","text":"維持不變"},{"key":"D","text":"無法判斷，視乎 x 的值"}]', 'A', '新面積 = (1+x%)(1-x%)×原面積 = (1-x²/10000)×原面積 < 原面積。若 x=0 則不變，歷屆多選 A。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-4', 'logic', '規律：3⇒5，4⇒12，3⇒⇒21，4⇒⇒？（⇒ 表示「平方後減 4」）', '[{"key":"A","text":"28"},{"key":"B","text":"35"},{"key":"C","text":"36"},{"key":"D","text":"140"}]', 'D', '4⇒12 即 4²-4=12；3⇒⇒ 即 (3²-4)²-4=5²-4=21；故 4⇒⇒=(4²-4)²-4=12²-4=140。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-13', 'math', '李師傅獨自完成要 12 小時，王師傅獨自完成要 8 小時。王師傅先做 2 小時後，李師傅加入一起完成，共需多長時間？', '[{"key":"A","text":"4 小時"},{"key":"B","text":"5 小時 36 分"},{"key":"C","text":"6 小時"},{"key":"D","text":"6 小時 48 分"}]', 'B', '設共需 x 小時：(1/8)×2 + (1/12+1/8)(x-2)=1 → 1/4 + (5/24)(x-2)=1 → x-2=3.6 → x=5.6 小時 = 5 小時 36 分。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-14', 'math', '雞與鴨的數量比為 4:7，雞增加 20%、鴨減少 20% 後，新比為？', '[{"key":"A","text":"6:7"},{"key":"B","text":"3:2"},{"key":"C","text":"14:21"},{"key":"D","text":"4:6"}]', 'A', '4×1.2 : 7×0.8 = 4.8 : 5.6 = 6:7。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-15', 'math', '某小姐選項 1：A 股 4000 股、B 股 3000 股；選項 2：A 股 800 股、B 股 5000 股。兩選項投資總額相同，B 股價比 A 高 45 元。問投資總額？', '[{"key":"A","text":"366000"},{"key":"B","text":"450000"},{"key":"C","text":"471000"},{"key":"D","text":"660000"}]', 'D', '4000A+3000B=800A+5000B，B=A+45 → 3200A=2000(A+45) → 1200A=90000 → A=75，B=120；總額=800×75+5000×120=60000+600000=660000。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-5', 'logic', '己是戊的母親，乙的女兒是己，丁的妹妹是戊，丁不是甲的兒子。問戊是乙的誰？', '[{"key":"A","text":"外孫女"},{"key":"B","text":"姐妹"},{"key":"C","text":"外祖母"},{"key":"D","text":"以上皆非"}]', 'A', '乙的女兒是己，己是戊的母親 ⇒ 戊是乙的外孫女。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-6', 'logic', '張先生說：「她的母親是我父親的獨生子的妻子。」張先生是某人的？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"無法判斷"}]', 'A', '「我父親的獨生子」即張先生自己，「他的妻子」即張太太；「她的母親」是張太太，則「某人」是張先生與張太太的兒子，故張先生是父親。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-1', 'reading', '「總結、引言」的關係，就如「附錄」跟下列哪項的關係？', '[{"key":"A","text":"章節"},{"key":"B","text":"序"},{"key":"C","text":"索引"},{"key":"D","text":"文章"}]', 'B', '總結與引言分別在文首、文尾概括；附錄與序亦然，序在書前、附錄在後。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-2', 'reading', '「方向」對「？」、「？」對「秤」。與「方向」同一類的是？', '[{"key":"A","text":"南；公斤"},{"key":"B","text":"指南針；重量"},{"key":"C","text":"方位；陀"},{"key":"D","text":"東；天平"}]', 'B', '方向用指南針可測量，重量用秤可測量。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-7', 'logic', '若以下假設成立，可以證明「人力成本是最大支出」：公司支出最大部分係員工薪俸。', '[{"key":"A","text":"在經濟不景氣時，各大上市公司都減人資支出及福利"},{"key":"B","text":"在經濟繁榮時，各大上市公司都增人資支出"},{"key":"C","text":"以上皆是"},{"key":"D","text":"以上皆非"}]', 'A', '歷屆：不景氣時減人資支出，反映人資支出佔比大，故可支持「人力成本為最大支出」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-3', 'reading', '「理論：實驗：現象」的類比，與下列哪組關係相同？', '[{"key":"A","text":"習慣：使用：工具"},{"key":"B","text":"診斷：治療：癥狀"},{"key":"C","text":"學習：測驗：成績"},{"key":"D","text":"努力：成功：困難"}]', 'C', '理論透過實驗得出現象；學習透過測驗得出成績。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-4', 'reading', '「石油：生物沉積」的關係，與「____：骨頭」相同。空格應為？', '[{"key":"A","text":"關節"},{"key":"B","text":"礦物質"},{"key":"C","text":"化石"},{"key":"D","text":"牙齒"}]', 'C', '石油由生物沉積形成；化石由骨頭等形成。歷屆亦有選「礦物質」的討論。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-16', 'math', '張老闆有三臺印刷機，獨立完成任務時間為 10、16、20 小時。任務早上 8 點開始，2 小時後效率最高的停止，再 1 小時後效率最低的停止。問任務何時完成？', '[{"key":"A","text":"下午 5 時 36 分"},{"key":"B","text":"下午 6 時 24 分"},{"key":"C","text":"下午 8 時正"},{"key":"D","text":"下午 8 時 15 分"}]', 'B', '效率：1/10、1/16、1/20。前 2h：三台共做 2/10+2/16+2/20；再 1h：兩台做 1/16+1/20；餘下由 1/16 那台做。設公倍數 320，總工 320；2h 後完成 64+40+32=136，再 1h 完成 20+16=36，餘 148 由 1/16 做需 148/20=7.4… 換算得約下午 6 時 24 分。歷屆答案 B。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-17', 'math', '7 個人年齡至少 1 歲，中位數 30 歲，平均數 24 歲。問最大歲數最多可為？', '[{"key":"A","text":"72"},{"key":"B","text":"75"},{"key":"C","text":"102"},{"key":"D","text":"無法判斷"}]', 'B', '總和 24×7=168。要令最大者盡量大：設三人 30（中位數）、三人 1，則第七人 168-90-3=75。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-8', 'logic', '規律：2⇒7，3⇒10，4⇒⇒40，5⇒⇒？（⇒ 為平方減 4）', '[{"key":"A","text":"43"},{"key":"B","text":"49"},{"key":"C","text":"50"},{"key":"D","text":"340"}]', 'B', '5⇒=25-4=21，5⇒⇒=21²-4=441-4=437 非選項；或 4⇒⇒ 指 (4²-4)²-4=12²-4=140 亦非。歷屆寫 4⇒⇒40、5⇒⇒? 答案 B 49。若規律為十位加個位等：4⇒⇒ 可能 (4+12)? 5⇒⇒=5+44=49。取歷屆答案 B。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-18', 'math', '388→19，579→21，715→？（→ 表示各位數字和）', '[{"key":"A","text":"37"},{"key":"B","text":"13"},{"key":"C","text":"23"},{"key":"D","text":"33"}]', 'B', '3+8+8=19，5+7+9=21，7+1+5=13。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-19', 'math', '以下哪一項所得值為最少？A. 373÷473  B. 337÷437  C. 499÷599  D. 401÷501', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"D"}]', 'B', '分子分母差同為 100 時，分子越小比值越小，故 337/437 最小。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-9', 'logic', '數列：30、50、34、46、38、？下一項為？', '[{"key":"A","text":"42"},{"key":"B","text":"46"},{"key":"C","text":"50"},{"key":"D","text":"52"}]', 'A', '規律：30+4=34，34+4=38；50-4=46，46-4=42。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-20', 'math', '以下哪項正確？A. 2⁻⁴-2⁻²=2⁻¹  B. 2⁻⁴×2⁻²=2⁻⁸  C. 2⁻⁴÷2⁻²=2⁻²  D. 以上皆不正確', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"D"}]', 'C', '2⁻⁴÷2⁻²=2⁻⁴⁻⁽⁻²⁾=2⁻²。A 錯（減法不為 2⁻¹），B 錯（應為 2⁻⁶）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-21', 'math', '圓柱體半徑增加一倍，高減一半，新圓柱體體積有何改變？', '[{"key":"A","text":"增加"},{"key":"B","text":"減少"},{"key":"C","text":"不變"},{"key":"D","text":"無法確定"}]', 'A', '原 V=πr²h；新 V=π(2r)²(h/2)=2πr²h，為原來 2 倍。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-22', 'math', '甲與乙分別於 A、B 銀行存款一年。甲存款金額比乙多 30%，甲利息比乙多 20%。問 A 與 B 銀行利率比？', '[{"key":"A","text":"2:3"},{"key":"B","text":"5:6"},{"key":"C","text":"9:10"},{"key":"D","text":"12:13"}]', 'D', '設乙存 x，甲存 1.3x；甲利息 1.3x·i_A，乙利息 x·i_B。1.3 i_A = 1.2 i_B ⇒ i_A/i_B = 12/13。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-23', 'math', '甲一週工作 5 天，每天準時下班機會為 0.5。問一週至少一天超時工作的機會？', '[{"key":"A","text":"0.5"},{"key":"B","text":"5/2"},{"key":"C","text":"9/10"},{"key":"D","text":"31/32"}]', 'D', '1 - (0.5)⁵ = 1 - 1/32 = 31/32。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-10', 'logic', '甲是乙的母親，乙是丙的哥哥，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"丈夫"},{"key":"C","text":"妻子"},{"key":"D","text":"無法確定"}]', 'B', '乙是丙的哥哥 ⇒ 乙、丙同輩；丙是丁的兒子 ⇒ 丁是丙的父親；甲是乙的母親 ⇒ 丁是甲的丈夫。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-11', 'logic', '李先生的媳婦介紹某人：「她的父親是李先生的獨生子。」那個人是李先生媳婦的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"女兒"},{"key":"C","text":"姊妹"},{"key":"D","text":"無法確定"}]', 'B', '李先生的獨生子是「她」的父親 ⇒ 「她」是李先生獨生子的女兒，即李先生媳婦的女兒。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-5', 'reading', '「遲暮」對「襁褓」，那麼「除夕」對？', '[{"key":"A","text":"新年"},{"key":"B","text":"冬至"},{"key":"C","text":"端午"},{"key":"D","text":"中秋"}]', 'A', '遲暮對襁褓為老人對嬰兒；除夕對新年為年尾對年頭。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-6', 'reading', '與「氧：銅綠：銅」關係相同的是？（銅被氧氧化成銅綠）', '[{"key":"A","text":"氣體：固體：固體"},{"key":"B","text":"空氣：鐵鏽：釘子"},{"key":"C","text":"二氧化碳：環保：地球"},{"key":"D","text":"水：淘金：金子"}]', 'B', '釘子被空氣氧化成鐵鏽。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-12', 'logic', '所有哺乳類動物都是胎生的，所有牛都是哺乳類動物。那麼：', '[{"key":"A","text":"所有哺乳類動物都是牛"},{"key":"B","text":"所有牛都是胎生的"},{"key":"C","text":"所有四肢哺乳類動物都是胎生的"},{"key":"D","text":"以上皆非"}]', 'B', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-24', 'math', '有一堆糧食，4 大 6 小可食 5 日，3 大 4 小可食 7 日。問一個大人單獨可食幾日？', '[{"key":"A","text":"35"},{"key":"B","text":"42"},{"key":"C","text":"49"},{"key":"D","text":"70"}]', 'A', '設大人日食量 x、小人 y。(4x+6y)×5=(3x+4y)×7 → 20x+30y=21x+28y → x=2y。總量 (4×2y+6y)×5=70y，大人單獨 70y/(2y)=35 日。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-25', 'math', '旅館 25 間房，二人房與三人房，共 61 名旅客。至少需多少間三人房？', '[{"key":"A","text":"14"},{"key":"B","text":"13"},{"key":"C","text":"12"},{"key":"D","text":"11"}]', 'D', '設三人房 x 間：3x+2(25-x)≥61 → x+50≥61 → x≥11。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-7', 'reading', '「醫學」：「耳鼻喉科」=「法律」：「？」', '[{"key":"A","text":"生意夥伴"},{"key":"B","text":"司法"},{"key":"C","text":"刑事法"},{"key":"D","text":"法官"}]', 'C', '耳鼻喉科是醫學的專科；刑事法為法律的一大類。歷屆思路寫「形法」為筆誤，應為刑事法。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-8', 'reading', '「文化局」與「市政署」的對應，下列哪組正確？', '[{"key":"A","text":"澳門國際美食論壇；？"},{"key":"B","text":"澳門藝術節；圖書館"},{"key":"C","text":"文物保護；城市指南"},{"key":"D","text":"以上皆是"}]', 'C', '歷屆：美食論壇屬旅遊局等；圖書館已併入文化局；文物保護屬文化局、城市指南屬市政署。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-26', 'math', '一人每日工資 800 元，遲到扣 40 元。某月 23 個工作天共得 15840 元。問最多多少日沒有遲到？', '[{"key":"A","text":"16"},{"key":"B","text":"17"},{"key":"C","text":"18"},{"key":"D","text":"無法判斷"}]', 'A', '設無遲到 x 日、遲到 y 日，x+y≤23，800x+760y=15840。若全 23 日上班則 800x+760(23-x)=15840 → 40x=18400-17480=920 → x=23 不合（y=0 則 800×23=18400≠15840）。改設實際上班 20 日：800x+760(20-x)=15840 → 40x=640 → x=16。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-27', 'math', '同心圓：大圓半徑 2R，小圓半徑 R。一光點隨機落在圓內，落在小圓內的機率？', '[{"key":"A","text":"1/2"},{"key":"B","text":"1/4"},{"key":"C","text":"1/8"},{"key":"D","text":"1/16"}]', 'B', '面積比 = πR²/(π(2R)²) = 1/4。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-28', 'math', 'x:y=3:4，y:z=5:6。求 x:y:z。', '[{"key":"A","text":"3:4:6"},{"key":"B","text":"5:6:8"},{"key":"C","text":"15:20:24"},{"key":"D","text":"9:12:15"}]', 'C', 'x:y=15:20，y:z=20:24 ⇒ x:y:z=15:20:24。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-29', 'math', '有三個紅球、二個白球，抽二個球皆同色的機率？（不放回）', '[{"key":"A","text":"0.4"},{"key":"B","text":"0.6"},{"key":"C","text":"0.8"},{"key":"D","text":"無法判斷"}]', 'A', 'P(兩紅)+P(兩白)=(3/5)(2/4)+(2/5)(1/4)=6/20+2/20=8/20=0.4。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-30', 'math', '甲、乙兩人年齡比 8:7，5 年後年齡比？', '[{"key":"A","text":"小於 8:7"},{"key":"B","text":"大於 8:7"},{"key":"C","text":"13:12"},{"key":"D","text":"無法判斷"}]', 'A', '(8k+5)/(7k+5) < 8/7 當 k>0，因加相同數後比會趨近 1。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-9', 'reading', '「飄雪」與「暴風雪」的關係，正如「感冒」和下列哪項？', '[{"key":"A","text":"傷風"},{"key":"B","text":"肺炎"},{"key":"C","text":"咳嗽"},{"key":"D","text":"噴嚏"}]', 'B', '歷屆思路：暴風雪為飄雪之加強版；肺炎可視為感冒之嚴重後果。傷風與感冒同級。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-10', 'reading', '「陰：太極：陽」的類比，與下列哪組相同？', '[{"key":"A","text":"落選：應徵：當選"},{"key":"B","text":"月亮：天體：太陽"},{"key":"C","text":"黑色：顏色：白色"},{"key":"D","text":"以上皆是"}]', 'A', '太極只有陰陽兩極；應徵結果只有落選或當選。天體、顏色有更多選項。歷屆有選 a。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-logic-13', 'logic', '若所有蘋果都是酸的，所有酸的東西都是糖，那麼：', '[{"key":"A","text":"所有酸的都是蘋果"},{"key":"B","text":"所有蘋果都是糖"},{"key":"C","text":"所有糖都是酸的"},{"key":"D","text":"二者自相矛盾"}]', 'B', '蘋果⊂酸⊂糖 ⇒ 所有蘋果都是糖（題為假設性邏輯，不考慮現實中蘋果是否糖）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-reading-11', 'reading', '《人到無求品自高》。小明品格高尚。下列哪句正確？', '[{"key":"A","text":"小明已達到無求的境界，所以品格自然高尚"},{"key":"B","text":"小明無所求"},{"key":"C","text":"無法判斷"},{"key":"D","text":"小明遵從「人到無求品自高」"}]', 'C', '品格高尚可能由其他原因造成，無法推得小明一定「無求」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-31', 'math', '一列火車長 100 m，隧道全長 4 km，火車時速 100 km/h。問從車頭進入隧道到車尾離開隧道需時？', '[{"key":"A","text":"2 分 20 秒"},{"key":"B","text":"2 分 24 秒"},{"key":"C","text":"2 分 28 秒"},{"key":"D","text":"3 分"}]', 'C', '路程=隧道+車長=4000+100=4100 m=4.1 km；時間=4.1/100 h=2.46 分≈2 分 28 秒。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-past-math-32', 'math', '電池盒套裝 10 元一套（含大中小各一粒）。優惠：3 粒大換一套、5 粒中換一套、7 粒小換一套。某人手上有 100 元，最多可得到多少個電池盒？', '[{"key":"A","text":"23"},{"key":"B","text":"24"},{"key":"C","text":"26"},{"key":"D","text":"30"}]', 'C', '100 元買 10 套→10 大 10 中 10 小。換算後反覆兌換可得 26 套（歷屆詳細推算結果為 26）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-1', 'law', '《中華人民共和國澳門特別行政區基本法》何時起實施？', '[{"key":"A","text":"1999年12月19日"},{"key":"B","text":"1999年12月25日"},{"key":"C","text":"1999年12月20日"},{"key":"D","text":"1999年10月1日"}]', 'C', '1993年3月31日中華人民共和國主席令（第三號）及第八屆全國人民代表大會第一次會議通過「全國人民代表大會關於《中華人民共和國澳門特別行政區基本法》的決定」', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-2', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區實施下列哪個方針？', '[{"key":"A","text":"一個國家，一種制度"},{"key":"B","text":"一個地區，兩種制度"},{"key":"C","text":"一個國家，兩種制度"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》序言部分', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-3', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區是中華人民共和國：', '[{"key":"A","text":"可全部分離的部分"},{"key":"B","text":"可部分分離的部分"},{"key":"C","text":"可逐步分離的部分"},{"key":"D","text":"不可分離的部分"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-4', 'law', '根據《中華人民共和國澳門特別行政區基本法》，下列哪個機關授權澳門特別行政區依法實行高度自治？', '[{"key":"A","text":"中華人民共和國中央人民政府"},{"key":"B","text":"中華人民共和國全國人民代表大會"},{"key":"C","text":"中華人民共和國最高人民法院"},{"key":"D","text":"中華人民共和國最高人民檢察院"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-5', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區享有：', '[{"key":"A","text":"行政管理權"},{"key":"B","text":"立法權"},{"key":"C","text":"獨立的司法權和終審權"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-6', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的行政機關是由下列哪類人士依法組成？', '[{"key":"A","text":"澳門特別行政區居民"},{"key":"B","text":"澳門特別行政區永久性居民"},{"key":"C","text":"澳門特別行政區非永久性居民"},{"key":"D","text":"任何人士"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-7', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區依法保障下列哪類人士的權利和自由？', '[{"key":"A","text":"澳門特別行政區居民和其他人"},{"key":"B","text":"澳門特別行政區居民"},{"key":"C","text":"其他人"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-8', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區保持原有的資本主義制度和生活方式：', '[{"key":"A","text":"二十年不變"},{"key":"B","text":"三十年不變"},{"key":"C","text":"四十年不變"},{"key":"D","text":"五十年不變"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-9', 'law', '根據《中華人民共和國澳門特別行政區基本法》，從澳門特別行政區境內的土地和自然資源取得的收入：', '[{"key":"A","text":"按比例歸中央人民政府支配"},{"key":"B","text":"少部分歸澳門特別行政區政府支配"},{"key":"C","text":"大部分歸澳門特別行政區政府支配"},{"key":"D","text":"以上皆不是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-10', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的正式語文為：', '[{"key":"A","text":"英文"},{"key":"B","text":"中文"},{"key":"C","text":"葡文"},{"key":"D","text":"中文及葡文"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-11', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區區旗繪有：', '[{"key":"A","text":"五星和桃花圖案"},{"key":"B","text":"五星、蓮花、大橋和海水圖案"},{"key":"C","text":"大橋和海水圖案"},{"key":"D","text":"蓮花、大橋和海水圖案"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第十條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-12', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區是中華人民共和國的一個享有高度自治權的地方行政區域，直轄於：', '[{"key":"A","text":"最高人民法院"},{"key":"B","text":"最高人民檢察院"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"以上皆是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-13', 'law', '根據《中華人民共和國澳門特別行政區基本法》，中央人民政府負責管理與澳門特別行政區有關的：', '[{"key":"A","text":"立法事務"},{"key":"B","text":"外交事務"},{"key":"C","text":"行政事務"},{"key":"D","text":"司法事務"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-14', 'law', '根據《中華人民共和國澳門特別行政區基本法》，中央人民政府負責管理澳門特別行政區的：', '[{"key":"A","text":"立法事務"},{"key":"B","text":"行政事務"},{"key":"C","text":"司法事務"},{"key":"D","text":"防務"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-15', 'law', '中央人民政府依照《中華人民共和國澳門特別行政區基本法》，任免澳門特別行政區：', '[{"key":"A","text":"行政長官"},{"key":"B","text":"政府主要官員"},{"key":"C","text":"檢察長"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-16', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的立法機關制定的法律須報下列哪個機關備案？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"終審法院院長"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"全國人民代表大會常務委員會"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-17', 'law', '根據《中華人民共和國澳門特別行政區基本法》，全國人民代表大會常務委員會在徵詢其所屬的下列哪個機關的意見後，如認為澳門特別行政區立法機關制定的任何法律不符合基本法關於中央和澳門特別行政區關係的條款，可將有關法律發回？', '[{"key":"A","text":"澳門特別行政區基本法委員會"},{"key":"B","text":"澳門特別行政區行政長官"},{"key":"C","text":"澳門特別行政區終審法院"},{"key":"D","text":"澳門特別行政區立法會"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第十七條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-18', 'law', '根據《中華人民共和國澳門特別行政區基本法》，下列哪些全國性法律在澳門特別行政區實施？', '[{"key":"A","text":"《中華人民共和國國旗法》"},{"key":"B","text":"《中華人民共和國領海及毗連區法》"},{"key":"C","text":"《中華人民共和國澳門特別行政區駐軍法》"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第十八條第二款、附件三', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-19', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區應自行立法禁止：', '[{"key":"A","text":"愛國行為"},{"key":"B","text":"團結國家行為"},{"key":"C","text":"叛國行為"},{"key":"D","text":"支持中央人民政府行為"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第二十三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-20', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區居民，簡稱澳門居民，包括：', '[{"key":"A","text":"永久性居民"},{"key":"B","text":"非永久性居民"},{"key":"C","text":"永久性居民和非永久性居民"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第二十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-21', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區永久性居民包括在澳門特別行政區成立：', '[{"key":"A","text":"以前在澳門出生的外國公民"},{"key":"B","text":"以前在澳門出生的中國公民"},{"key":"C","text":"以後在澳門出生的中國公民"},{"key":"D","text":"以前或以後在澳門出生的中國公民"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第二十四條第二款(一)項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-22', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區永久性居民在澳門特別行政區：', '[{"key":"A","text":"享有居留權"},{"key":"B","text":"有資格領取澳門特別行政區永久性居民身份證"},{"key":"C","text":"享有居留權並有資格領取澳門居民身份證"},{"key":"D","text":"享有居留權並有資格領取澳門特別行政區永久性居民身份證"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第二十四條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-23', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區非永久性居民在澳門特別行政區並不享有：', '[{"key":"A","text":"言論自由權"},{"key":"B","text":"結社自由權"},{"key":"C","text":"居留權"},{"key":"D","text":"集會自由權"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第二十四條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-24', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民在法律面前：', '[{"key":"A","text":"一律平等"},{"key":"B","text":"按血統而平等"},{"key":"C","text":"按國籍而平等"},{"key":"D","text":"按性別而平等"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第二十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-25', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區永久性居民依法享有：', '[{"key":"A","text":"選舉權"},{"key":"B","text":"被選舉權"},{"key":"C","text":"選舉權或被選舉權"},{"key":"D","text":"選舉權和被選舉權"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第二十六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-26', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區居民享有：', '[{"key":"A","text":"言論自由"},{"key":"B","text":"出版自由"},{"key":"C","text":"結社自由"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第二十七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-27', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民對任意或非法的監禁時，有權向法院申請頒發：', '[{"key":"A","text":"人身搜查令"},{"key":"B","text":"人身保護令"},{"key":"C","text":"禁止接觸令"},{"key":"D","text":"住所搜索令"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第二十八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-28', 'law', '澳門居民在被指控犯罪時，在法院判罪之前均假定：', '[{"key":"A","text":"有罪"},{"key":"B","text":"暫時有罪"},{"key":"C","text":"無罪"},{"key":"D","text":"暫時無罪"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第二十九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-29', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民的人格尊嚴不受侵犯。禁止用任何方法對居民進行：', '[{"key":"A","text":"侮辱"},{"key":"B","text":"誹謗"},{"key":"C","text":"誣告陷害"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第三十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-30', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民的住宅不受侵犯，禁止：', '[{"key":"A","text":"任意搜查"},{"key":"B","text":"非法搜查"},{"key":"C","text":"任意或非法搜查"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第三十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-31', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民的通訊自由和通訊秘密：', '[{"key":"A","text":"不受法律保護"},{"key":"B","text":"受法律保護"},{"key":"C","text":"得以任何理由受到侵犯"},{"key":"D","text":"不得以任何理由受到侵犯"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第三十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-32', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民有在澳門特別行政區境內：', '[{"key":"A","text":"遷徙的自由"},{"key":"B","text":"移居其他國家和地區的自由"},{"key":"C","text":"出入境的自由"},{"key":"D","text":"以上皆是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第三十三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-33', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民有：', '[{"key":"A","text":"宗教信仰的自由"},{"key":"B","text":"選擇職業和工作的自由"},{"key":"C","text":"從事學術研究的自由"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第三十四條第二款、第三十五條及第三十七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-34', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民為保護自己的合法權益，有權訴諸法律，向：', '[{"key":"A","text":"法院提起訴訟"},{"key":"B","text":"檢察院提起訴訟"},{"key":"C","text":"行政長官提起訴訟"},{"key":"D","text":"立法會提起訴訟"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第三十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-35', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門居民以下哪些權利受法律保護？', '[{"key":"A","text":"婚姻自由"},{"key":"B","text":"自願生育"},{"key":"C","text":"成立家庭"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第三十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-36', 'law', '根據《中華人民共和國澳門特別行政區基本法》，回歸後，《公民權利和政治權利國際公約》適用於澳門的有關規定：', '[{"key":"A","text":"不再有效"},{"key":"B","text":"繼續有效"},{"key":"C","text":"繼續有效，並通過澳門特別行政區的法律予以實施"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第四十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-37', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在澳門特別行政區境內的澳門居民以外的其他人：', '[{"key":"A","text":"依法享有基本法規定的澳門居民的權利和自由"},{"key":"B","text":"有遵守澳門特別行政區實行的法律的義務"},{"key":"C","text":"以上 A 或 B"},{"key":"D","text":"以上 A 及 B"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第四十三條及第四十四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-38', 'law', '根據《中華人民共和國澳門特別行政區基本法》，代表澳門特別行政區的行政長官，是澳門特別行政區的：', '[{"key":"A","text":"區長"},{"key":"B","text":"市長"},{"key":"C","text":"首長"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第四十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-39', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官，必須：', '[{"key":"A","text":"年滿四十周歲"},{"key":"B","text":"在澳門通常居住連續滿十年"},{"key":"C","text":"是澳門特別行政區非永久性居民"},{"key":"D","text":"以上皆是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第四十六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-40', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官的產生，是在澳門特別行政區通過：', '[{"key":"A","text":"選舉"},{"key":"B","text":"協商"},{"key":"C","text":"選舉或協商"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第四十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-41', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官：', '[{"key":"A","text":"任期十年，可連任一次"},{"key":"B","text":"任期十年，可連選連任"},{"key":"C","text":"任期五年，可連任一次"},{"key":"D","text":"任期五年，可連選連任"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第四十八條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-42', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官在任職期內：', '[{"key":"A","text":"可具有外國居留權，但不得從事私人贏利活動"},{"key":"B","text":"不得具有外國居留權，亦不得從事私人贏利活動"},{"key":"C","text":"可具有外國居留權，亦可從事私人贏利活動"},{"key":"D","text":"不得具有外國居留權，但可從事私人贏利活動"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第四十九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-43', 'law', '根據《中華人民共和國澳門特別行政區基本法》，下列哪一項是澳門特別行政區行政長官的職權？', '[{"key":"A","text":"領導澳門特別行政區政府"},{"key":"B","text":"簽署及通過法案"},{"key":"C","text":"制定法律並頒佈執行"},{"key":"D","text":"以上皆是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第五十條（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-44', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官遇有下列哪一情況時，可解散立法會？', '[{"key":"A","text":"行政長官拒絕簽署立法會首次通過的法案"},{"key":"B","text":"行政長官拒絕簽署立法會再次通過的法案"},{"key":"C","text":"行政長官拒絕簽署立法會第三次通過的法案"},{"key":"D","text":"以上皆不是"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第五十二條第一款(一)項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-45', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官如有下列哪一情況時必須辭職？', '[{"key":"A","text":"因嚴重疾病或其他原因無力履行職務"},{"key":"B","text":"因兩次拒絕簽署立法會通過的法案而解散立法會"},{"key":"C","text":"因立法會拒絕通過財政預算案"},{"key":"D","text":"因立法會拒絕通過關係到澳門特別行政區整體利益的法案"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第五十四條（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-46', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政長官短期不能履行職務時，臨時代理其職務的是：', '[{"key":"A","text":"司長"},{"key":"B","text":"局長"},{"key":"C","text":"廳長"},{"key":"D","text":"處長"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第五十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-47', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政會是：', '[{"key":"A","text":"命令行政長官決策的機構"},{"key":"B","text":"代替行政長官決策的機構"},{"key":"C","text":"協助行政長官決策的機構"},{"key":"D","text":"對抗行政長官決策的機構"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第五十六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-48', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政會的委員，從下列哪些人中委任？', '[{"key":"A","text":"政府主要官員"},{"key":"B","text":"立法會議員"},{"key":"C","text":"社會人士"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第五十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-49', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區行政會的會議，每月至少舉行：', '[{"key":"A","text":"一次"},{"key":"B","text":"兩次"},{"key":"C","text":"三次"},{"key":"D","text":"四次"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第五十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-50', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區廉政公署的廉政專員，對：', '[{"key":"A","text":"中共中央紀律檢查委員會負責"},{"key":"B","text":"最高人民檢察院負責"},{"key":"C","text":"中央人民政府負責"},{"key":"D","text":"以上皆不是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第五十九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-51', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區審計署的審計長，對：', '[{"key":"A","text":"終審法院院長負責"},{"key":"B","text":"立法會主席負責"},{"key":"C","text":"行政長官負責"},{"key":"D","text":"以上皆是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第六十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-52', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府是澳門特別行政區的：', '[{"key":"A","text":"司法機關"},{"key":"B","text":"立法機關"},{"key":"C","text":"行政機關"},{"key":"D","text":"行政及立法機關"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第六十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-53', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在架構上，澳門特別行政區政府由上而下依次設：', '[{"key":"A","text":"司、局、廳、處"},{"key":"B","text":"局、司、處、廳"},{"key":"C","text":"局、處、司、廳"},{"key":"D","text":"廳、處、司、局"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第六十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-54', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府的主要官員，必須：', '[{"key":"A","text":"在澳門通常居住連續滿十五年"},{"key":"B","text":"是澳門特別行政區永久性居民"},{"key":"C","text":"是中國公民"},{"key":"D","text":"同時符合以上條件"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第六十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-55', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區主要官員就任時，應向澳門特別行政區終審法院院長申報：', '[{"key":"A","text":"住址"},{"key":"B","text":"國籍"},{"key":"C","text":"財產"},{"key":"D","text":"刑事紀錄"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第六十三條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-56', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府行使的職權包括：', '[{"key":"A","text":"制定並執行政策"},{"key":"B","text":"管理各項行政事務"},{"key":"C","text":"提出法案、議案，草擬行政法規"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第六十四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-57', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府對澳門特別行政區立法會負責：', '[{"key":"A","text":"執行立法會未通過的法案"},{"key":"B","text":"不定期向立法會作施政報告"},{"key":"C","text":"答覆立法會議員的質詢"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第六十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-58', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區立法會是澳門特別行政區的：', '[{"key":"A","text":"行政與立法機關"},{"key":"B","text":"立法機關"},{"key":"C","text":"立法與司法機關"},{"key":"D","text":"司法與諮詢機關"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第六十七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-59', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區立法會議員應由下列哪類人士擔任？', '[{"key":"A","text":"澳門特別行政區永久性居民"},{"key":"B","text":"澳門特別行政區非永久性居民"},{"key":"C","text":"澳門居民"},{"key":"D","text":"澳門居民及其他人"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第六十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-60', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區立法會除第一屆另有規定外，每屆任期：', '[{"key":"A","text":"兩年"},{"key":"B","text":"三年"},{"key":"C","text":"四年"},{"key":"D","text":"五年"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第六十九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-61', 'law', '澳門特別行政區立法會如經行政長官依照《中華人民共和國澳門特別行政區基本法》解散，須於多長時間內依法重新產生？', '[{"key":"A","text":"三個月"},{"key":"B","text":"九十日"},{"key":"C","text":"六個月"},{"key":"D","text":"一百八十日"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第七十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-62', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區立法會行使的職權包括：', '[{"key":"A","text":"依法定程序制定、修改、暫停實施和廢除法律"},{"key":"B","text":"審核、通過政府提出的財政預算案"},{"key":"C","text":"就公共利益問題進行辯論"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第七十一條第一款(一)、(二)、(五)項', '["260","430"]');
