INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-69', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區立法會通過的法案，須經下列哪項程序，方能生效？', '[{"key":"A","text":"行政長官簽署"},{"key":"B","text":"公佈"},{"key":"C","text":"行政長官簽署或公佈"},{"key":"D","text":"行政長官簽署、公佈"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第七十八條', '["260","430"]');
