INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-95', 'law', '根據《中華人民共和國澳門特別行政區基本法》，財政上，澳門特別行政區保持：', '[{"key":"A","text":"財政獨立"},{"key":"B","text":"財政非獨立"},{"key":"C","text":"視情況保持財政獨立或非獨立"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百零四條第一款', '["260","430"]');
