INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-97', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的財政預算所遵循的原則是：', '[{"key":"A","text":"力求收支失衡"},{"key":"B","text":"量入為出"},{"key":"C","text":"尋求赤字"},{"key":"D","text":"與本地生產總值的增長率相抵觸"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第一百零五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-98', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區實行：', '[{"key":"A","text":"獨立的稅收制度"},{"key":"B","text":"半獨立的稅收制度"},{"key":"C","text":"視情況實行獨立或半獨立的稅收制度"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百零六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-99', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區的貨幣金融制度由：', '[{"key":"A","text":"行政法規規定"},{"key":"B","text":"批示規定"},{"key":"C","text":"法律規定"},{"key":"D","text":"行政法規及批示規定"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百零七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-100', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門元為澳門特別行政區的：', '[{"key":"A","text":"法定貨幣，繼續流通"},{"key":"B","text":"約定貨幣，可繼續流通"},{"key":"C","text":"法定貨幣，但不再流通"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百零八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-101', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門貨幣發行權屬於：', '[{"key":"A","text":"中央人民政府"},{"key":"B","text":"澳門特別行政區政府"},{"key":"C","text":"全國人民代表大會"},{"key":"D","text":"澳門特別行政區境內銀行"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第一百零九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-102', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在外匯政策上，澳門特別行政區不實行：', '[{"key":"A","text":"外匯管制政策"},{"key":"B","text":"外匯自由政策"},{"key":"C","text":"資金進出自由政策"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百零九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-103', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區保持自由港的地位：', '[{"key":"A","text":"不徵收關稅"},{"key":"B","text":"徵收關稅"},{"key":"C","text":"除法律另有規定外，不徵收關稅"},{"key":"D","text":"除法律另有規定外，徵收關稅"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百一十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-104', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區實行自由貿易政策，保障：', '[{"key":"A","text":"貨物的流動自由"},{"key":"B","text":"無形財產的流動自由"},{"key":"C","text":"資本的流動自由"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百一十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-105', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區為單獨的關稅地區，可以下列哪項名義參加有關國際組織和國際貿易協定？', '[{"key":"A","text":"中華人民共和國"},{"key":"B","text":"澳門特別行政區"},{"key":"C","text":"中國澳門"},{"key":"D","text":"澳門中國"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百一十二條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-106', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區根據當時的產地規則，可對產品簽發：', '[{"key":"A","text":"產品維修證"},{"key":"B","text":"產地來源證"},{"key":"C","text":"產品加工證"},{"key":"D","text":"以上皆不是"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第一百一十三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-107', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在勞工政策上，澳門特別行政區設立由下列哪些機構或實體的代表組成的諮詢性的協調組織？', '[{"key":"A","text":"政府"},{"key":"B","text":"僱主團體"},{"key":"C","text":"僱員團體"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百一十五條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-108', 'law', '根據《中華人民共和國澳門特別行政區基本法》，外國軍用船隻進入澳門特別行政區須經下列哪個機關的特別許可？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"立法會"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"全國人民代表大會"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百一十六條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-109', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區可自行制定民用航空的各項管理制度，但以：', '[{"key":"A","text":"經中央人民政府具體授權為限"},{"key":"B","text":"經行政長官具體授權為限"},{"key":"C","text":"經立法會具體授權為限"},{"key":"D","text":"經終審法院具體授權為限"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百一十七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-110', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區依法承認和保護澳門特別行政區成立前已批出或決定的年期超過一九九九年十二月十九日的：', '[{"key":"A","text":"合法土地契約"},{"key":"B","text":"任何土地契約"},{"key":"C","text":"與土地契約有關的一切權利"},{"key":"D","text":"合法土地契約和與土地契約有關的一切權利"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百二十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-111', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府依法推行義務教育，社會團體和私人：', '[{"key":"A","text":"不可舉辦各種教育事業"},{"key":"B","text":"可舉辦各種教育事業"},{"key":"C","text":"可依法舉辦各種教育事業"},{"key":"D","text":"以上皆不是"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百二十一條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-112', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區各類學校均有辦學的自主性，依法：', '[{"key":"A","text":"享有教學自由"},{"key":"B","text":"享有學術自由"},{"key":"C","text":"不享有教學自由和學術自由"},{"key":"D","text":"享有教學自由和學術自由"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百二十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-113', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在文化和社會事務上，澳門特別行政區政府自行制定：', '[{"key":"A","text":"促進醫療衛生服務和發展中西醫藥的政策"},{"key":"B","text":"科學技術政策"},{"key":"C","text":"文化政策"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百二十三條、第一百二十四條第一款及第一百二十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-114', 'law', '根據《中華人民共和國澳門特別行政區基本法》，在文化政策上，澳門特別行政區政府依法保護：', '[{"key":"A","text":"名勝"},{"key":"B","text":"古蹟和其他歷史文物"},{"key":"C","text":"文物所有者的合法權益"},{"key":"D","text":"以上皆是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百二十五條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-115', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府根據宗教信仰自由的原則：', '[{"key":"A","text":"不干預宗教組織的任何事務"},{"key":"B","text":"干預宗教組織同澳門以外地區的教徒保持及發展關係"},{"key":"C","text":"不限制與澳門特別行政區法律相抵觸的宗教活動"},{"key":"D","text":"以上皆不是"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百二十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-116', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府自行確定專業制度，在制定有關評審和頒授各種專業和執業資格的辦法時，必須根據：', '[{"key":"A","text":"公平原則"},{"key":"B","text":"合理原則"},{"key":"C","text":"公平合理的原則"},{"key":"D","text":"公平公開的原則"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百二十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-117', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府在原有社會福利制度的基礎上，根據下列哪項情況來自行制定有關社會福利政策？', '[{"key":"A","text":"經濟條件和社會需要"},{"key":"B","text":"批地數量"},{"key":"C","text":"賭收盈餘"},{"key":"D","text":"國際政治形勢"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百三十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-118', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區政府的代表，可作為中華人民共和國政府代表團的成員，參加由中央人民政府進行的同澳門特別行政區直接有關的：', '[{"key":"A","text":"行政管理事務"},{"key":"B","text":"外交談判"},{"key":"C","text":"立法事務"},{"key":"D","text":"司法事務"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第一百三十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-119', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區可以「中國澳門」的名義參加不以下列哪項為單位參加的國際組織和國際會議？', '[{"key":"A","text":"國家"},{"key":"B","text":"省"},{"key":"C","text":"直轄市"},{"key":"D","text":"經濟特區"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百三十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-120', 'law', '根據《中華人民共和國澳門特別行政區基本法》，中央人民政府授權澳門特別行政區政府依照法律給持有澳門特別行政區永久性居民身份證的中國公民簽發：', '[{"key":"A","text":"中華人民共和國護照"},{"key":"B","text":"澳門特別行政區護照"},{"key":"C","text":"其他旅行證件"},{"key":"D","text":"中華人民共和國澳門特別行政區護照"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百三十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-121', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區可根據需要在外國設立官方或半官方的經濟和貿易機構，報：', '[{"key":"A","text":"全國人民代表大會備案"},{"key":"B","text":"全國人民代表大會常務委員會備案"},{"key":"C","text":"中央人民政府備案"},{"key":"D","text":"最高人民法院備案"}]', 'C', '《中華人民共和國澳門特別行政區基本法》第一百四十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-122', 'law', '根據《中華人民共和國澳門特別行政區基本法》，已同中華人民共和國建立正式外交關係的國家在澳門設立的領事機構和其他官方機構：', '[{"key":"A","text":"可予保留"},{"key":"B","text":"不可保留"},{"key":"C","text":"視情況可予保留"},{"key":"D","text":"視情況不予保留"}]', 'A', '《中華人民共和國澳門特別行政區基本法》第一百四十二條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-123', 'law', '根據《中華人民共和國澳門特別行政區基本法》，尚未同中華人民共和國建立正式外交關係的國家在澳門設立的領事機構和其他官方機構，可根據情況：', '[{"key":"A","text":"不予保留"},{"key":"B","text":"予以保留"},{"key":"C","text":"改為半官方機構"},{"key":"D","text":"予以保留或改為半官方機構"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百四十二條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-124', 'law', '根據《中華人民共和國澳門特別行政區基本法》，尚未為中華人民共和國承認的國家，祇能在澳門特別行政區設立：', '[{"key":"A","text":"官方機構"},{"key":"B","text":"半官方機構"},{"key":"C","text":"官方機構或半官方機構"},{"key":"D","text":"民間機構"}]', 'D', '《中華人民共和國澳門特別行政區基本法》第一百四十二條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-basic-125', 'law', '根據《中華人民共和國澳門特別行政區基本法》，該法的解釋權及修改權，分別屬於：', '[{"key":"A","text":"全國人民代表大會及中央人民政府"},{"key":"B","text":"全國人民代表大會常務委員會及全國人民代表大會"},{"key":"C","text":"全國人民代表大會及澳門特別行政區基本法起草委員會"},{"key":"D","text":"中央人民政府及澳門特別行政區基本法起草委員會"}]', 'B', '《中華人民共和國澳門特別行政區基本法》第一百四十三條第一款、第一百四十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-1', 'law', '澳門特別行政區的《政府組織綱要法》，由澳門特別行政區：', '[{"key":"A","text":"行政長官制定"},{"key":"B","text":"立法會制定"},{"key":"C","text":"法院制定"},{"key":"D","text":"以上皆不是"}]', 'B', '第2/1999號法律首部分', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-2', 'law', '根據現行《政府組織綱要法》，澳門特別行政區政府是澳門特別行政區的：', '[{"key":"A","text":"行政、立法機關"},{"key":"B","text":"行政、司法機關"},{"key":"C","text":"立法、司法機關"},{"key":"D","text":"行政機關"}]', 'D', '第2/1999號法律第一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-3', 'law', '根據現行《政府組織綱要法》，澳門特別行政區行政長官是政府的首長，並領導：', '[{"key":"A","text":"政府"},{"key":"B","text":"法院"},{"key":"C","text":"立法會"},{"key":"D","text":"以上皆是"}]', 'A', '第2/1999號法律第二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-4', 'law', '根據現行《政府組織綱要法》，在架構上，澳門特別行政區政府由上而下依次序設：', '[{"key":"A","text":"司、局、處、廳"},{"key":"B","text":"局、廳、科、組"},{"key":"C","text":"廳、處、組、科"},{"key":"D","text":"司、局、廳、處"}]', 'D', '第2/1999號法律第三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-5', 'law', '根據現行《政府組織綱要法》，不屬於澳門特別行政區政府主要官員的是：', '[{"key":"A","text":"各司司長"},{"key":"B","text":"廉政專員"},{"key":"C","text":"立法會議員"},{"key":"D","text":"海關關長"}]', 'C', '第2/1999號法律第四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-6', 'law', '根據現行《政府組織綱要法》，澳門特別行政區政府各司的排列順序為：', '[{"key":"A","text":"行政法務司、保安司、經濟財政司、運輸工務司及社會文化司"},{"key":"B","text":"經濟財政司、社會文化司、保安司、行政法務司及運輸工務司"},{"key":"C","text":"社會文化司、運輸工務司、行政法務司、經濟財政司及保安司"},{"key":"D","text":"行政法務司、經濟財政司、保安司、社會文化司及運輸工務司"}]', 'D', '第2/1999號法律第五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-7', 'law', '根據現行《政府組織綱要法》，澳門特別行政區政府各司設司長：', '[{"key":"A","text":"一名"},{"key":"B","text":"兩名"},{"key":"C","text":"視情況設一名或兩名"},{"key":"D","text":"以上皆是"}]', 'A', '第2/1999號法律第五條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-8', 'law', '根據現行《政府組織綱要法》，澳門特別行政區設立下列哪些機構，獨立工作？', '[{"key":"A","text":"統一負責保安事務的警察部門"},{"key":"B","text":"中華人民共和國澳門特別行政區海關"},{"key":"C","text":"廉政公署、審計署"},{"key":"D","text":"以上皆是"}]', 'C', '第2/1999號法律第六條第一款、第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-9', 'law', '根據現行《政府組織綱要法》，澳門特別行政區行政長官由年滿四十週歲，在澳門通常居住連續滿多少年的澳門特別行政區永久性居民中的中國公民擔任？', '[{"key":"A","text":"五十年"},{"key":"B","text":"四十年"},{"key":"C","text":"三十年"},{"key":"D","text":"二十年"}]', 'D', '第2/1999號法律第七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-10', 'law', '根據現行《政府組織綱要法》，任命澳門特別行政區行政長官的是：', '[{"key":"A","text":"全國人民代表大會常務委員會"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"以上皆不是"}]', 'C', '第2/1999號法律第七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-11', 'law', '根據現行《政府組織綱要法》，澳門特別行政區行政長官依照《澳門特別行政區基本法》的規定，對：', '[{"key":"A","text":"中央人民政府負責"},{"key":"B","text":"全國人民代表大會負責"},{"key":"C","text":"澳門特別行政區負責"},{"key":"D","text":"中央人民政府和澳門特別行政區負責"}]', 'D', '第2/1999號法律第七條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-12', 'law', '根據現行《政府組織綱要法》，澳門特別行政區行政長官在任期内不得具有外國居留權：', '[{"key":"A","text":"但可從事私人贏利活動"},{"key":"B","text":"視情況可從事私人贏利活動"},{"key":"C","text":"不得從事私人贏利活動"},{"key":"D","text":"視情況不得從事私人贏利活動"}]', 'C', '第2/1999號法律第七條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-13', 'law', '根據現行《政府組織綱要法》，澳門特別行政區主要官員由在澳門通常居住連續滿十五年的哪些人擔任？', '[{"key":"A","text":"澳門居民"},{"key":"B","text":"澳門特別行政區永久性居民中的中國公民"},{"key":"C","text":"中國公民"},{"key":"D","text":"外國公民"}]', 'B', '第2/1999號法律第八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-14', 'law', '根據現行《政府組織綱要法》，提名澳門特別行政區主要官員的是：', '[{"key":"A","text":"行政長官"},{"key":"B","text":"立法會"},{"key":"C","text":"終審法院"},{"key":"D","text":"中央人民政府"}]', 'A', '第2/1999號法律第八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-15', 'law', '澳門特別行政區主要官員對：', '[{"key":"A","text":"中央人民政府負責"},{"key":"B","text":"全國人民代表大會負責"},{"key":"C","text":"澳門特別行政區負責"},{"key":"D","text":"行政長官負責"}]', 'D', '第2/1999號法律第八條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-16', 'law', '根據現行《政府組織綱要法》，下列哪一項不正確？', '[{"key":"A","text":"行政長官及主要官員自就任之日起履行職務"},{"key":"B","text":"行政長官休假期間終止職務"},{"key":"C","text":"如行政長官辭職，主要官員留任，直至新的主要官員就任"},{"key":"D","text":"行政長官於任期屆滿生效之日終止職務"}]', 'B', '第2/1999號法律第九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-17', 'law', '根據現行《政府組織綱要法》，行政長官及主要官員就任時須依法：', '[{"key":"A","text":"宣誓並申報財產"},{"key":"B","text":"宣誓"},{"key":"C","text":"申報財產"},{"key":"D","text":"申報健康狀況"}]', 'A', '第2/1999號法律第十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-18', 'law', '根據現行《政府組織綱要法》，行政長官短期不能履行職務時，依法定順序先由哪個司的司長臨時代理其職務？', '[{"key":"A","text":"保安司"},{"key":"B","text":"運輸工務司"},{"key":"C","text":"行政法務司"},{"key":"D","text":"社會文化司"}]', 'C', '第2/1999號法律第十一條第一款、第五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-19', 'law', '根據現行《政府組織綱要法》，行政長官出缺時，應在多長的時間內根據《澳門特別行政區基本法》的有關規定產生新的行政長官：', '[{"key":"A","text":"一百日"},{"key":"B","text":"一百二十日"},{"key":"C","text":"二百日"},{"key":"D","text":"二百二十日"}]', 'B', '第2/1999號法律第十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-20', 'law', '根據現行《政府組織綱要法》，代理行政長官在任期內：', '[{"key":"A","text":"不得具有外國居留權"},{"key":"B","text":"不得從事私人贏利活動"},{"key":"C","text":"不得具有外國居留權，但可從事私人贏利活動"},{"key":"D","text":"不得具有外國居留權，亦不得從事私人贏利活動"}]', 'D', '第2/1999號法律第十二條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-21', 'law', '根據現行《政府組織綱要法》，政府對立法會負責：', '[{"key":"A","text":"執行立法會通過但並未生效的法律"},{"key":"B","text":"每年至少向立法會作施政報告一次"},{"key":"C","text":"向法院提交財政預算案及預算執行情況報告"},{"key":"D","text":"任意答覆立法會議員的質詢"}]', 'B', '第2/1999號法律第十三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-22', 'law', '根據現行《政府組織綱要法》，行政長官向立法會宣讀：', '[{"key":"A","text":"施政理念"},{"key":"B","text":"施政指引"},{"key":"C","text":"施政報告"},{"key":"D","text":"施政措施"}]', 'C', '第2/1999號法律第十四條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-23', 'law', '根據現行《政府組織綱要法》，行政會是協助下列哪一機關決策的機構？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"立法會"},{"key":"C","text":"終審法院"},{"key":"D","text":"以上皆是"}]', 'A', '第2/1999號法律第十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-gov-24', 'law', '根據現行《政府組織綱要法》，政府可根據需要而設立的諮詢組織，除法規另有規定外，其意見：', '[{"key":"A","text":"具約束力"},{"key":"B","text":"不具約束力"},{"key":"C","text":"具普遍約束力"},{"key":"D","text":"以上皆不是"}]', 'B', '第2/1999號法律第十九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-1', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，行政法務司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"公共行政；市政事務"},{"key":"B","text":"財政預算；職業培訓"},{"key":"C","text":"社會工作；教育"},{"key":"D","text":"運輸及通訊；經濟房屋及社會房屋"}]', 'A', '第6/1999號行政法規第二條第一款（一）及（二）項', '["260","430"]');
