INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-5', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，保安司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"市政事務；民事及刑事身份資料"},{"key":"B","text":"澳門特別行政區的內部治安；刑事偵查"},{"key":"C","text":"工業、商業、博彩監察及離岸業務"},{"key":"D","text":"社會工作；旅遊"}]', 'B', '第6/1999號行政法規第四條第一款（一）及（二）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-6', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，保安司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"青年；社會重返"},{"key":"B","text":"消費者的保護；勞工及就業"},{"key":"C","text":"第2/2007號法律《違法青少年教育監管制度》所定範圍內的少年感化事務"},{"key":"D","text":"交通管理及航空器和港務"}]', 'C', '第6/1999號行政法規第四條第一款（八）項', '["260","430"]');
