INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-8', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，社會文化司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"統計；職業培訓；勞工及就業"},{"key":"B","text":"青年；社會保障；社會重返"},{"key":"C","text":"運輸及通訊；環境保護；氣象"},{"key":"D","text":"公共行政；市政事務；法律翻譯及法律推廣"}]', 'B', '第6/1999號行政法規第五條第一款（七）、（八）及（十）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-9', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，運輸工務司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"貨幣、匯兌及金融體系，包括保險業務"},{"key":"B","text":"出入境控制；民防；海上交通及有關罰則的監察"},{"key":"C","text":"衛生；旅遊；文化產業"},{"key":"D","text":"土地的整治；基礎建設及公共工程；氣象"}]', 'D', '第6/1999號行政法規第六條第一款（一）、（三）及（七）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-dept-10', 'law', '根據現行《政府部門及實體的組織、職權及運作》行政法規，運輸工務司司長在下列哪些施政領域行使職權？', '[{"key":"A","text":"公共行政；市政事務；《澳門特別行政區公報》的製作"},{"key":"B","text":"財政預算；統計；勞工及就業"},{"key":"C","text":"運輸及通訊；環境保護；經濟房屋及社會房屋"},{"key":"D","text":"刑事偵查；出入境控制；民防"}]', 'C', '第6/1999號行政法規第六條第一款（四）至（六）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-1', 'law', '第57/99/M號法令核准的《行政程序法典》所引進的重要更新，包括：', '[{"key":"A","text":"善意原則"},{"key":"B","text":"意思自治原則"},{"key":"C","text":"絕對公權力"},{"key":"D","text":"以上皆是"}]', 'A', '第57/99/M號法令前言', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-2', 'law', '根據現行《行政程序法典》，「為形成與表示公共行政當局意思，或為執行該意思而進行之一連串有序之行為及手續」是以下哪一項用語的定義？', '[{"key":"A","text":"行政行為"},{"key":"B","text":"行政卷宗"},{"key":"C","text":"行政程序"},{"key":"D","text":"行政合同"}]', 'C', '《行政程序法典》第一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-3', 'law', '根據現行《行政程序法典》，「行政卷宗」係指：', '[{"key":"A","text":"為形成與表示公共行政當局意思，或為執行該意思而進行之一連串有序之行為及手續"},{"key":"B","text":"體現組成行政程序之行為及手續之文件整體"},{"key":"C","text":"行政當局之機關之決定，其目的為在一個別具體情況中，依據公法之規定產生法律效果"},{"key":"D","text":"一合意，基於此合意而設定、變更或消滅一行政法律關係"}]', 'B', '《行政程序法典》第一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-4', 'law', '現行《行政程序法典》之規定，適用於：', '[{"key":"A","text":"從事公共管理行政活動時與私人建立關係之公共行政當局所有機關"},{"key":"B","text":"不屬公共行政當局之本地區機關在執行實質上之行政職務時所作屬行政事宜之行為"},{"key":"C","text":"被特許實體在行使當局權力時所作之行為"},{"key":"D","text":"以上皆是"}]', 'D', '《行政程序法典》第二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-5', 'law', '根據現行《行政程序法典》，合法性原則體現為：', '[{"key":"A","text":"行政機關有權限在尊重居民之權利及受法律保護之利益下，謀求公共利益"},{"key":"B","text":"公共行政當局之機關從事活動時，應使用澳門之正式語文"},{"key":"C","text":"公共行政當局機關之活動，應遵從法律及法且在該機關獲賦予之權力範圍內進行，並應符合將該等權力賦予該機關所擬達致之目的"},{"key":"D","text":"公共行政當局從事活動時，應以公正及無私方式，對待所有與其產生關係者"}]', 'C', '《行政程序法典》第三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-6', 'law', '根據現行《行政程序法典》，行政機關有權限在尊重居民之權利及受法律保護之利益下，謀求：', '[{"key":"A","text":"行政利益"},{"key":"B","text":"公共利益"},{"key":"C","text":"私人利益"},{"key":"D","text":"社團利益"}]', 'B', '《行政程序法典》第四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-7', 'law', '根據現行《行政程序法典》，與私人產生關係時，公共行政當局不得因被管理者之血統、性別、種族、語言、原居地、宗教、政治信仰、意識形態信仰、教育、經濟狀況或社會地位，而使之享有特權、受惠、受損害，或剝奪其任何權利或免除其任何義務的規定，是體現了：', '[{"key":"A","text":"平等原則"},{"key":"B","text":"適度原則"},{"key":"C","text":"善意原則"},{"key":"D","text":"公開原則"}]', 'A', '《行政程序法典》第五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-8', 'law', '根據現行《行政程序法典》，行政當局之決定與私人之權利或受法律保護之利益有衝突時，僅得在對所擬達致之目的屬甚麼情況下，損害該等權利或利益？', '[{"key":"A","text":"公平及平等"},{"key":"B","text":"合法"},{"key":"C","text":"善意"},{"key":"D","text":"適當及適度"}]', 'D', '《行政程序法典》第五條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-9', 'law', '根據現行《行政程序法典》，公共行政當局之機關從事活動時，應：', '[{"key":"A","text":"只使用中文"},{"key":"B","text":"只使用葡文"},{"key":"C","text":"使用澳門之正式語文"},{"key":"D","text":"使用澳門之正式語文及英文"}]', 'C', '《行政程序法典》第六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-10', 'law', '根據現行《行政程序法典》，公共行政當局從事活動時，應以甚麼方式，對待所有與其產生關係者？', '[{"key":"A","text":"公開及善意"},{"key":"B","text":"嚴謹及合法"},{"key":"C","text":"公正及無私"},{"key":"D","text":"公開及平等"}]', 'C', '《行政程序法典》第七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-11', 'law', '根據現行《行政程序法典》，在任何形式之行政活動中，以及在行政活動之任何階段，公共行政當局與私人均應依循甚麼規則行事及建立關係？', '[{"key":"A","text":"善意"},{"key":"B","text":"無私"},{"key":"C","text":"公正"},{"key":"D","text":"平等"}]', 'A', '《行政程序法典》第八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-12', 'law', '根據現行《行政程序法典》，公共行政當局須對以甚麼方式提供予私人之資訊負責，即使該等資訊非屬強制性提供亦然？', '[{"key":"A","text":"口頭"},{"key":"B","text":"書面"},{"key":"C","text":"電子通訊"},{"key":"D","text":"以上皆是"}]', 'B', '《行政程序法典》第九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-13', 'law', '根據現行《行政程序法典》，公共行政當局之機關，在形成與私人及以維護其利益為宗旨之團體有關之決定時，應確保私人及該等團體之：', '[{"key":"A","text":"保密"},{"key":"B","text":"隔離"},{"key":"C","text":"知悉"},{"key":"D","text":"參與"}]', 'D', '《行政程序法典》第十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-14', 'law', '根據現行《行政程序法典》，如有權限之機關對一私人提出之請求曾作出一行政行為，而該私人自該行政行為作出之日起多少年內以相同依據提出同一請求，則該機關無作出決定之義務？', '[{"key":"A","text":"一"},{"key":"B","text":"兩"},{"key":"C","text":"三"},{"key":"D","text":"四"}]', 'B', '《行政程序法典》第十一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-15', 'law', '根據現行《行政程序法典》，公共行政當局應以使部門親民為目的，且以非官僚化之方式，建立架構及運作，藉此確保其能以甚麼方式作出決定？', '[{"key":"A","text":"快捷、經濟及有效率"},{"key":"B","text":"詳盡及程序化"},{"key":"C","text":"快捷及友善"},{"key":"D","text":"經濟及高效"}]', 'A', '《行政程序法典》第十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-16', 'law', '根據現行《行政程序法典》，除特別法另有規定外，行政程序為：', '[{"key":"A","text":"有償"},{"key":"B","text":"無償"},{"key":"C","text":"因應利害關係人經濟狀況而定為有償或無償"},{"key":"D","text":"行政當局自由裁量為有償或無償"}]', 'B', '《行政程序法典》第十三條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-17', 'law', '根據現行《行政程序法典》，每一合議行政機關須設有：', '[{"key":"A","text":"一名主席及一名秘書"},{"key":"B","text":"一名主席、一名副主席及一名秘書"},{"key":"C","text":"一名主席及兩名秘書"},{"key":"D","text":"一名主席及一名副主席"}]', 'A', '《行政程序法典》第十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-18', 'law', '根據現行《行政程序法典》，在不影響有關授權及代任之規定的適用下，權限係由甚麼規定？', '[{"key":"A","text":"自由裁量"},{"key":"B","text":"規章"},{"key":"C","text":"規章或自由裁量"},{"key":"D","text":"法律或規章"}]', 'D', '《行政程序法典》第三十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-19', 'law', '根據現行《行政程序法典》，通常有權限對某項事宜作出決定之行政機關，得透過甚麼行為，容許另一機關或行政當局人員作出關於該事宜之行政行為？', '[{"key":"A","text":"委託行為"},{"key":"B","text":"授權行為"},{"key":"C","text":"協商行為"},{"key":"D","text":"命令行為"}]', 'B', '《行政程序法典》第三十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-20', 'law', '根據現行《行政程序法典》，授權行為或轉授權行為須公布於：', '[{"key":"A","text":"澳門地區的中文及葡文報章"},{"key":"B","text":"《澳門政府公報》"},{"key":"C","text":"澳門特區政府官方網頁"},{"key":"D","text":"以上皆是"}]', 'B', '《行政程序法典》第三十九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-21', 'law', '以下哪一情況不屬於現行《行政程序法典》規定公共行政當局之機關據位人或人員必須迴避之情況？', '[{"key":"A","text":"其本人，或因身為他人之代理人或無因管理人，就行政程序、行政行為或行政合同有利害關係"},{"key":"B","text":"其配偶、直系血親或姻親、二親等內之旁系血親或姻親、任何與其在共同經濟下生活之人，曾以鑑定人或受任人之身分參與行政程序"},{"key":"C","text":"利害關係人或其配偶提起司法訴訟，針對相關的機關據位人或人員、其配偶或直系血親"},{"key":"D","text":"如該機關據位人或人員，又或其配偶，與就該程序、行為或合同有直接利害關係之人嚴重交惡或存有極親密之關係"}]', 'D', '《行政程序法典》第四十六條第一款 a、e 及 f 項，以及第五十條第1款 d 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-22', 'law', '根據現行《行政程序法典》，行政程序中使用的正式語文是：', '[{"key":"A","text":"中文"},{"key":"B","text":"葡文"},{"key":"C","text":"中文或葡文"},{"key":"D","text":"中文及葡文"}]', 'C', '《行政程序法典》第五十六條第一款、《基本法》第九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-23', 'law', '根據現行《行政程序法典》，除法律另定期間，或因特殊情節而須另定期間者，行政程序應在多少日內完成？', '[{"key":"A","text":"三十"},{"key":"B","text":"六十"},{"key":"C","text":"九十"},{"key":"D","text":"一百二十日"}]', 'C', '《行政程序法典》第六十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-24', 'law', '根據現行《行政程序法典》，利害關係人的一般義務包括：', '[{"key":"A","text":"不提出違法要求"},{"key":"B","text":"不陳述與真相不符之事實"},{"key":"C","text":"不申請採取純為拖延之措施"},{"key":"D","text":"以上皆是"}]', 'D', '《行政程序法典》第六十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-25', 'law', '下列哪項不屬於現行《行政程序法典》規定不得向利害關係人提供的程序上之文書或資料？', '[{"key":"A","text":"依法列為機密或秘密之文書或資料，而該項歸類尚未為有權限之實體撤除者"},{"key":"B","text":"某些程序上之文書或資料，如其為利害關係人所知悉，係可能影響有關程序之主要目的或損害他人之基本權利者"},{"key":"C","text":"行政卷宗所在之部門已作出之行為及決定"},{"key":"D","text":"以上皆不屬於"}]', 'C', '《行政程序法典》第六十三條第二款及第三款 a 項及 b 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-26', 'law', '根據現行《行政程序法典》，在利害關係人提出要求之資訊後，相關部門最遲應在多少日內提供？', '[{"key":"A","text":"十個工作日"},{"key":"B","text":"十個自然日"},{"key":"C","text":"十五個工作日"},{"key":"D","text":"十五個自然日"}]', 'A', '《行政程序法典》第六十三條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-27', 'law', '根據現行《行政程序法典》，未有特別定出期間時，行政行為之通知應在多少日內作出？', '[{"key":"A","text":"七"},{"key":"B","text":"八"},{"key":"C","text":"九"},{"key":"D","text":"十"}]', 'B', '《行政程序法典》第七十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-28', 'law', '根據現行《行政程序法典》，如無特別規定，或行政當局無定出期間，行政機關作出行為之期間為：', '[{"key":"A","text":"七日"},{"key":"B","text":"十四日"},{"key":"C","text":"十五日"},{"key":"D","text":"二十日"}]', 'C', '《行政程序法典》第七十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-29', 'law', '以下哪項不符合現行《行政程序法典》規定的期間之計算所適用的規則？', '[{"key":"A","text":"期間自某事件發生之日起開始進行者，該日不計算在內"},{"key":"B","text":"期間連續進行，且不論有否任何手續，期間均開始進行"},{"key":"C","text":"如期間屆滿之日部門不向公眾開放，或屬正常工作期間而部門不運作者，則其後第一個工作日方為期間屆滿之日"},{"key":"D","text":"以政府公共部門辦公日子為期間計算的日子"}]', 'D', '《行政程序法典》第七十四條 a 項至 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-30', 'law', '根據現行《行政程序法典》，如無特別規定，意見書須在多少日期間內發出？', '[{"key":"A","text":"三十"},{"key":"B","text":"五十"},{"key":"C","text":"六十"},{"key":"D","text":"九十"}]', 'A', '《行政程序法典》第九十二條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-31', 'law', '根據現行《行政程序法典》，在無特別法規定下，在為作出決定而定之期間內，如有權限之行政機關未對向其提出之要求作出最終決定，則賦予利害關係人甚麼權能，以便其得使用有關之法定申訴方法？', '[{"key":"A","text":"推定該要求獲默示批准之權能"},{"key":"B","text":"推定該要求仍然待決之權能"},{"key":"C","text":"推定該要求被駁回之權能"},{"key":"D","text":"推定該要求因程序消滅而不生任何效果之權能"}]', 'C', '《行政程序法典》第一百零二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-32', 'law', '根據現行《行政程序法典》，「行政當局之機關之決定，其目的為在一個別具體情況中，依據公法之規定產生法律效果」是以下哪個用語的概念？', '[{"key":"A","text":"行政行為"},{"key":"B","text":"行政卷宗"},{"key":"C","text":"行政程序"},{"key":"D","text":"行政合同"}]', 'A', '《行政程序法典》第一百一十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-33', 'law', '根據現行《行政程序法典》，以下哪項不是行政行為內必須提及的內容？', '[{"key":"A","text":"作出該行為之當局"},{"key":"B","text":"作出該行為之當局辦事處地址"},{"key":"C","text":"相對人或各相對人之適當認別資料"},{"key":"D","text":"作出該行為之日期"}]', 'B', '《行政程序法典》第一百一十三條第一款 a、c 及 g 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-34', 'law', '根據現行《行政程序法典》，如法律規定須將行政行為公布，但未規範公布之方式，則應在三十日期間內將之公布於：', '[{"key":"A","text":"澳門特別行政區最多人閱讀的中文報章"},{"key":"B","text":"澳門地特別行政區最多人閱讀的葡文報章"},{"key":"C","text":"《澳門政府公報》"},{"key":"D","text":"澳門特別行政區政府入口網站"}]', 'C', '《行政程序法典》第一百二十條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-35', 'law', '根據現行《行政程序法典》，欠缺任何主要要素之行政行為是：', '[{"key":"A","text":"無效之行政行為"},{"key":"B","text":"可撤銷之行政行為"},{"key":"C","text":"不規則的行政行為"},{"key":"D","text":"不存在的行政行為"}]', 'A', '《行政程序法典》第一百二十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-36', 'law', '根據現行《行政程序法典》，行政行為的執行得以下列哪項為目的？', '[{"key":"A","text":"支付一定金額"},{"key":"B","text":"交付一定之物"},{"key":"C","text":"作出一事實"},{"key":"D","text":"以上皆是"}]', 'D', '《行政程序法典》第一百四十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-37', 'law', '根據現行《行政程序法典》，私人提出聲明異議時，是向：', '[{"key":"A","text":"對作出行為者行使監督權或監管權之機關提出"},{"key":"B","text":"作出行為者提出"},{"key":"C","text":"作出行為者之上級，又或向授權者或轉授權者提出"},{"key":"D","text":"作出行為者所屬之合議機關，又或向授權者或轉授權者提出"}]', 'B', '《行政程序法典》第一百四十五條第二款 a 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-38', 'law', '根據現行《行政程序法典》，除另有規定者外，聲明異議及上訴得以下列哪一項為依據？', '[{"key":"A","text":"被申訴之行政行為違法或不當"},{"key":"B","text":"被申訴之行政行為違法及不當"},{"key":"C","text":"被申訴之行政行為之結果與利害關係人提出之要求全部或部分相反"},{"key":"D","text":"被申訴之行政行為課予利害關係人義務"}]', 'A', '《行政程序法典》第一百四十六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-39', 'law', '根據現行《行政程序法典》，聲明異議應自期間開始計算時起多少日內提出？', '[{"key":"A","text":"十"},{"key":"B","text":"十四"},{"key":"C","text":"十五"},{"key":"D","text":"二十一"}]', 'C', '《行政程序法典》第一百四十九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-40', 'law', '根據現行《行政程序法典》，有權限之機關對聲明異議作出審查及決定之期間為：', '[{"key":"A","text":"十五日"},{"key":"B","text":"三十日"},{"key":"C","text":"六十日"},{"key":"D","text":"九十日"}]', 'A', '《行政程序法典》第一百五十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-41', 'law', '根據現行《行政程序法典》，如法律未另定期間，則提起必要訴願之期間為：', '[{"key":"A","text":"十五日"},{"key":"B","text":"三十日"},{"key":"C","text":"四十五日"},{"key":"D","text":"六十日"}]', 'B', '《行政程序法典》第一百五十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-42', 'law', '以下哪項不屬現行《行政程序法典》規定應拒絕受理訴願的情況？', '[{"key":"A","text":"向作出行為者之上級提起"},{"key":"B","text":"對不可提起訴願之行為提出申訴"},{"key":"C","text":"訴願人不具正當性"},{"key":"D","text":"逾期提起訴願"}]', 'A', '《行政程序法典》第一百六十條 b 至 d 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-43', 'law', '根據現行《行政程序法典》，法律未另定期間時，有權限審理訴願之機關應自收到有關卷宗之時起多少日內，就訴願作出決定？', '[{"key":"A","text":"一百二十"},{"key":"B","text":"九十"},{"key":"C","text":"六十"},{"key":"D","text":"三十"}]', 'D', '《行政程序法典》第一百六十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-44', 'law', '根據現行《行政程序法典》，一機關對屬同一法人之另一機關行使監管權，而兩者並無行政等級關係時，向行使監管權之機關所提起之訴願，視為：', '[{"key":"A","text":"監督上訴"},{"key":"B","text":"不真正訴願"},{"key":"C","text":"必要訴願"},{"key":"D","text":"任意訴願"}]', 'B', '《行政程序法典》第一百六十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-45', 'law', '根據現行《行政程序法典》，監督上訴之標的為：', '[{"key":"A","text":"受其他機關之等級權力拘束之機關所作出之一切行政行為，如法律不排除對此等行政行為提起訴願之可能"},{"key":"B","text":"任何行政行為"},{"key":"C","text":"受監督或監管之公法人所作之行政行為"},{"key":"D","text":"以上皆是"}]', 'C', '《行政程序法典》第一百六十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-46', 'law', '根據現行《行政程序法典》，行政合同尤其包括：', '[{"key":"A","text":"公共工程承攬合同"},{"key":"B","text":"公共事業特許合同"},{"key":"C","text":"繼續供應合同"},{"key":"D","text":"以上皆是"}]', 'D', '《行政程序法典》第一百六十五條第二款 a、c 及 e 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-47', 'law', '以下哪一合同，不屬現行《行政程序法典》規定的行政合同？', '[{"key":"A","text":"公共工程特許合同"},{"key":"B","text":"博彩經營特許合同"},{"key":"C","text":"個人勞動合同"},{"key":"D","text":"為直接公益提供勞務之合同"}]', 'C', '《行政程序法典》第一百六十五條第二款 b、d 及 f 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-proc-48', 'law', '根據現行《行政程序法典》，除特別制度規定外，應透過甚麼方式選擇共同訂立合同人？', '[{"key":"A","text":"公開競投"},{"key":"B","text":"限制性競投"},{"key":"C","text":"直接磋商"},{"key":"D","text":"以上皆是"}]', 'D', '《行政程序法典》第一百六十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-1', 'law', '現行《澳門公共行政工作人員通則》適用於包括下列哪一項在內之澳門行政當局公共部門之人員？', '[{"key":"A","text":"私人團體及自治機關"},{"key":"B","text":"自治機關及自治基金組織"},{"key":"C","text":"私人團體及自治基金組織"},{"key":"D","text":"以上皆是"}]', 'B', '《澳門公共行政工作人員通則》第一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-2', 'law', '為適用現行《澳門公共行政工作人員通則》的規定，視為公共行政工作人員的是：', '[{"key":"A","text":"公務員及服務人員"},{"key":"B","text":"公務員"},{"key":"C","text":"服務人員"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-3', 'law', '除有特別規定外，實施現行《澳門公共行政工作人員通則》所規定之行為屬：', '[{"key":"A","text":"總督之權限"},{"key":"B","text":"立法會主席之權限"},{"key":"C","text":"行政長官之權限"},{"key":"D","text":"終審法院院長之權限"}]', 'C', '《澳門公共行政工作人員通則》第四條第一款、《回歸法》附件四(四)', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-4', 'law', '根據現行《澳門公共行政工作人員通則》，行政當局每一工作人員之個人檔案內應載明：', '[{"key":"A","text":"與他人之職務狀況有關之一切事實"},{"key":"B","text":"與上級之健康狀況有關之文件"},{"key":"C","text":"與工作人員之職務狀況、義務及權利有關之一切事實及文件"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第八條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-5', 'law', '根據現行《澳門公共行政工作人員通則》，如公務員或服務人員暫時被安排到另一部門工作，該部門應儘快將一切須記入個人檔案之事實通知：', '[{"key":"A","text":"原部門"},{"key":"B","text":"行政長官"},{"key":"C","text":"立法會主席"},{"key":"D","text":"終審法院院長"}]', 'A', '《澳門公共行政工作人員通則》第八條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-6', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪一項不是擔任公共職務之一般要件？', '[{"key":"A","text":"學歷資格或專業資格"},{"key":"B","text":"未成年"},{"key":"C","text":"任職能力"},{"key":"D","text":"身體健康及精神健全"}]', 'B', '《澳門公共行政工作人員通則》第十條第一款b項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-7', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪種性質為主之職務，得例外錄取非中國籍或葡國籍之工作人員，但不包括領導及主管職務？', '[{"key":"A","text":"技術"},{"key":"B","text":"學術"},{"key":"C","text":"教學"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第十條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-8', 'law', '根據現行《澳門公共行政工作人員通則》，除另有訂定之特別年齡限制外，錄取進入公職編制的年齡限制：', '[{"key":"A","text":"最低為十八歲，最高為五十歲"},{"key":"B","text":"最低為十七歲，最高為六十歲"},{"key":"C","text":"最低為十六歲，最高為七十歲"},{"key":"D","text":"最低為十五歲，最高為八十歲"}]', 'A', '《澳門公共行政工作人員通則》第十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-9', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪一項者不具備擔任公共職務之能力？', '[{"key":"A","text":"被認為不具備擔任公共職務之能力者"},{"key":"B","text":"不得兼任或兼任之規定所包括者"},{"key":"C","text":"處於短期無薪假狀況之公務員"},{"key":"D","text":"以上者皆不具備"}]', 'D', '《澳門公共行政工作人員通則》第十三條第一款c、e及a項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-10', 'law', '根據現行《澳門公共行政工作人員通則》，公共職務的任用之特別要件由：', '[{"key":"A","text":"專有法律訂定"},{"key":"B","text":"行政法規訂定"},{"key":"C","text":"行政長官批示訂定"},{"key":"D","text":"行政命令訂定"}]', 'A', '《澳門公共行政工作人員通則》第十四條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-11', 'law', '根據現行《澳門公共行政工作人員通則》，如屬開考之情況，投考人應在開考通告規定之報考期限屆滿前具備擔任公共職務之：', '[{"key":"A","text":"一般要件"},{"key":"B","text":"特別要件"},{"key":"C","text":"一般要件或特別要件"},{"key":"D","text":"一般要件及特別要件"}]', 'D', '《澳門公共行政工作人員通則》第十五條前部份', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-12', 'law', '根據現行《澳門公共行政工作人員通則》，在不遵守學歷資格或專業資格要件之情況下作出之任用：', '[{"key":"A","text":"無效"},{"key":"B","text":"可予撤銷"},{"key":"C","text":"不產生效力"},{"key":"D","text":"不存在"}]', 'A', '《澳門公共行政工作人員通則》第十六條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-13', 'law', '根據現行《澳門公共行政工作人員通則》，擔任公共職務須遵守：', '[{"key":"A","text":"專職性原則"},{"key":"B","text":"兼職性原則"},{"key":"C","text":"半專職性原則"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-14', 'law', '根據現行《澳門公共行政工作人員通則》，在下列哪一情況下容許工作人員兼任公共職務或職位？', '[{"key":"A","text":"私人業務"},{"key":"B","text":"職業培訓活動"},{"key":"C","text":"教學活動，不論在時間上是否抵觸"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-15', 'law', '根據現行《澳門公共行政工作人員通則》，當然兼任係指：', '[{"key":"A","text":"擔任一公共職務時，因行政法規之規定而必須擔任另一職務"},{"key":"B","text":"擔任一公共職務時，因法律之規定而必須擔任另一職務"},{"key":"C","text":"擔任一公共職務時，因批示之規定而必須擔任另一職務"},{"key":"D","text":"以上皆是"}]', 'B', '《澳門公共行政工作人員通則》第十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-16', 'law', '根據現行《澳門公共行政工作人員通則》，擔任當然兼任之職務係一項源自主職務之：', '[{"key":"A","text":"權利"},{"key":"B","text":"義務"},{"key":"C","text":"權利或義務"},{"key":"D","text":"權利和義務"}]', 'B', '《澳門公共行政工作人員通則》第十八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-17', 'law', '根據現行《澳門公共行政工作人員通則》，除領導及主管人員外，進入編制內之職位，在多少時間內屬於臨時性質？', '[{"key":"A","text":"六個月內"},{"key":"B","text":"一年內"},{"key":"C","text":"兩年內"},{"key":"D","text":"三年內"}]', 'C', '《澳門公共行政工作人員通則》第二十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-18', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪一項屬公務員之調動方式？', '[{"key":"A","text":"調任"},{"key":"B","text":"派駐"},{"key":"C","text":"徵用"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第三十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-19', 'law', '根據現行《澳門公共行政工作人員通則》，就職行為屬：', '[{"key":"A","text":"公開行為"},{"key":"B","text":"親身行為"},{"key":"C","text":"公開及親身行為"},{"key":"D","text":"公開或親身行為"}]', 'C', '《澳門公共行政工作人員通則》第三十五條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-20', 'law', '根據現行《澳門公共行政工作人員通則》，在下列哪一項情況下，須進行就職？', '[{"key":"A","text":"臨時委任"},{"key":"B","text":"任何情況中之定期委任"},{"key":"C","text":"任何情況中之確定委任"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第三十六條第一款a項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-21', 'law', '根據現行《澳門公共行政工作人員通則》，與人員有關且影響其職務上之法律狀況之一切行為，均應由有關部門在十五日內通知：', '[{"key":"A","text":"行政公職局"},{"key":"B","text":"法務局"},{"key":"C","text":"財政局"},{"key":"D","text":"身份證明局"}]', 'A', '《澳門公共行政工作人員通則》第三十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-22', 'law', '根據現行《澳門公共行政工作人員通則》，除特殊情況而另有規定外，澳門公共行政工作人員每周工作：', '[{"key":"A","text":"三十小時"},{"key":"B","text":"三十二小時"},{"key":"C","text":"三十六小時"},{"key":"D","text":"三十八小時"}]', 'C', '《澳門公共行政工作人員通則》第七十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-23', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員必須嚴格遵守每日辦公時間。每日或每周遲到超過多少分鐘，須作不合理缺勤紀錄？', '[{"key":"A","text":"每日十五分鐘或每周三十分鐘"},{"key":"B","text":"每日二十分鐘或每周四十分鐘"},{"key":"C","text":"每日三十分鐘或每周六十分鐘"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第七十八條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-24', 'law', '根據現行《澳門公共行政工作人員通則》，工作時間制度可分為一般制度和特別制度，下列哪項屬特別工作時間制度？', '[{"key":"A","text":"彈性工作時間"},{"key":"B","text":"輪值工作"},{"key":"C","text":"特定工作時間"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第七十八條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-25', 'law', '根據現行《澳門公共行政工作人員通則》，除法律另有規定外，年假權屬不可放棄之權利，而年假權之實際享受：', '[{"key":"A","text":"不得以任何金錢補償代替"},{"key":"B","text":"得以相應日數之報酬補償代替"},{"key":"C","text":"得以雙倍之報酬補償代替"},{"key":"D","text":"得以其他津貼補償代替"}]', 'A', '《澳門公共行政工作人員通則》第八十條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-26', 'law', '根據現行《澳門公共行政工作人員通則》，以下有關年假之效力的表述中，正確的是：', '[{"key":"A","text":"在年假期間，工作人員無權收取實際服務時有權收取之報酬"},{"key":"B","text":"在年假期間，工作人員絕對不得從事任何有報酬之活動"},{"key":"C","text":"在年假期間，工作人員不得從事任何有報酬之活動，但屬一直依法從事之活動除外"},{"key":"D","text":"在年假期間，工作人員喪失相應之權利或福利"}]', 'C', '《澳門公共行政工作人員通則》第八十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-27', 'law', '根據現行《澳門公共行政工作人員通則》，基於適當說明理由的工作需要並經由部門領導批准，可將已到期及累積的最多多少個工作日的年假轉移至下一曆年享受？', '[{"key":"A","text":"十一個工作日"},{"key":"B","text":"二十二個工作日"},{"key":"C","text":"三十三個工作日"},{"key":"D","text":"四十四個工作日"}]', 'C', '《澳門公共行政工作人員通則》第八十三條第七款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-28', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪些情況視為不合理缺勤？', '[{"key":"A","text":"基於該通則未有規定之原因而缺勤"},{"key":"B","text":"未根據該通則之規定作出合理解釋之缺勤"},{"key":"C","text":"須取決於領導接受與否之缺勤，而該領導認為工作人員所援引之理由不充分時"},{"key":"D","text":"以上皆視為不合理缺勤"}]', 'D', '《澳門公共行政工作人員通則》第九十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-29', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員不合理缺勤除導致法定之紀律後果外，尚導致以下哪一後果？', '[{"key":"A","text":"喪失相應於缺勤日數之報酬"},{"key":"B","text":"缺勤日數不計入為年資之效力而計算之服務時間內"},{"key":"C","text":"在該曆年之年假中扣除缺勤之日數"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第九十條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-30', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因結婚而缺勤，應在缺勤開始前最少提早多少日以書面方式作出通知，並應在締結婚姻後多少日內出示有關證明以證明結婚之事實？', '[{"key":"A","text":"十五日；三十日"},{"key":"B","text":"十日；三十日"},{"key":"C","text":"十五日；二十日"},{"key":"D","text":"十日；二十日"}]', 'A', '《澳門公共行政工作人員通則》第九十一條第二款及第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-31', 'law', '根據現行《澳門公共行政工作人員通則》，女性工作人員有權因分娩而缺勤多少日，且其中多少日須在分娩後立即享受？', '[{"key":"A","text":"九十日；三十日"},{"key":"B","text":"九十日；六十日"},{"key":"C","text":"六十日；三十日"},{"key":"D","text":"六十日；二十日"}]', 'B', '《澳門公共行政工作人員通則》第九十二條第一款及第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-32', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因成為父親而缺勤應在何時作出缺勤通知，並應出示出生證明，作為缺勤之合理解釋？', '[{"key":"A","text":"發生缺勤當日"},{"key":"B","text":"發生缺勤後三日內"},{"key":"C","text":"發生缺勤後五日內"},{"key":"D","text":"發生缺勤後五個工作日內"}]', 'A', '《澳門公共行政工作人員通則》第九十三條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-33', 'law', '根據現行《澳門公共行政工作人員通則》，在符合法定情況下，工作人員因收養初生嬰兒而有權連續缺勤：', '[{"key":"A","text":"十日"},{"key":"B","text":"二十日"},{"key":"C","text":"三十日"},{"key":"D","text":"四十日"}]', 'C', '《澳門公共行政工作人員通則》第九十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-34', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因成為母親、成為父親及收養而缺勤，應以主診醫生或醫院之聲明，又或以具足夠證明力之文件作合理解釋。有關聲明或文件須在何時呈交予工作人員任職之部門？', '[{"key":"A","text":"緊接缺勤當日之第一個工作日結束前"},{"key":"B","text":"緊接缺勤當日之第二個工作日結束前"},{"key":"C","text":"緊接缺勤當日之第三個工作日結束前"},{"key":"D","text":"緊接缺勤當日之第四個工作日結束前"}]', 'B', '《澳門公共行政工作人員通則》第九十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-35', 'law', '根據現行《澳門公共行政工作人員通則》，如工作人員因親屬死亡而缺勤，應在何時將缺勤通知部門？', '[{"key":"A","text":"缺勤開始之日"},{"key":"B","text":"緊接缺勤當日之第一個工作日"},{"key":"C","text":"缺勤期間任何時間"},{"key":"D","text":"返回部門上班時"}]', 'A', '《澳門公共行政工作人員通則》第九十六條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-36', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員如在每一曆年內因病缺勤之日數連續或間斷超過多少日，須自為職級及職程之效力而計算之年資內扣除超出之缺勤日數？', '[{"key":"A","text":"十日"},{"key":"B","text":"十五日"},{"key":"C","text":"二十日"},{"key":"D","text":"三十日"}]', 'D', '《澳門公共行政工作人員通則》第九十七條第六款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-37', 'law', '根據現行《澳門公共行政工作人員通則》，除法例另有規定，公共部門最遲應於何時完成因病缺勤而扣除在職薪俸的程序？', '[{"key":"A","text":"每年三月底前"},{"key":"B","text":"每年六月底前"},{"key":"C","text":"每年九月底前"},{"key":"D","text":"每年十二月底前"}]', 'B', '《澳門公共行政工作人員通則》第九十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-38', 'law', '根據現行《澳門公共行政工作人員通則》，作為合理解釋，工作人員因病缺勤可呈交：', '[{"key":"A","text":"住院及休養聲明"},{"key":"B","text":"醫院探病證明"},{"key":"C","text":"出入境紀錄證明"},{"key":"D","text":"出生證明"}]', 'A', '《澳門公共行政工作人員通則》第一百條 b 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-39', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因病缺勤而呈交之醫生檢查證明須以專用印件發出，並應在何時遞交予工作人員任職之部門？', '[{"key":"A","text":"緊接缺勤當日之第一個工作日結束前"},{"key":"B","text":"緊接缺勤當日之第二個工作日結束前"},{"key":"C","text":"緊接缺勤當日之第三個工作日結束前"},{"key":"D","text":"緊接缺勤當日之第四個工作日結束前"}]', 'B', '《澳門公共行政工作人員通則》第一百零一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-40', 'law', '根據現行《澳門公共行政工作人員通則》，有關工作人員因病缺勤的規定，以下表述中正確的是：', '[{"key":"A","text":"除病人住院之情況外，部門領導得隨時要求專責醫生或澳門衛生局到病人家中核實病況"},{"key":"B","text":"如疾病不引致患病者必須留在家中，應在工作人員連同醫生檢查證明一併遞交之聲明上所指之地點、日期及時間進行病況核實"},{"key":"C","text":"如屬工作人員住院之情況，應以有關醫院發出之住院聲明，作為因病缺勤之合理解釋"},{"key":"D","text":"以上皆正確"}]', 'D', '《澳門公共行政工作人員通則》第一百零二條第一款、第二款及第一百零三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-41', 'law', '根據現行《澳門公共行政工作人員通則》，除在醫院留醫外，在下列哪種情況中，工作人員應接受由部門領導要求協助之健康檢查委員會之檢查？', '[{"key":"A","text":"根據該通則之規定證實患病而缺勤達三十日"},{"key":"B","text":"不論缺勤日數多少，病人之行為顯示有欺詐成分"},{"key":"C","text":"工作人員之行為未顯示有影響其正常擔任職務之身體或精神紊亂"},{"key":"D","text":"以上皆是"}]', 'B', '《澳門公共行政工作人員通則》第一百零四條第一款 b 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-42', 'law', '根據現行《澳門公共行政工作人員通則》，除通則規定的特定疾病外，如健康檢查委員會認為工作人員不適宜工作，得連續批給以多少日為一期之因病缺勤期，但不得超過多長時間？', '[{"key":"A","text":"三十日；十八個月"},{"key":"B","text":"六十日；十八個月"},{"key":"C","text":"三十日；十二個月"},{"key":"D","text":"六十日；十二個月"}]', 'A', '《澳門公共行政工作人員通則》第一百零五條第三款及第一百零六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-43', 'law', '根據現行《澳門公共行政工作人員通則》，為退休效力而計算的服務時間滿十五年之工作人員，在因病缺勤之法定期限屆滿後，須：', '[{"key":"A","text":"自動離職"},{"key":"B","text":"離職及獲退還為退休效力而扣除的款項"},{"key":"C","text":"自動離職以待退休"},{"key":"D","text":"離職及獲退還為撫恤金效力而扣除的款項"}]', 'C', '《澳門公共行政工作人員通則》第一百零七條第一款 a 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-44', 'law', '根據現行《澳門公共行政工作人員通則》，具合法理由身處澳門特別行政區外且在當地患病之工作人員，如不能啟程返回澳門特別行政區及不能在預定日期上班時，工作人員本人或中介人應在何時及以什麼方式將患病之事宜、預計患病期及聯絡地點通知有關部門？', '[{"key":"A","text":"在三個工作日內以書面方式"},{"key":"B","text":"在三個工作日內以口頭或書面方式"},{"key":"C","text":"在五個工作日內以書面方式"},{"key":"D","text":"在五個工作日內以口頭或書面方式"}]', 'A', '《澳門公共行政工作人員通則》第一百零九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-45', 'law', '根據現行《澳門公共行政工作人員通則》，在採用彈性工作時間時應遵守下列哪項規定？', '[{"key":"A","text":"每周正常工作時數為三十六小時"},{"key":"B","text":"工作人員每周不可欠時，亦不可將超出三十六小時的工作時數轉移至下周"},{"key":"C","text":"須訂定上下午必須出勤的工作時段，該時段稱為固定時段"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第七十九-C 條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-46', 'law', '根據現行《澳門公共行政工作人員通則》，在下列哪一項情況下發生之直接或間接使遇難人身體損傷、功能紊亂或患病以致無工作能力或死亡之意外，視為在職時意外？', '[{"key":"A","text":"在擔任其職務時於工作地點發生"},{"key":"B","text":"為執行上級指派之任務，在工作地點外發生"},{"key":"C","text":"在居所與工作地點之間之正常途徑中發生"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第一百一十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-47', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員如出現在職時意外，遇難人本人或第三人應在緊接意外發生後多長時間內以書面方式通知遇難人所屬部門之領導？', '[{"key":"A","text":"三日內"},{"key":"B","text":"五日內"},{"key":"C","text":"七日內"},{"key":"D","text":"十日內"}]', 'A', '《澳門公共行政工作人員通則》第一百一十一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-48', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員使用任何不當手段或方法，又或實施欺詐行為而享有為在職時意外而制定之保障及福利，須負：', '[{"key":"A","text":"紀律責任，且不影響倘提起之刑事程序"},{"key":"B","text":"紀律責任，且不影響倘提起之民事程序"},{"key":"C","text":"刑事責任，且不影響倘提起之民事程序"},{"key":"D","text":"民事責任"}]', 'A', '《澳門公共行政工作人員通則》第一百一十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-49', 'law', '根據現行《澳門公共行政工作人員通則》，在接獲工作人員在職時意外之通知後，部門領導應立即命令作出實況筆錄，並應在多長時間內向上級報告該事件？', '[{"key":"A","text":"十二小時"},{"key":"B","text":"二十四小時"},{"key":"C","text":"三十六小時"},{"key":"D","text":"四十八小時"}]', 'D', '《澳門公共行政工作人員通則》第一百一十三條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-50', 'law', '就現行《澳門公共行政工作人員通則》針對工作人員因在職時意外而缺勤的規定，以下表述中正確的是：', '[{"key":"A","text":"部門領導得知意外發生後，應立即採取措施，以便向遇難人提供必要之衛生護理"},{"key":"B","text":"提供衛生護理之醫生在開始治療時，應在專用印件上描述遇難人之傷勢及症狀"},{"key":"C","text":"如遇難人無能力充分履行其職務逾六十日，應其所屬部門領導之要求，遇難人必須接受健康檢查委員會之檢查"},{"key":"D","text":"以上皆正確"}]', 'D', '《澳門公共行政工作人員通則》第一百一十四條、第一百一十五條第一款及第一百一十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-51', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因發生在職時意外而導致其無能力充分履行職務之狀況，應：', '[{"key":"A","text":"每月以醫生之聲明確認"},{"key":"B","text":"每十日以醫生之聲明確認"},{"key":"C","text":"每月以部門領導之聲明確認"},{"key":"D","text":"每十日以部門領導之聲明確認"}]', 'A', '《澳門公共行政工作人員通則》第一百一十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-52', 'law', '根據現行《澳門公共行政工作人員通則》，遇有下列哪種情況，發生在職時意外的工作人員有權依法退休？', '[{"key":"A","text":"暫時部分無工作能力時"},{"key":"B","text":"長期部分無工作能力時"},{"key":"C","text":"主診醫生發出長期無工作能力聲明時"},{"key":"D","text":"健康檢查委員會發出長期及絕對無工作能力聲明時"}]', 'D', '《澳門公共行政工作人員通則》第一百一十九條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-53', 'law', '根據現行《澳門公共行政工作人員通則》，身為學生之工作人員得在每一曆年內以扣減薪俸方式連續或間斷缺勤最多六個工作日，而不喪失任何其他權利或福利，但須最少提前多少日申請，且以不致對部門之工作造成不便為限？', '[{"key":"A","text":"七個工作日"},{"key":"B","text":"七日"},{"key":"C","text":"八個工作日"},{"key":"D","text":"八日"}]', 'B', '《澳門公共行政工作人員通則》第一百二十五條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-54', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員為參加公共部門範圍內之開考之考核，而在進行考核所需期間內缺勤時，應最遲在何時作出通知，且須在四十八小時內以呈交典試委員會之聲明作為合理解釋。？', '[{"key":"A","text":"缺勤前一日"},{"key":"B","text":"缺勤前兩日"},{"key":"C","text":"缺勤前三日"},{"key":"D","text":"缺勤前四日"}]', 'A', '《澳門公共行政工作人員通則》第一百三十條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-55', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因履行法定義務而缺勤時，在一般情況下，應盡可能最遲：', '[{"key":"A","text":"在缺勤前兩日通知且在七十二小時內作出合理解釋"},{"key":"B","text":"在缺勤前一日通知且在四十八小時內作出合理解釋"},{"key":"C","text":"在缺勤當日通知且在二十四小時內作出合理解釋"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第一百三十一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-56', 'law', '根據現行《澳門公共行政工作人員通則》，無薪假僅得批予確定委任且同時符合下列哪一項要件之公務員？', '[{"key":"A","text":"現職且非正受紀律程序追究"},{"key":"B","text":"無拖欠財政局款項"},{"key":"C","text":"不致對部門之工作造成不便"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第一百三十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-57', 'law', '根據現行《澳門公共行政工作人員通則》，公務員應將享受無薪假期間之什麼資料通知所屬部門？', '[{"key":"A","text":"聯絡地點"},{"key":"B","text":"聯絡電話"},{"key":"C","text":"聯絡方式"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第一百三十七條第六款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-58', 'law', '根據現行《澳門公共行政工作人員通則》，基於工作需要，行政長官得以哪一方式隨時中斷或終止公務員之無薪假？', '[{"key":"A","text":"法律"},{"key":"B","text":"行政法規"},{"key":"C","text":"批示"},{"key":"D","text":"以上任一方式"}]', 'C', '《澳門公共行政工作人員通則》第一百三十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-59', 'law', '根據現行《澳門公共行政工作人員通則》，有權獲得衛生護理之受益權利人包括：', '[{"key":"A","text":"行政當局所有現職工作人員"},{"key":"B","text":"因患病而處於長期無薪假狀況之公務員"},{"key":"C","text":"處於待退休或已退休狀況之人員"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第一百四十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-60', 'law', '根據現行《澳門公共行政工作人員通則》，有權獲得衛生護理之受益權利人之供款係其薪俸、工資或退休金總數之：', '[{"key":"A","text":"1.5%"},{"key":"B","text":"1%"},{"key":"C","text":"0.5%"},{"key":"D","text":"0.1%"}]', 'C', '《澳門公共行政工作人員通則》第一百五十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-61', 'law', '服務時間對現行《澳門公共行政工作人員通則》或特別法所規定之效力，尤其對下列哪一項事宜具重要性：', '[{"key":"A","text":"職程內之晉階及晉升"},{"key":"B","text":"假期之批給"},{"key":"C","text":"退休及撫卹"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第一百五十六條 a、b 及 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-62', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員如在紀律程序內被命令防範性停職，而隨後被科處處分，則處於防範性停職狀況之期間：', '[{"key":"A","text":"視作實際服務時間"},{"key":"B","text":"不視作實際服務時間"},{"key":"C","text":"按情況視作實際服務時間"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第一百五十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-63', 'law', '僅《澳門公共行政工作人員通則》或特別法容許或規定之報酬，方得處理、結算及支付予行政當局工作人員。這規定體現了：', '[{"key":"A","text":"平等原則"},{"key":"B","text":"適度原則"},{"key":"C","text":"合法性原則"},{"key":"D","text":"無私原則"}]', 'C', '《澳門公共行政工作人員通則》第一百七十五條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-64', 'law', '根據現行《澳門公共行政工作人員通則》，以任何名義擔任公共職務之年報酬上限，按以下公式計算，其中「V」是代表：', '[{"key":"A","text":"薪俸表之最高薪俸"},{"key":"B","text":"年資獎金"},{"key":"C","text":"家庭津貼"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第一百七十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-65', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員之假期津貼：', '[{"key":"A","text":"不可轉讓及查封"},{"key":"B","text":"不可轉讓但可查封"},{"key":"C","text":"可轉讓及查封"},{"key":"D","text":"可轉讓但不可查封"}]', 'A', '《澳門公共行政工作人員通則》第一百八十四條第六款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-66', 'law', '根據現行《澳門公共行政工作人員通則》，以下哪項工作時間制度適用於無固定辦公時間的人員：', '[{"key":"A","text":"彈性工作時間"},{"key":"B","text":"特定工作時間"},{"key":"C","text":"輪值工作"},{"key":"D","text":"以上皆不適用"}]', 'D', '《澳門公共行政工作人員通則》第七十九-A 條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-67', 'law', '根據現行《澳門公共行政工作人員通則》，在下列哪一項的時間內所提供之工作，視為超時工作？', '[{"key":"A","text":"正常工作時間內"},{"key":"B","text":"每周休息日"},{"key":"C","text":"輪值工作制度下之值班時間內"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第七十九-H條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-68', 'law', '根據現行《澳門公共行政工作人員通則》，超時工作：', '[{"key":"A","text":"須經部門領導預先批准；屬特別和緊迫的情況，可由工作人員的上級決定，並在隨後兩個工作日內由部門領導確認，且因工作的不正常積累或緊急情況而提供"},{"key":"B","text":"只須由上級決定，且因工作的正常累積而允許提供"},{"key":"C","text":"無須經上級決定，但須在特別和緊迫的情況下提供"},{"key":"D","text":"無須經領導預先批准或上級決定，但須因工作之不正常累積或緊急情況而提供"}]', 'A', '《澳門公共行政工作人員通則》第七十九-I條第一及第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-69', 'law', '根據現行《澳門公共行政工作人員通則》，在非屬特別和緊迫的情況，提供超時工作：', '[{"key":"A","text":"無須預先批准"},{"key":"B","text":"須預先批准"},{"key":"C","text":"須事後追認"},{"key":"D","text":"無須預先批准，亦無須事後追認"}]', 'B', '《澳門公共行政工作人員通則》第七十九-I條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-70', 'law', '根據現行《澳門公共行政工作人員通則》，有關超時工作的規定，如屬特別和緊迫的情況，得由工作人員的上級決定，並在隨後多長時間內由部門領導確認？', '[{"key":"A","text":"一個工作日"},{"key":"B","text":"二個工作日"},{"key":"C","text":"三個工作日"},{"key":"D","text":"四個工作日"}]', 'B', '《澳門公共行政工作人員通則》第七十九-I條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-71', 'law', '根據現行《澳門公共行政工作人員通則》，除法例另有規定外，提供超時工作之時數上限為：', '[{"key":"A","text":"每月三十六小時"},{"key":"B","text":"每月四十四小時"},{"key":"C","text":"每月五十二小時"},{"key":"D","text":"每月六十小時"}]', 'C', '《澳門公共行政工作人員通則》第七十九-I條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-72', 'law', '現行《澳門公共行政工作人員通則》針對工作人員的輪值工作的規定，下列表述中正確的是：', '[{"key":"A","text":"值班以輪流方式作出，工作人員的工作時間須定期變動，最少每月兩次"},{"key":"B","text":"在須持續運作的部門內，同一名工作人員不得連續工作超過五日"},{"key":"C","text":"各班可重疊，但重疊的時間不得超過每班總工作時數的一半"},{"key":"D","text":"每班時間最長為九小時"}]', 'C', '《澳門公共行政工作人員通則》第七十九-E條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-73', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員因執行公務而前往外地，返回後多少日內應遞交詳細之行程報告書？', '[{"key":"A","text":"十日內"},{"key":"B","text":"二十日內"},{"key":"C","text":"三十日內"},{"key":"D","text":"四十日內"}]', 'C', '《澳門公共行政工作人員通則》第二百三十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-74', 'law', '根據現行《澳門公共行政工作人員通則》，工作人員之退休分為：', '[{"key":"A","text":"法定退休及意定退休"},{"key":"B","text":"強迫退休及自願退休"},{"key":"C","text":"自願退休及強制退休"},{"key":"D","text":"法定退休及自願退休"}]', 'C', '《澳門公共行政工作人員通則》第二百六十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-75', 'law', '根據現行《澳門公共行政工作人員通則》，處於下列哪一狀況之公務員或服務人員，須強制離職待退休？', '[{"key":"A","text":"達到五十歲"},{"key":"B","text":"因在職時意外而引致長期絕對無擔任職務之能力"},{"key":"C","text":"經健康檢查委員會宣告為長期絕對無擔任公共職務之能力"},{"key":"D","text":"最少有十年為退休效力而計算之服務時間，而被科處強迫退休處分"}]', 'B', '《澳門公共行政工作人員通則》第二百六十二條第一款c項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-76', 'law', '根據現行《澳門公共行政工作人員通則》，處於下列哪一狀況之公務員或服務人員，得自願退休？', '[{"key":"A","text":"為退休效力而計算之服務時間滿三十年且年滿五十五歲，聲明願意退休"},{"key":"B","text":"服務時間滿三十年，申請退休"},{"key":"C","text":"經健康檢查委員會宣告為長期絕對無擔任公共職務之能力"},{"key":"D","text":"因在職時意外而引致長期絕對無擔任職務之能力"}]', 'A', '《澳門公共行政工作人員通則》第二百六十三條第一款a項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-77', 'law', '根據現行《澳門公共行政工作人員通則》，退休人員之退休金相等於作為計算基礎之薪俸之三十六分之一乘以為退休而計算之服務年數，而有關服務年數最高為：', '[{"key":"A","text":"三十六年"},{"key":"B","text":"三十年"},{"key":"C","text":"二十年"},{"key":"D","text":"十五年"}]', 'A', '《澳門公共行政工作人員通則》第二百六十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-78', 'law', '根據現行《澳門公共行政工作人員通則》，退休人員之退休狀況在下列哪些情況下終止？', '[{"key":"A","text":"權利之時效完成"},{"key":"B","text":"放棄領取退休金或有關之權利"},{"key":"C","text":"死亡"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第二百七十條第一款a、b及d項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-79', 'law', '根據現行《澳門公共行政工作人員通則》，擔任公共職務時，公務員或服務人員專門為：', '[{"key":"A","text":"私人利益服務"},{"key":"B","text":"公共利益服務"},{"key":"C","text":"私人及公共利益服務"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第二百七十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-80', 'law', '根據現行《澳門公共行政工作人員通則》，擔任公共職務時，公務員或服務人員需要遵守的一般義務有：', '[{"key":"A","text":"無私、熱心"},{"key":"B","text":"服從、保密"},{"key":"C","text":"勤謹、守時"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第二百七十九條第二款a、b、c、e、g及h項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-81', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行其職務時需要遵守的無私義務，包括：', '[{"key":"A","text":"以有效之方式及盡心之態度執行其職務"},{"key":"B","text":"以尊重、有教養之態度對待上級"},{"key":"C","text":"持公正無私及獨立之態度對待任何性質之私人利益及壓力，以尊重市民間之平等"},{"key":"D","text":"對因擔任其職務而獲悉之非公開之事實保守職業秘密"}]', 'C', '《澳門公共行政工作人員通則》第二百七十九條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-82', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員有義務不因執行職務而直接或間接收取非法律賦予之金錢或其他利益。這裏所涉及的義務是：', '[{"key":"A","text":"無私之義務"},{"key":"B","text":"熱心之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"勤謹之義務"}]', 'A', '《澳門公共行政工作人員通則》第二百七十九條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-83', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員有義務以有效之方式及盡心之態度執行其職務。這裏所涉及的義務是：', '[{"key":"A","text":"熱心之義務"},{"key":"B","text":"服從之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"勤謹之義務"}]', 'A', '《澳門公共行政工作人員通則》第二百七十九條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-84', 'law', '公務員或服務人員在執行職務時尤其要了解法律及規章之規定、上級之指示。這是現行《澳門公共行政工作人員通則》規定的哪一義務之內容？', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"熱心之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"勤謹之義務"}]', 'B', '《澳門公共行政工作人員通則》第二百七十九條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-85', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行其職務時有義務具備及增進其技術知識、掌握及改善其工作方式。這是哪一義務的內容？', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"有禮之義務"},{"key":"C","text":"熱心之義務"},{"key":"D","text":"勤謹之義務"}]', 'C', '《澳門公共行政工作人員通則》第二百七十九條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-86', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行其職務時有服從之義務，係指：', '[{"key":"A","text":"以有效之方式及盡心之態度執行其職務"},{"key":"B","text":"以尊重、有教養之態度對待上級"},{"key":"C","text":"遵守其正當上級以任何方式發出之命令"},{"key":"D","text":"尊重及遵守其正當上級以法定方式及以工作為目的而發出之命令"}]', 'D', '《澳門公共行政工作人員通則》第二百七十九條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-87', 'law', '公務員或服務人員有義務根據上級指示及工作目的執行其職務，以謀求公共利益。這就是現行《澳門公共行政工作人員通則》所指的：', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"忠誠之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"無私之義務"}]', 'B', '《澳門公共行政工作人員通則》第二百七十九條第六款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-88', 'law', '根據現行《澳門公共行政工作人員通則》，如公務員或服務人員將因擔任其職務而獲悉之非公開之事實公開，則違反了：', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"忠誠之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"保密之義務"}]', 'D', '《澳門公共行政工作人員通則》第二百七十九條第七款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-89', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員有義務以尊重、有教養之態度對待公共部門之使用者、同事、上級及下屬。這裏所指的義務是：', '[{"key":"A","text":"熱心之義務"},{"key":"B","text":"有禮之義務"},{"key":"C","text":"忠誠之義務"},{"key":"D","text":"無私之義務"}]', 'B', '《澳門公共行政工作人員通則》第二百七十九條第八款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-90', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行其職務時有動謹之義務，係指：', '[{"key":"A","text":"正常及持續地在部門工作"},{"key":"B","text":"正常及間歇地在部門工作"},{"key":"C","text":"隨意地到部門上班"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第二百七十九條第九款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-91', 'law', '公務員或服務人員在執行其職務時有義務按指定之時間到部門上班。這就是現行《澳門公共行政工作人員通則》所規定的：', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"守時之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"保密之義務"}]', 'B', '《澳門公共行政工作人員通則》第二百七十九條第十款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-92', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行其職務時須遵守不從事不得兼任之活動之義務。這種義務係指：', '[{"key":"A","text":"擔任與所擔任職務相容之活動"},{"key":"B","text":"停止從事與所擔任職務相容之活動"},{"key":"C","text":"不擔任及停止從事與所擔任職務不相容之活動"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第二百七十九條第十一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-93', 'law', '根據現行《澳門公共行政工作人員通則》，領導及主管或等同領導及主管者，有義務：', '[{"key":"A","text":"以違反合法性之方式對待下屬"},{"key":"B","text":"以偏袒之態度對待下屬"},{"key":"C","text":"以任何方式及態度對待下屬"},{"key":"D","text":"以遵守合法性之方式及以公正之態度對待下屬"}]', 'D', '《澳門公共行政工作人員通則》第二百七十九條第十二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-94', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員如無需就職時，自何時起須對本身作出之違紀行為向上級負紀律責任？', '[{"key":"A","text":"自簽訂合同之日起"},{"key":"B","text":"自開始職務之日起"},{"key":"C","text":"自簽訂合同或開始職務之日起"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第二百八十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-95', 'law', '現行《澳門公共行政工作人員通則》規定之違紀行為，係指公務員或服務人員作出之違反其須遵守之一般義務或特別義務之：', '[{"key":"A","text":"故意事實"},{"key":"B","text":"過失事實"},{"key":"C","text":"過錯事實"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第二百八十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-96', 'law', '根據現行《澳門公共行政工作人員通則》，構成公務員或服務人員紀律責任之減輕情節的是：', '[{"key":"A","text":"自願承認違紀行為"},{"key":"B","text":"違紀行為已公開"},{"key":"C","text":"所擔任職位之責任重大"},{"key":"D","text":"工作十年以上"}]', 'A', '《澳門公共行政工作人員通則》第二百八十二條b項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-97', 'law', '根據現行《澳門公共行政工作人員通則》，構成公務員或服務人員紀律責任之加重情節的是：', '[{"key":"A","text":"與他人勾結作出違紀行為"},{"key":"B","text":"累犯"},{"key":"C","text":"公務員或服務人員本人引致違紀行為之公開"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第二百八十三條第一款d、f及i項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-98', 'law', '根據現行《澳門公共行政工作人員通則》，構成公務員或服務人員紀律責任加重情節的是：', '[{"key":"A","text":"初犯"},{"key":"B","text":"在接受紀律處分期間作出違紀行為"},{"key":"C","text":"在不應服從上級命令之情況下善意服從"},{"key":"D","text":"違紀行為並無公開"}]', 'B', '《澳門公共行政工作人員通則》第二百八十三條第一款e項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-99', 'law', '根據現行《澳門公共行政工作人員通則》，構成公務員或服務人員紀律責任加重情節之預謀，係指最少在作出違紀行為前多長時間已形成之意圖？', '[{"key":"A","text":"十小時"},{"key":"B","text":"十二小時"},{"key":"C","text":"二十四小時"},{"key":"D","text":"四十八小時"}]', 'C', '《澳門公共行政工作人員通則》第二百八十三條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-100', 'law', '根據現行《澳門公共行政工作人員通則》，構成紀律責任加重情節之累犯，其定義係指：', '[{"key":"A","text":"在因違紀行為而接受處分期滿之日起一年內作出相同之違紀行為"},{"key":"B","text":"在因違紀行為而接受處分期滿之日起六個月內作出相同之違紀行為"},{"key":"C","text":"在因違紀行為而接受處分期滿之日起三個月內作出相同之違紀行為"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第二百八十三條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-101', 'law', '公務員或服務人員因違紀行為而接受處分期滿之日起一年後作出相同之違紀行為或作出不同性質之違紀行為，構成以下哪項現行《澳門公共行政工作人員通則》所規定之加重情節？', '[{"key":"A","text":"累犯"},{"key":"B","text":"再犯"},{"key":"C","text":"違紀行為之合併"},{"key":"D","text":"預謀"}]', 'B', '《澳門公共行政工作人員通則》第二百八十三條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-102', 'law', '根據現行《澳門公共行政工作人員通則》，構成紀律責任加重情節之違紀行為之合併，係指：', '[{"key":"A","text":"在同一場合作出兩項或兩項以上之違紀行為"},{"key":"B","text":"第一項違紀行為未被處分前再作出另一違紀行為"},{"key":"C","text":"以上 A 或 B"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第二百八十三條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-103', 'law', '根據現行《澳門公共行政工作人員通則》，構成工作人員紀律責任之阻卻情節的是：', '[{"key":"A","text":"不可抵抗之人身脅迫"},{"key":"B","text":"作出不法行為時，在意外及非自願之情況下喪失運用智能之能力"},{"key":"C","text":"不可能期待作出其他行為"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第二百八十四條 a、b 及 d 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-104', 'law', '根據現行《澳門公共行政工作人員通則》，如出現為本人或他人作出正當防衛的情節，則構成紀律責任之：', '[{"key":"A","text":"阻卻情節"},{"key":"B","text":"減輕情節"},{"key":"C","text":"加重情節"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第二百八十四條 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-105', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員遵守上級在工作方面發出之命令或指示行事時，如認為存在下列哪一情況，在預先要求以書面傳達或確認該等命令或指示後，則排除倘有之紀律責任：', '[{"key":"A","text":"懷疑該等命令或指示之確實性"},{"key":"B","text":"該等命令或指示不合理"},{"key":"C","text":"該等命令或指示基於任何錯誤資訊而發出"},{"key":"D","text":"執行命令或指示可能引起上級未能預見之嚴重後果"}]', 'D', '《澳門公共行政工作人員通則》第二百八十五條第一款 d 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-106', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員遵守上級在工作方面發出之命令或指示行事時，遇有下列何種情況則服從之義務終止？', '[{"key":"A","text":"如命令或指示之執行將引致任何犯罪之實施"},{"key":"B","text":"如命令或指示之執行將引致嚴重犯罪之實施"},{"key":"C","text":"如命令或指示之執行將引致違法行為之實施"},{"key":"D","text":"以上皆不是"}]', 'A', '《澳門公共行政工作人員通則》第二百八十五條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-107', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員之紀律責任在以下哪一情況下解除？', '[{"key":"A","text":"在刑事訴訟程序中被判罪"},{"key":"B","text":"紀律程序之時效完成"},{"key":"C","text":"當事人員患有嚴重疾病"},{"key":"D","text":"特赦"}]', 'B', '《澳門公共行政工作人員通則》第二百八十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-108', 'law', '根據現行《澳門公共行政工作人員通則》，紀律程序之時效自作出違紀行為之日起計算，經：', '[{"key":"A","text":"一年完成"},{"key":"B","text":"兩年完成"},{"key":"C","text":"三年完成"},{"key":"D","text":"四年完成"}]', 'C', '《澳門公共行政工作人員通則》第二百八十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-109', 'law', '根據現行《澳門公共行政工作人員通則》，科處以下哪種紀律處分不取決於紀律程序，但事先須聽取違紀者之聲明？', '[{"key":"A","text":"書面申誡"},{"key":"B","text":"罰款"},{"key":"C","text":"停職"},{"key":"D","text":"強迫退休"}]', 'A', '《澳門公共行政工作人員通則》第二百九十一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-110', 'law', '根據現行《澳門公共行政工作人員通則》，紀律程序得分為一般程序或特別程序，以下屬特別程序的是：', '[{"key":"A","text":"對直接得知違紀行為之程序"},{"key":"B","text":"專案調查"},{"key":"C","text":"簡易調查"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第二百九十二條第一款及第五章第一、三及四節', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-111', 'law', '根據現行《澳門公共行政工作人員通則》，紀律程序在下列哪一階段具機密性質？', '[{"key":"A","text":"在提出控訴後"},{"key":"B","text":"在提出控訴前"},{"key":"C","text":"在科處處分後"},{"key":"D","text":"在科處處分前"}]', 'B', '《澳門公共行政工作人員通則》第二百九十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-112', 'law', '根據現行《澳門公共行政工作人員通則》，紀律程序的嫌疑人在程序哪一階段可委託律師？', '[{"key":"A","text":"在提出控訴後"},{"key":"B","text":"預審程序結束後"},{"key":"C","text":"任何階段"},{"key":"D","text":"在科處處分後"}]', 'C', '《澳門公共行政工作人員通則》第二百九十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-113', 'law', '根據現行《澳門公共行政工作人員通則》，如針對一名公務員或服務人員作出之多項嚴重程度不同之違紀行為且已提起多個程序時，則該等程序合併在：', '[{"key":"A","text":"最先提起之程序內"},{"key":"B","text":"最後提起之程序內"},{"key":"C","text":"嚴重程度較低的違紀行為之程序內"},{"key":"D","text":"較嚴重違紀行為之程序內"}]', 'D', '《澳門公共行政工作人員通則》第二百九十六條第一款前部份', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-114', 'law', '根據現行《澳門公共行政工作人員通則》，如有權參加開考之公務員或服務人員為紀律程序中之嫌疑人，即使處於防範性停職之狀況：', '[{"key":"A","text":"仍不准其參加該開考"},{"key":"B","text":"仍准其參加該開考"},{"key":"C","text":"仍准其參加該開考，只要違紀行為嚴重性輕微"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第二百九十七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-115', 'law', '根據現行《澳門公共行政工作人員通則》，因作成列舉各項違紀行為及指出所觸犯之法律規定之控訴書時無聽取嫌疑人之聲明，則產生何種法律後果？', '[{"key":"A","text":"不可補正之無效"},{"key":"B","text":"可補正之無效"},{"key":"C","text":"可撤銷"},{"key":"D","text":"不產生效力"}]', 'A', '《澳門公共行政工作人員通則》第二百九十八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-116', 'law', '現行《澳門公共行政工作人員通則》針對因公務員或服務人員作出違紀行為而可科處之處分，按其等級由低至高排列為：', '[{"key":"A","text":"罰款、書面申誡、停職、強迫退休及撤職"},{"key":"B","text":"書面申誡、罰款、強迫退休、停職及撤職"},{"key":"C","text":"書面申誡、罰款、停職、撤職及強迫退休"},{"key":"D","text":"書面申誡、罰款、停職、強迫退休及撤職"}]', 'D', '《澳門公共行政工作人員通則》第三百條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-117', 'law', '現行《澳門公共行政工作人員通則》關於紀律處分方面，下列表述中正確的是：', '[{"key":"A","text":"強迫退休係指公務員或服務人員確定性停止工作"},{"key":"B","text":"停職處分係指強制規定公務員或服務人員轉至退休人員之狀況"},{"key":"C","text":"撤職處分係指公務員或服務人員暫時性停止工作，並終止職務聯繫"},{"key":"D","text":"書面申誡處分係單純就違紀行為作出之勸戒"}]', 'D', '《澳門公共行政工作人員通則》第三百零一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-118', 'law', '根據現行《澳門公共行政工作人員通則》，停職處分的最低級別中，在下列哪一期間中定出？', '[{"key":"A","text":"二百四十一日至一年"},{"key":"B","text":"一百二十一日至二百四十日"},{"key":"C","text":"十日至一百二十日"},{"key":"D","text":"十日至二百四十日"}]', 'C', '《澳門公共行政工作人員通則》第三百零三條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-119', 'law', '根據現行《澳門公共行政工作人員通則》，對退休人員科處之強迫退休處分以：', '[{"key":"A","text":"喪失收取二十日退休金代替"},{"key":"B","text":"喪失收取退休金權利兩年代替"},{"key":"C","text":"中止支付退休金四年代替"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第三百零六條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-120', 'law', '根據現行《澳門公共行政工作人員通則》，除該通則另有規定，停職處分之時效自裁定轉為不可上訴之裁定之日起計，經：', '[{"key":"A","text":"兩年完成"},{"key":"B","text":"三年完成"},{"key":"C","text":"四年完成"},{"key":"D","text":"五年完成"}]', 'B', '《澳門公共行政工作人員通則》第三百零七條 b 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-121', 'law', '根據現行《澳門公共行政工作人員通則》，除該通則另有規定，撤職處分之時效自裁定轉為不可上訴之裁定之日起計，經：', '[{"key":"A","text":"兩年完成"},{"key":"B","text":"三年完成"},{"key":"C","text":"四年完成"},{"key":"D","text":"五年完成"}]', 'D', '《澳門公共行政工作人員通則》第三百零七條 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-122', 'law', '根據現行《澳門公共行政工作人員通則》，紀律處分自何時起產生效力？', '[{"key":"A","text":"自開始執行之日起"},{"key":"B","text":"自執行完結之日起"},{"key":"C","text":"自裁定作出之日起"},{"key":"D","text":"自裁定公布在《澳門特別行政區公報》之日起"}]', 'A', '《澳門公共行政工作人員通則》第三百零八條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-123', 'law', '根據現行《澳門公共行政工作人員通則》，停職處分導致被處分的人員：', '[{"key":"A","text":"自處分完結時起六個月內喪失享受年假之權能"},{"key":"B","text":"不得擔任官職或職務，並中止有關之職務聯繫"},{"key":"C","text":"喪失獲得醫療福利之權利"},{"key":"D","text":"喪失收取家庭津貼之權利"}]', 'B', '《澳門公共行政工作人員通則》第三百零九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-124', 'law', '根據現行《澳門公共行政工作人員通則》，被強迫退休之公務員或服務人員在收到處分通知之日起經過多長時間後方得收取退休金？', '[{"key":"A","text":"六個月後"},{"key":"B","text":"八個月後"},{"key":"C","text":"一年後"},{"key":"D","text":"十八個月後"}]', 'D', '《澳門公共行政工作人員通則》第三百一十條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-125', 'law', '根據現行《澳門公共行政工作人員通則》，撤職處分導致公務員或服務人員：', '[{"key":"A","text":"兩年內不得晉階及晉升"},{"key":"B","text":"僅喪失獲得醫療福利、收取家庭津貼及房屋津貼之權利"},{"key":"C","text":"喪失一切權利"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第三百一十一條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-126', 'law', '根據現行《澳門公共行政工作人員通則》，對未為部門帶來損失或令部門名譽受損之輕微違紀行為，科處：', '[{"key":"A","text":"撤職處分"},{"key":"B","text":"書面申誡處分"},{"key":"C","text":"罰款處分"},{"key":"D","text":"停職處分"}]', 'B', '《澳門公共行政工作人員通則》第三百一十二條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-127', 'law', '現行《澳門公共行政工作人員通則》關於紀律處分方面，導致科處罰款處分的違紀行為尤其包括：', '[{"key":"A","text":"整理所負責之簿冊及文件時不遵守上級命令，或記帳時因過失而犯錯誤者"},{"key":"B","text":"不遵守上級命令，但未造成嚴重後果者"},{"key":"C","text":"不禮貌對待上級、下屬、同事或公眾者"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第三百一十三條第二款 a、b 及 d 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-128', 'law', '根據現行《澳門公共行政工作人員通則》，對於不向有權限當局舉報在擔任職務時獲悉其下屬作出之嚴重違紀行為者，科處哪種紀律處分？', '[{"key":"A","text":"停職一百二十一日至二百四十日"},{"key":"B","text":"停職十日至一百二十日"},{"key":"C","text":"停職二百四十一日至一年"},{"key":"D","text":"強迫退休或撤職"}]', 'A', '《澳門公共行政工作人員通則》第三百一十四條第二款 i 項及第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-129', 'law', '根據現行《澳門公共行政工作人員通則》，下列哪種行為可導致行為人被科處強迫退休或撤職處分？', '[{"key":"A","text":"對出於過失及誤解職務上之義務之情況"},{"key":"B","text":"在醉酒或受麻醉品或同類藥物影響之狀態下上班"},{"key":"C","text":"擔任職務時作出明顯違反憲定制度及原則之行為"},{"key":"D","text":"在同一曆年內，無合理解釋而連續缺勤五日"}]', 'C', '《澳門公共行政工作人員通則》第三百一十五條第二款 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-130', 'law', '根據現行《澳門公共行政工作人員通則》，對於經證明無專業能力的公務員或服務人員可科處以下哪項紀律處分？', '[{"key":"A","text":"書面申誡"},{"key":"B","text":"罰款"},{"key":"C","text":"停職"},{"key":"D","text":"強迫退休或撤職"}]', 'D', '《澳門公共行政工作人員通則》第三百一十五條第二款 g 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-131', 'law', '現行《澳門公共行政工作人員通則》關於紀律處分方面，如屬累犯，且科處之紀律處分為罰款或更高者，則處分：', '[{"key":"A","text":"不受影響"},{"key":"B","text":"必須加重一級"},{"key":"C","text":"可加重一級"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門公共行政工作人員通則》第三百一十六條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-132', 'law', '根據現行《澳門公共行政工作人員通則》，在符合法定情況下，紀律處分可予暫緩執行，而期間自將有關裁定通知嫌疑人之日起計算，不得：', '[{"key":"A","text":"少於一年"},{"key":"B","text":"超過三年"},{"key":"C","text":"少於一年或超過三年"},{"key":"D","text":"以上皆不是"}]', 'C', '《澳門公共行政工作人員通則》第三百一十七條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-133', 'law', '根據現行《澳門公共行政工作人員通則》，除屬應歸檔之情況外，當出現下列哪些情況，有權限提起紀律程序之實體須立即提起有關程序？', '[{"key":"A","text":"在收到筆錄後"},{"key":"B","text":"在收到舉報後"},{"key":"C","text":"在收到投訴後"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第三百二十五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-134', 'law', '根據現行《澳門公共行政工作人員通則》，遇有下列哪種情況，紀律程序之預審員須回避擔任有關職務？', '[{"key":"A","text":"預審員曾直接或間接因違紀行為而被傷害或損害"},{"key":"B","text":"嫌疑人與預審員之間有強烈敵意"},{"key":"C","text":"預審員及嫌疑人或舉報人為在法院待決之程序中之當事人"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第三百二十七條第一款 a、e 及 c 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-135', 'law', '根據現行《澳門公共行政工作人員通則》，紀律程序中的預審階段包括一系列簡易調查及措施，其目的在於：', '[{"key":"A","text":"查明是否存在違紀行為"},{"key":"B","text":"確定行為人及其責任"},{"key":"C","text":"搜集一切有助作出具依據之裁定之證據"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門公共行政工作人員通則》第三百二十九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-136', 'law', '根據現行《澳門公共行政工作人員通則》，當涉及之違紀行為可被科處下列哪項處分時，嫌疑人得被命令防範性停職？', '[{"key":"A","text":"書面申誡"},{"key":"B","text":"罰款"},{"key":"C","text":"停職一百二十一日至二百四十日"},{"key":"D","text":"以上皆不是"}]', 'D', '《澳門公共行政工作人員通則》第三百三十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-137', 'law', '根據現行《澳門公共行政工作人員通則》，在預審員認為出現下列何種情況時，應建議將紀律程序歸檔？', '[{"key":"A","text":"筆錄所載事實構成違紀行為"},{"key":"B","text":"嫌疑人為違紀行為之行為人"},{"key":"C","text":"因時效或其他原因而不得追究紀律責任"},{"key":"D","text":"違紀行為構成犯罪"}]', 'C', '《澳門公共行政工作人員通則》第三百三十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-138', 'law', '根據現行《澳門公共行政工作人員通則》，對於紀律程序中作出之最後裁定，行為人得提出：', '[{"key":"A","text":"書面聽證"},{"key":"B","text":"司法上訴"},{"key":"C","text":"民事訴訟"},{"key":"D","text":"刑事訴訟"}]', 'B', '《澳門公共行政工作人員通則》第三百四十條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-139', 'law', '現行《澳門公共行政工作人員通則》關於紀律程序方面，構成複查紀律程序之理由包括：', '[{"key":"A","text":"單純指程序在形式上違法"},{"key":"B","text":"單純指程序在實質上違法"},{"key":"C","text":"單純指科處之處分在形式或實質上違法"},{"key":"D","text":"以上皆不是"}]', 'D', '《澳門公共行政工作人員通則》第三百四十四條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-140', 'law', '根據現行《澳門公共行政工作人員通則》，准予複查紀律程序後，被新委任之預審員須給予利害關係人多長期限以作書面答辯？', '[{"key":"A","text":"不少於五日但不超過十日"},{"key":"B","text":"不少於五日但不超過二十日"},{"key":"C","text":"不少於十日但不超過二十日"},{"key":"D","text":"不少於十日但不超過三十日"}]', 'C', '《澳門公共行政工作人員通則》第三百四十六條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-141', 'law', '根據現行《澳門公共行政工作人員通則》，科處或履行罰款處分後，經過多長期間，利害關係人或其代理人得申請恢復權利？', '[{"key":"A","text":"一年"},{"key":"B","text":"兩年"},{"key":"C","text":"三年"},{"key":"D","text":"五年"}]', 'B', '《澳門公共行政工作人員通則》第三百四十九條第三款 b 項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-staff-142', 'law', '現行《澳門公共行政工作人員通則》關於恢復權利方面，下列表述中正確的是：', '[{"key":"A","text":"恢復權利使無能力之狀況及尚存之其他判罪效力終止"},{"key":"B","text":"受強迫退處分之人，因恢復權利之事實而可再獲擔任行政當局職位或職務之權利"},{"key":"C","text":"受撤職處分之人，不論其服務時間多久，得在恢復權利中要求將撤職處分轉換為強迫退休"},{"key":"D","text":"受任何處分之公務員或服務人員僅透過複查紀律程序，方得獲恢復權利"}]', 'A', '《澳門公共行政工作人員通則》第三百四十九條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-1', 'law', '除另有規定外，現行《公務人員職程制度》不適用於下列哪種情況的人員？', '[{"key":"A","text":"按專有人員通則獲任用、擔任顧問和專業技術職務、在澳門特別行政區駐外辦事處按其駐在地的法例擔任職務"},{"key":"B","text":"所擔任的職務因性質或特殊性而須由專有法規規範"},{"key":"C","text":"由公共企業、公共團體，又或全部或部分資本屬公共資本的公司任用"},{"key":"D","text":"以上皆不適用"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第一條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-2', 'law', '根據現行《公務人員職程制度》，「與各公共部門的共同工作範疇相對應的職程，又或與一個或多個公共部門專有的特定職務相對應的職程」是以下哪一個用語的定義？', '[{"key":"A","text":"一般職程"},{"key":"B","text":"特別職程"},{"key":"C","text":"垂直職程"},{"key":"D","text":"橫向職程"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第二條（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-3', 'law', '根據現行《公務人員職程制度》，以下哪項是「垂直職程」的正確定義？', '[{"key":"A","text":"與各公共部門的共同工作範疇相對應的職程，又或與一個或多個公共部門專有的特定職務相對應的職程"},{"key":"B","text":"一系列不同的薪酬級別，而提升薪酬級別的準則是人員執行構成相關職務內容的工作的經驗增加，但工作的複雜程度無明顯改變"},{"key":"C","text":"職務內容相同的各個職級的序列，該等職級是按工作複雜程度及人員責任的遞增順序排列"},{"key":"D","text":"與一個或多個公共部門的特定職務相對應的職程，而基於相關職務內容的特徵，該等職程有本身的入職規定、進程及所需具備的資格要件或專業要件"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第二條（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-4', 'law', '根據現行《公務人員職程制度》，「一系列不同的薪酬級別，而提升薪酬級別的準則是人員執行構成相關職務內容的工作的經驗增加，但工作的複雜程度無明顯改變」是以下哪一個用語的定義？', '[{"key":"A","text":"一般職程"},{"key":"B","text":"特別職程"},{"key":"C","text":"垂直職程"},{"key":"D","text":"橫向職程"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第二條（四）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-5', 'law', '根據現行《公務人員職程制度》，「按人員的職務內容的一般特徵而界定的人員類別」是以下哪一個用語的定義？', '[{"key":"A","text":"人員組別"},{"key":"B","text":"一般職程"},{"key":"C","text":"特別職程"},{"key":"D","text":"級別"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第二條（五）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-6', 'law', '根據現行《公務人員職程制度》，「一系列因具有一個或多個共通點而可歸併成某種工作類別的職務」是以下哪一個用語的定義？', '[{"key":"A","text":"職務範疇"},{"key":"B","text":"職務內容"},{"key":"C","text":"級別"},{"key":"D","text":"職等"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第二條（六）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-7', 'law', '根據現行《公務人員職程制度》，「某一職程內的人員普遍執行的一系列工作」是以下哪一個用語的定義？', '[{"key":"A","text":"職務範疇"},{"key":"B","text":"職務內容"},{"key":"C","text":"級別"},{"key":"D","text":"職等"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第二條（七）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-8', 'law', '根據現行《公務人員職程制度》，「按職務的複雜程度，以及對人員的學歷、專業及其他要求而定出的職務等級編排」是以下哪一個用語的定義？', '[{"key":"A","text":"職階"},{"key":"B","text":"職等"},{"key":"C","text":"職務內容"},{"key":"D","text":"級別"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第二條（八）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-9', 'law', '根據現行《公務人員職程制度》，「構成某一垂直職程的各個職級，而各個職級是按其工作的複雜程度順序排列」是以下哪一個用語的定義？', '[{"key":"A","text":"職階"},{"key":"B","text":"職等"},{"key":"C","text":"晉級"},{"key":"D","text":"晉階"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第二條（九）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-10', 'law', '根據現行《公務人員職程制度》，「在某一職等或某一橫向職程內的薪酬級別」是以下哪一個用語的定義？', '[{"key":"A","text":"職階"},{"key":"B","text":"職等"},{"key":"C","text":"級別"},{"key":"D","text":"職程"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第二條（十）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-11', 'law', '根據現行《公務人員職程制度》，「在某一垂直職程內的職等晉升」是以下哪一個用語的定義？', '[{"key":"A","text":"職階"},{"key":"B","text":"職等"},{"key":"C","text":"晉級"},{"key":"D","text":"晉階"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第二條（十一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-12', 'law', '根據現行《公務人員職程制度》，「在某一橫向職程內或在某一垂直職程的某一職等內的職階晉升」是以下哪一個用語的定義？', '[{"key":"A","text":"職階"},{"key":"B","text":"職等"},{"key":"C","text":"晉級"},{"key":"D","text":"晉階"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第二條（十二）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-13', 'law', '根據現行《公務人員職程制度》，具有職權訂定一般職程及存在於多個公共部門的特別職程的職務內容的政府部門是：', '[{"key":"A","text":"行政公職局"},{"key":"B","text":"法務局"},{"key":"C","text":"檢察院"},{"key":"D","text":"審計署"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-14', 'law', '根據現行《公務人員職程制度》，一般情況下，在垂直職程中應從以下哪一個職等及職階入職？', '[{"key":"A","text":"第一職等第一職階"},{"key":"B","text":"第二職等第一職級"},{"key":"C","text":"第二職等第一職階"},{"key":"D","text":"第一職等第二職階"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第十二條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-15', 'law', '根據現行《公務人員職程制度》，在垂直職程內由某一職階晉升至緊接的較高職階，須在原職階的服務時間內的工作表現評核中取得不低於甚麼程度的評語？', '[{"key":"A","text":"優異"},{"key":"B","text":"十分滿意"},{"key":"C","text":"滿意"},{"key":"D","text":"不大滿意"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-16', 'law', '根據現行《公務人員職程制度》，如在原職階的服務時間內的工作表現評核均取得「滿意」的評語，在垂直職程內由原職階晉升至緊接的較高職階〔如屬在最高職等內晉階〕時，須在原職階服務滿多少年？', '[{"key":"A","text":"三年"},{"key":"B","text":"八年"},{"key":"C","text":"九年"},{"key":"D","text":"五年"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第十三條第一款（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-17', 'law', '根據現行《公務人員職程制度》，如在原職階的服務時間內的工作表現評核均取得「滿意」的評語，在垂直職程內由原職階晉升至緊接的較高職階〔非屬在最高職等內晉階〕時，須在原職階服務滿多少年？', '[{"key":"A","text":"一年"},{"key":"B","text":"二年"},{"key":"C","text":"三年"},{"key":"D","text":"四年"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第十三條第一款（二）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-18', 'law', '根據現行《公務人員職程制度》，如在原職階的服務時間內的工作表現評核均取得「滿意」的評語，在橫向職程內由原職階晉升至緊接的較高職階時，以下表述不正確的是：', '[{"key":"A","text":"如屬晉升至第二職階，須在原職階服務滿一年"},{"key":"B","text":"如屬晉升至第三職階或第四職階，須在原職階服務滿三年"},{"key":"C","text":"如屬晉升至第五職階或第六職階，須在原職階服務滿四年"},{"key":"D","text":"如屬晉升至第七職階、第八職階、第九職階或第十職階，須在原職階服務滿五年"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第十三條第二款（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-19', 'law', '根據現行《公務人員職程制度》，除另有規定外，如屬晉升至職程內的最高職等，須在原職等服務滿多少年，且在該段服務時間內的工作表現評核中取得不低於甚麼的評語？', '[{"key":"A","text":"九年，滿意 或 八年，十分滿意"},{"key":"B","text":"十年，滿意 或 九年，十分滿意"},{"key":"C","text":"八年，滿意 或 七年 十分滿意"},{"key":"D","text":"八年，滿意 或 七年，優異"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第十四條第一款（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-20', 'law', '根據現行《公務人員職程制度》，經部門建議，技術工人職程及勤雜人員職程的職務範疇可由哪一個部門訂定或修改？', '[{"key":"A","text":"行政公職局"},{"key":"B","text":"法務局"},{"key":"C","text":"立法會"},{"key":"D","text":"行政法務司司長辦公室"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第十八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-21', 'law', '根據現行《公務人員職程制度》，以下哪些工作範疇設有特別職程？', '[{"key":"A","text":"郵務、教育、統計"},{"key":"B","text":"商務、傳譯及翻譯、監察"},{"key":"C","text":"園藝、氣象、土木"},{"key":"D","text":"衛生、農務、氣象"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第十九條第一款（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-22', 'law', '根據現行《公務人員職程制度》，以下哪些工作範疇設有特別職程？', '[{"key":"A","text":"文贖、商務、衛生"},{"key":"B","text":"保安、港務、電信"},{"key":"C","text":"地形測量、運輸、土木"},{"key":"D","text":"氣象、港務、藝術"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第十九條第一款（十三）至（十五）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-23', 'law', '根據現行《公務人員職程制度》，以下哪個工作範疇的特別職程由專有法規規範？', '[{"key":"A","text":"教育範疇、保安範疇"},{"key":"B","text":"衛生範疇、司法範疇"},{"key":"C","text":"文贖範疇、登記及公證範疇"},{"key":"D","text":"以上皆是"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第十九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-24', 'law', '根據現行《公務人員職程制度》，設立特別職程的依據是：', '[{"key":"A","text":"職務分析"},{"key":"B","text":"對職務內容、職務範疇、入職要件、職程進程、資格要件或專業要件，以及能力和技能要求的特別要求"},{"key":"C","text":"不能採用一般職程"},{"key":"D","text":"以上皆是"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第二十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-25', 'law', '根據現行《公務人員職程制度》，如須統籌十名或以上人員的工作，又或統籌工作的複雜性經適當證明，可設立以下哪個職位？', '[{"key":"A","text":"職務主管"},{"key":"B","text":"主任"},{"key":"C","text":"科長"},{"key":"D","text":"處長"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第五十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-26', 'law', '根據現行《公務人員職程制度》，法規草擬職務的每月附加報酬的金額可於薪俸表內的薪俸點一百點的哪一比例範圍內訂定？', '[{"key":"A","text":"百分之四十至一百"},{"key":"B","text":"百分之五十至一百"},{"key":"C","text":"百分之五十至八十"},{"key":"D","text":"百分之七十至九十"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第五十四條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-27', 'law', '根據現行《公務人員職程制度》，法律筆譯職務的每月附加報酬的金額相當於薪俸表內的薪俸點一百點的百分之幾？', '[{"key":"A","text":"二十"},{"key":"B","text":"三十"},{"key":"C","text":"四十"},{"key":"D","text":"五十"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第五十四條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-28', 'law', '根據現行《公務人員職程制度》，專業資格：', '[{"key":"A","text":"應與擔任的職務相稱"},{"key":"B","text":"須透過完成培訓課程取得或由公共部門發出的職業技能證明文件取得"},{"key":"C","text":"A 或 B"},{"key":"D","text":"A 及 B"}]', 'D', '經第4/2017號法律修改的第14/2009號法律第六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-29', 'law', '根據現行《公務人員職程制度》，高級技術員的職務是：', '[{"key":"A","text":"創造"},{"key":"B","text":"應用"},{"key":"C","text":"執行"},{"key":"D","text":"領導"}]', 'A', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-30', 'law', '根據現行《公務人員職程制度》，技術輔助人員的職務是：', '[{"key":"A","text":"領導"},{"key":"B","text":"創造"},{"key":"C","text":"應用"},{"key":"D","text":"執行"}]', 'D', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-31', 'law', '根據現行《公務人員職程制度》，須具專業技能及從具高等專科學位程度的學歷獲得專業知識，以便對既定計劃中技術性的方法及程序能獨立並盡責擔任研究及應用的職務是屬於下列哪項的人員組別的職務內容的一般特徵？', '[{"key":"A","text":"高級技術員"},{"key":"B","text":"技術員"},{"key":"C","text":"技術輔助人員"},{"key":"D","text":"工人"}]', 'B', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-32', 'law', '根據現行《公務人員職程制度》，須具有高中畢業學歷中的理論及實踐性的技術知識，以便以對某些方法及程序的認識或配合為基礎，擔任既定指令中的技術應用的執行性職務是屬於下列哪項的人員組別的職務內容的一般特徵？', '[{"key":"A","text":"工人"},{"key":"B","text":"技術員"},{"key":"C","text":"技術輔助人員"},{"key":"D","text":"高級技術員"}]', 'C', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-33', 'law', '根據現行《公務人員職程制度》，須具備專業資格或相關工作經驗，以便擔任既定一般指示中具一定複雜程度的人手或機械操作的生產活動方面或維修及保養方面的執行性職務是屬於下列哪項的人員組別的職務內容的一般特徵？', '[{"key":"A","text":"技術員"},{"key":"B","text":"技術輔助人員"},{"key":"C","text":"工人"},{"key":"D","text":"高級技術員"}]', 'C', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-career-34', 'law', '根據現行《公務人員職程制度》，以下哪項的職程不屬技術輔助人員？', '[{"key":"A","text":"公關督導員"},{"key":"B","text":"行政技術助理員"},{"key":"C","text":"郵務文員"},{"key":"D","text":"技術工人"}]', 'D', '經第4/2017號法律修改的第14/2009號法律附件一表二', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-1', 'law', '為適用現行《公共部門勞動合同制度》的規定，公共部門所指的公共行政當局的機關及部門包括：', '[{"key":"A","text":"自治基金、公務法人"},{"key":"B","text":"行政長官辦公室、政府主要官員的辦公室及行政輔助部門"},{"key":"C","text":"立法會輔助部門、終審法院院長辦公室及檢察長辦公室"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-2', 'law', '在不影響特別制度的適用下，現行《公共部門勞動合同制度》適用於公共部門以哪一制度任用的工作人員？', '[{"key":"A","text":"勞動合同"},{"key":"B","text":"編制外合同"},{"key":"C","text":"散位合同"},{"key":"D","text":"定期委任"}]', 'A', '第12/2015號法律第二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-3', 'law', '現行《公共部門勞動合同制度》不適用於下列哪種情況的人員？', '[{"key":"A","text":"按專有人員通則獲任用者"},{"key":"B","text":"擔任顧問和專業技術職務者"},{"key":"C","text":"為滿足臨時性或緊急性的需求者"},{"key":"D","text":"以上皆不適用"}]', 'A', '第12/2015號法律第二條二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-4', 'law', '根據現行《公共部門勞動合同制度》，公共部門勞動合同分為：', '[{"key":"A","text":"編制外合同和個人勞動合同"},{"key":"B","text":"行政任用合同和散位合同"},{"key":"C","text":"行政任用合同和個人勞動合同"},{"key":"D","text":"編制外合同和散位合同"}]', 'C', '第12/2015號法律第三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-5', 'law', '根據現行《公共部門勞動合同制度》，除另有規定的情況除外，以合同方式任用工作人員在公共部門擔任職務，應採用的合同是：', '[{"key":"A","text":"編制外合同"},{"key":"B","text":"散位合同"},{"key":"C","text":"行政任用合同"},{"key":"D","text":"個人勞動合同"}]', 'C', '第12/2015號法律第三條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-6', 'law', '根據現行《公共部門勞動合同制度》，在下列哪種情況下方可採用個人勞動合同？', '[{"key":"A","text":"按專有人員通則獲任用"},{"key":"B","text":"由公共企業、公共團體，又或全部或部分資本屬公共資本的公司任用"},{"key":"C","text":"所擔任的職務因性質或特殊性而須由專有法規規範"},{"key":"D","text":"擔任顧問和專業技術職務或為滿足臨時性或緊急性的需求"}]', 'D', '第12/2015號法律第三條第三款（一）及（二）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-7', 'law', '根據現行《公共部門勞動合同制度》，行政任用合同的修改及續期透過：', '[{"key":"A","text":"所屬公共部門領導書面核准"},{"key":"B","text":"立約人簽訂新的行政任用合同作出"},{"key":"C","text":"立約人在附註上簽署作出"},{"key":"D","text":"行政長官之批示核准"}]', 'C', '第12/2015號法律第四條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-8', 'law', '根據現行《公共部門勞動合同制度》，試用期的期間為：', '[{"key":"A","text":"三個月"},{"key":"B","text":"六個月"},{"key":"C","text":"九個月"},{"key":"D","text":"十二個月"}]', 'B', '第12/2015號法律第五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-9', 'law', '根據現行《公共部門勞動合同制度》，除特別規定外，行政任用合同的期間一般不超過：', '[{"key":"A","text":"六個月"},{"key":"B","text":"一年"},{"key":"C","text":"十八個月"},{"key":"D","text":"兩年"}]', 'D', '第12/2015號法律第六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-10', 'law', '根據現行《公共部門勞動合同制度》，工作人員以行政任用合同提供服務的時間滿兩年及在工作表現評核中連續取得兩次不低於「十分滿意」的評語，行政任用合同須修改為：', '[{"key":"A","text":"不具期限的行政任用合同"},{"key":"B","text":"具不確定期限的行政任用合同"},{"key":"C","text":"期間為三年的長期行政任用合同"},{"key":"D","text":"中期行政任用合同"}]', 'C', '第12/2015號法律第六條第二款第（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-11', 'law', '根據現行《公共部門勞動合同制度》，工作人員以長期行政任用合同提供服務的時間滿三年及在工作表現評核中連續取得兩次不低於「十分滿意」的評語，行政任用合同須修改為：', '[{"key":"A","text":"不具期限的行政任用合同"},{"key":"B","text":"具不確定期限的行政任用合同"},{"key":"C","text":"具確定期限的行政任用合同"},{"key":"D","text":"具期限的行政任用合同"}]', 'A', '第12/2015號法律第六條第二款第（二）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-12', 'law', '根據現行《公共部門勞動合同制度》，長期行政任用合同續期的期間為：', '[{"key":"A","text":"一年"},{"key":"B","text":"兩年"},{"key":"C","text":"三年"},{"key":"D","text":"四年"}]', 'C', '第12/2015號法律第六條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-13', 'law', '根據現行《公共部門勞動合同制度》，除其另有規定外，以下哪一項適用於以行政任用合同任用的工作人員？', '[{"key":"A","text":"勞動關係法"},{"key":"B","text":"澳門保安部隊軍事化人員通則"},{"key":"C","text":"司法輔助人員通則"},{"key":"D","text":"公職法律制度"}]', 'D', '第12/2015號法律第七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-14', 'law', '根據現行《公共部門勞動合同制度》，如不具期限的行政任用合同由工作人員提出或經雙方協議而終止，工作人員可在行政任用合同終止日起計多少時間內向原公共部門申請重新聘用？', '[{"key":"A","text":"一年"},{"key":"B","text":"兩年"},{"key":"C","text":"三年"},{"key":"D","text":"四年"}]', 'B', '第12/2015號法律第八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-15', 'law', '根據現行《公共部門勞動合同制度》，重新聘用除須由公共部門所屬的監督實體許可外，還須同時符合以下哪些要件？', '[{"key":"A","text":"該公共部門有人員需求及有編制外人員配備的空缺"},{"key":"B","text":"申請人在終止行政任用合同之日緊接前五年的工作表現評核中均取得不低於「十分滿意」的評語"},{"key":"C","text":"申請人沒有在行政任用合同終止後擔任任何公共職務"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第八條第二款（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-16', 'law', '根據現行《公共部門勞動合同制度》，以行政任用合同制度任用的工作人員，只要在調職建議之日在原公共部門的相關職程連續提供服務滿多少年，可以相同職程、職級及職階，從原公共部門轉至其他公共部門而無須採用開考制度？', '[{"key":"A","text":"兩"},{"key":"B","text":"三"},{"key":"C","text":"四"},{"key":"D","text":"五"}]', 'A', '第12/2015號法律第九條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-17', 'law', '根據現行《公共部門勞動合同制度》，調職建議由擬聘用工作人員的公共部門向其監督實體提出及須獲其許可，並附同下列哪些文件？', '[{"key":"A","text":"工作人員的同意書或申請書"},{"key":"B","text":"工作人員的原公共部門的贊同意見書"},{"key":"C","text":"行政公職局就擬聘用工作人員的公共部門編制外人員配備的空缺情況所給予的意見書"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第九條第二款（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-18', 'law', '根據現行《公共部門勞動合同制度》，以下哪項不是行政任用合同終止的方式？', '[{"key":"A","text":"經雙方協議"},{"key":"B","text":"解除"},{"key":"C","text":"由任一方提出"},{"key":"D","text":"失效"}]', 'B', '第12/2015號法律第十條（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-19', 'law', '根據現行《公共部門勞動合同制度》，公共部門可在以下哪些情況下終止行政任用合同？', '[{"key":"A","text":"根據紀律制度或刑法規定對工作人員科處終止職務的處罰"},{"key":"B","text":"因工作表現評核結果而終止擔任職務"},{"key":"C","text":"工作人員在試用期內的工作表現評核中取得「不滿意」的評語，又或終止職務是實習或入職培訓制度所規定的後果"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第十二條第一款（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-20', 'law', '根據現行《公共部門勞動合同制度》，經公共部門所屬的監督實體許可，公共部門亦可在最少提前多少期間內以書面通知工作人員後終止行政任用合同？', '[{"key":"A","text":"三十日"},{"key":"B","text":"六十日"},{"key":"C","text":"九十日"},{"key":"D","text":"一百二十日"}]', 'B', '第12/2015號法律第十二條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-21', 'law', '根據現行《公共部門勞動合同制度》，工作人員應最少提前多少時間以書面通知所任職的公共部門其終止行政任用合同的意願？', '[{"key":"A","text":"一百二十日"},{"key":"B","text":"九十日"},{"key":"C","text":"六十日"},{"key":"D","text":"三十日"}]', 'C', '第12/2015號法律第十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-22', 'law', '以下哪項是現行《公共部門勞動合同制度》規定的行政任用合同失效的情況？', '[{"key":"A","text":"當工作人員達到擔任公職的最高年齡限制"},{"key":"B","text":"當工作人員處於長期絕對無擔任職務的能力"},{"key":"C","text":"屬調職的情況下，則自該工作人員按新行政任用合同開始擔任職務之日起"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第十五條（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-23', 'law', '根據現行《公共部門勞動合同制度》，僅在專業人員短缺或擬聘用的人員具特別才能的情況下，方可以下列哪種制度聘用澳門特別行政區或以外的工作人員擔任顧問或專業技術職務？', '[{"key":"A","text":"行政任用合同"},{"key":"B","text":"個人勞動合同"},{"key":"C","text":"編制外合同"},{"key":"D","text":"散位合同"}]', 'B', '第12/2015號法律第十七條', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-24', 'law', '根據現行《公共部門勞動合同制度》，以個人勞動合同的聘用須經：', '[{"key":"A","text":"行政公職局許可"},{"key":"B","text":"法務局許可"},{"key":"C","text":"行政長官許可"},{"key":"D","text":"行政法務司司長許可"}]', 'C', '第12/2015號法律第十八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-25', 'law', '根據現行《公共部門勞動合同制度》，除特別的情況外，任用工作人員以滿足臨時性或緊急性需求的合同的期間不可超過：', '[{"key":"A","text":"一年"},{"key":"B","text":"十八個月"},{"key":"C","text":"兩年"},{"key":"D","text":"三年"}]', 'A', '第12/2015號法律第二十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-26', 'law', '根據現行《公共部門勞動合同制度》，任用工作人員以滿足臨時性或緊急性需求的個人勞動合同可以例外續期的情況是：', '[{"key":"A","text":"嚴重事故"},{"key":"B","text":"災難"},{"key":"C","text":"不可抗力"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第二十一條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-27', 'law', '根據現行《公共部門勞動合同制度》，個人勞動合同於終止後多久內，公共部門不可與同一名工作人員訂立新的個人勞動合同？', '[{"key":"A","text":"一個月"},{"key":"B","text":"三個月"},{"key":"C","text":"六個月"},{"key":"D","text":"九個月"}]', 'B', '第12/2015號法律第二十一條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-28', 'law', '根據現行《公共部門勞動合同制度》，以個人勞動合同任用的工作人員適用以下哪些制度？', '[{"key":"A","text":"法例明確規定適用於公共部門以個人勞動合同聘用的工作人員的制度"},{"key":"B","text":"個人勞動合同的相關條款"},{"key":"C","text":"補充適用公職法律制度的規定"},{"key":"D","text":"以上皆是"}]', 'D', '第12/2015號法律第二十二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-29', 'law', '根據現行《公共部門勞動合同制度》，經十二月二十一日第 87/89/M 號法令核准的《澳門公共行政工作人員通則》第六編規定的紀律制度規範：', '[{"key":"A","text":"公共企業聘任的工作人員"},{"key":"B","text":"為滿足臨時性或緊急性的需求而聘用的工作人員"},{"key":"C","text":"受聘擔任顧問或專業技術職務的工作人員"},{"key":"D","text":"以上皆是"}]', 'C', '第12/2015號法律第二十二條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-contract-30', 'law', '根據現行《公共部門勞動合同制度》，在該制度生效之日以編制外合同或預先訂定期間的數位合同制度任用的工作人員，均視為以下列哪種制度任用？', '[{"key":"A","text":"個人勞動合同"},{"key":"B","text":"行政任用合同"},{"key":"C","text":"提供勞務合同"},{"key":"D","text":"批給合同"}]', 'B', '第12/2015號法律第二十四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-1', 'law', '現行《公共行政工作人員的工作表現評核一般制度》訂定包括任職在下列哪些機關或實體的公共行政工作人員的工作表現評核一般制度的補足規定？', '[{"key":"A","text":"法人機關"},{"key":"B","text":"自治基金"},{"key":"C","text":"A 或 B"},{"key":"D","text":"A 及 B"}]', 'D', '第31/2004號行政法規第一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-2', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，下列哪些人員不須接受工作表現評核：', '[{"key":"A","text":"擔任領導或等同領導官職的人員，包括擔任警察總局局長助理的人員"},{"key":"B","text":"警察總局及海關顧問官職的據位人"},{"key":"C","text":"以臨時定期委任制度執行職務的人員"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第一條第二款（一）、（三）及（四）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-3', 'law', '為適用現行《公共行政工作人員的工作表現評核一般制度》的規定，在每一公共部門或實體設立一個具諮詢性質的：', '[{"key":"A","text":"技術諮詢委員會"},{"key":"B","text":"評核諮詢委員會"},{"key":"C","text":"績效諮詢委員會"},{"key":"D","text":"績效技術委員會"}]', 'B', '第31/2004號行政法規第二條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-4', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，「評核諮詢委員會」的成員執行職務時態度應：', '[{"key":"A","text":"公平、公正及公開"},{"key":"B","text":"保密、公平及公正"},{"key":"C","text":"獨立、公正及無私"},{"key":"D","text":"保密、獨立及公正"}]', 'C', '第31/2004號行政法規第二條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-5', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評核諮詢委員會的組成及運作程序，以及其成員的甄選規則由誰以批示訂定？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"行政法務司司長"},{"key":"C","text":"行政公職局局長"},{"key":"D","text":"審計長"}]', 'A', '第31/2004號行政法規第二條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-6', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，任何工作人員不得在下列哪些人士的評核程序中被指定為評核人？', '[{"key":"A","text":"其配偶"},{"key":"B","text":"其直系姻親"},{"key":"C","text":"三親等內的旁系血親"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-7', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核程序屬：', '[{"key":"A","text":"公開"},{"key":"B","text":"部分公開"},{"key":"C","text":"部分保密"},{"key":"D","text":"保密"}]', 'D', '第31/2004號行政法規第四條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-8', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核是以甚麼制度為基準？', '[{"key":"A","text":"評語制度"},{"key":"B","text":"評分制度"},{"key":"C","text":"審查制度"},{"key":"D","text":"扣分制度"}]', 'B', '第31/2004號行政法規第五條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-9', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》的評分制度，下列哪些是工作人員必須接受評核的項目：', '[{"key":"A","text":"工作成效"},{"key":"B","text":"適應性及靈活性"},{"key":"C","text":"責任感"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第五條第一款（一）、（二）及（四）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-10', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，以下哪一項不屬評分制度內工作人員必須接受評核的項目：', '[{"key":"A","text":"不斷改善工作"},{"key":"B","text":"電子產品應用能力"},{"key":"C","text":"工作上的人際關係"},{"key":"D","text":"工作時間的管理"}]', 'B', '第31/2004號行政法規第五條第一款（三）、（五）及（七）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-11', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，按照所執行職務的性質，尚可依下列哪些項目評核工作人員的表現？', '[{"key":"A","text":"革新及創造力"},{"key":"B","text":"團隊工作"},{"key":"C","text":"與公眾的關係"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第五條第二款（二）、（四）及（五）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-12', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，在最終評分時，以下哪項評核項目作兩倍評分計算？', '[{"key":"A","text":"工作成效"},{"key":"B","text":"責任感"},{"key":"C","text":"A 及 B"},{"key":"D","text":"A 或 B"}]', 'C', '第31/2004號行政法規第七條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-13', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現的評核結果是以填寫經行政長官批示核准的甚麼方式表述？', '[{"key":"A","text":"評語表"},{"key":"B","text":"年資表"},{"key":"C","text":"評分表"},{"key":"D","text":"履歷表"}]', 'C', '第31/2004號行政法規第六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-14', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，將工作表現的評核結果表述出來的評分表須附有：', '[{"key":"A","text":"《評語指引》"},{"key":"B","text":"《評分指引》"},{"key":"C","text":"《績效指引》"},{"key":"D","text":"《履歷指引》"}]', 'B', '第31/2004號行政法規第六條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-15', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核是透過對工作人員須接受的每一評核項目的工作表現作量化評價後，以下列哪種方式表述？', '[{"key":"A","text":"工作質量評語"},{"key":"B","text":"工作效益評語"},{"key":"C","text":"工作能力評語"},{"key":"D","text":"工作數量評語"}]', 'A', '第31/2004號行政法規第七條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-16', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，不屬質量評語的是：', '[{"key":"A","text":"優異"},{"key":"B","text":"十分滿意"},{"key":"C","text":"不滿意"},{"key":"D","text":"劣等"}]', 'D', '第31/2004號行政法規第七條第二款（五）、（四）及（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-17', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，按工作人員在工作表現評核中所得分數，給予質量評語。下列哪一質量評語正確？', '[{"key":"A","text":"優異 - 8 分"},{"key":"B","text":"滿意 - 5 分"},{"key":"C","text":"不滿意 - 1 分"},{"key":"D","text":"十分滿意 - 6 分"}]', 'C', '第31/2004號行政法規第七條第二款（一）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-18', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，如最終評分結果出現小數，則以甚麼方式計算成整數？', '[{"key":"A","text":"四拾五入"},{"key":"B","text":"捨棄小數位"},{"key":"C","text":"進一"},{"key":"D","text":"以上皆不是"}]', 'A', '第31/2004號行政法規第七條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-19', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，不受特別評核或主管人員評核制度約束的所有工作人員，在評核所針對的曆年內實際服務時間至少為多久，均須接受平常評核？', '[{"key":"A","text":"三個月"},{"key":"B","text":"六個月"},{"key":"C","text":"九個月"},{"key":"D","text":"十一個月"}]', 'B', '第31/2004號行政法規第八條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-20', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，除已接受特別評核的期間或按主管人員評核制度被評核的期間，平常評核是針對上曆年哪段期間的工作表現？', '[{"key":"A","text":"一月一日至十二月三十一日"},{"key":"B","text":"三月一日至十二月三十一日"},{"key":"C","text":"六月一日至十二月三十一日"},{"key":"D","text":"九月一日至十二月三十一日"}]', 'A', '第31/2004號行政法規第八條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-21', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，擔任主管官職的人員的工作表現所涉及的評核期，自執行有關職務之日起計，一般為期：', '[{"key":"A","text":"三年"},{"key":"B","text":"半年"},{"key":"C","text":"兩年"},{"key":"D","text":"一年"}]', 'D', '第31/2004號行政法規第九條第二款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-22', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，在對擔任主管官職的人員的評核程序中，可讓該主管屬下的人員藉填寫經行政長官以批示核准的問卷對下列哪項發表意見？', '[{"key":"A","text":"主管的人際關係"},{"key":"B","text":"主管的工作表現"},{"key":"C","text":"主管的道德操守"},{"key":"D","text":"主管的衣著儀容"}]', 'B', '第31/2004號行政法規第九條第四款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-23', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，處於臨時委任的工作人員，如在評核所針對的年度內實際服務時間至少為多久，須接受特別評核？', '[{"key":"A","text":"一年"},{"key":"B","text":"十八個月"},{"key":"C","text":"六個月"},{"key":"D","text":"九個月"}]', 'C', '第31/2004號行政法規第十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-24', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，下列哪項工作人員，如在評核所針對的年度內實際服務時間至少為六個月，須接受特別評核？', '[{"key":"A","text":"處於臨時委任狀況者"},{"key":"B","text":"以合同受聘而於首兩年提供服務者"},{"key":"C","text":"處於轉變職程狀況的被定期委任者"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第十條第一款（一）至（三）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-25', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，「簡要評核」：', '[{"key":"A","text":"具獨立作用"},{"key":"B","text":"屬整體評核"},{"key":"C","text":"僅供在其後緊接進行平常評核或特別評核時按比例計分"},{"key":"D","text":"以上皆是"}]', 'C', '第31/2004號行政法規第十一條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-26', 'law', '下列哪項不屬現行《公共行政工作人員的工作表現評核一般制度》規定平常評核及特別評核的程序包括的階段？', '[{"key":"A","text":"指定評核人"},{"key":"B","text":"評核會議"},{"key":"C","text":"自我評核"},{"key":"D","text":"評核人與被評核人對質"}]', 'D', '第31/2004號行政法規第十二條第一款（一）、（二）及（四）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-27', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，每一評核人原則上不應負責評核超過多少名工作人員？', '[{"key":"A","text":"十"},{"key":"B","text":"二十"},{"key":"C","text":"三十"},{"key":"D","text":"四十"}]', 'B', '第31/2004號行政法規第十三條第五款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-28', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，被評核人可自獲悉評核結果之日起計多少日內，對評核人所評定的評核結果提出聲明異議？', '[{"key":"A","text":"三"},{"key":"B","text":"五"},{"key":"C","text":"七"},{"key":"D","text":"十"}]', 'D', '第31/2004號行政法規第二十條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-29', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，由負責認可的主管機關據位人擔任評核人時，對評核結果提出的聲明異議作決定前，必須聽取：', '[{"key":"A","text":"績效諮詢委員會的意見"},{"key":"B","text":"行政長官的意見"},{"key":"C","text":"評核諮詢委員會的意見"},{"key":"D","text":"行政公職局的意見"}]', 'C', '第31/2004號行政法規第二十條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-30', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，對認可及對由負責認可的主管機關據位人在程序中擔任評核人而給予的評核結果，被評核人可向有關部門或實體所屬施政領域的政府主要官員提起：', '[{"key":"A","text":"必要訴願"},{"key":"B","text":"任意訴願"},{"key":"C","text":"監督上訴"},{"key":"D","text":"司法上訴"}]', 'B', '第31/2004號行政法規第二十三條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-31', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，平常評核及特別評核的程序包括的階段有：', '[{"key":"A","text":"指定評核人"},{"key":"B","text":"評核人會議；評核會議"},{"key":"C","text":"自我評核；評分；認可"},{"key":"D","text":"以上皆是"}]', 'D', '第31/2004號行政法規第十二條第一款（一）至（六）項', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-32', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評核人應儘可能是被評核人的直屬上級，但亦可以是對被評核人的工作有較直接及實際了解的：', '[{"key":"A","text":"職務主管"},{"key":"B","text":"部門最高領導"},{"key":"C","text":"直屬下級"},{"key":"D","text":"以上皆不是"}]', 'A', '第31/2004號行政法規第十三條第三款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-law-official-perf-33', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，除另有規定外，評核程序包括在評核人會議後至多少期間內由評核人與被評核人舉行評核會議？', '[{"key":"A","text":"至該評核歷年的十二月三十一日"},{"key":"B","text":"至該評核歷年的十一月三十一日"},{"key":"C","text":"至翌年的一月十五日"},{"key":"D","text":"至翌年的四月一日前"}]', 'C', '第31/2004號行政法規第十六條第一款', '["260","430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-1', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區不實行下列哪種制度？', '[{"key":"A","text":"資本主義制度"},{"key":"B","text":"社會主義制度"},{"key":"C","text":"原有法律保留制度"},{"key":"D","text":"高度自治制度"}]', 'B', '《澳門特別行政區基本法》第五條：澳門特別行政區不實行社會主義的制度和政策，保持原有的資本主義制度和生活方式，五十年不變。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-2', 'law', '根據《澳門特別行政區基本法》，澳門原有的法律、法令、行政法規及其他規範性文件，除與本法相抵觸或經澳門特別行政區立法機關或其他有關機關依照法定程序修改者外，如何處理？', '[{"key":"A","text":"一律廢除"},{"key":"B","text":"一律修改"},{"key":"C","text":"予以保留"},{"key":"D","text":"予以暫停實施"}]', 'C', '《澳門特別行政區基本法》第八條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-3', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區區徽的圖案包括下列哪些元素？', '[{"key":"A","text":"五星、蓮花、大橋、海水"},{"key":"B","text":"蓮花、大橋、海水"},{"key":"C","text":"五星、蓮花"},{"key":"D","text":"大橋、海水"}]', 'A', '《澳門特別行政區基本法》第十條第一款：澳門特別行政區區徽中間是五星、蓮花、大橋、海水。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-4', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區法院對國防、外交等國家行為的事實問題是否有管轄權？', '[{"key":"A","text":"有完全管轄權"},{"key":"B","text":"有部分管轄權"},{"key":"C","text":"無管轄權"},{"key":"D","text":"視情況而定"}]', 'C', '《澳門特別行政區基本法》第十九條第三款：澳門特別行政區法院對國防、外交等國家行為無管轄權。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-5', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區可與外國簽署互免簽證協議，但須在下列哪個機關的協助或授權下進行？', '[{"key":"A","text":"全國人民代表大會"},{"key":"B","text":"全國人民代表大會常務委員會"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"澳門特別行政區立法會"}]', 'C', '《澳門特別行政區基本法》第一百四十條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-6', 'law', '根據《澳門特別行政區基本法》，外國在澳門特別行政區設立領事機構或其他官方機構，須經下列哪個機關許可？', '[{"key":"A","text":"澳門特別行政區政府"},{"key":"B","text":"澳門特別行政區立法會"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"全國人民代表大會常務委員會"}]', 'C', '《澳門特別行政區基本法》第一百四十二條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-7', 'law', '根據《澳門特別行政區基本法》，該法的修改權屬於下列哪個機關？', '[{"key":"A","text":"中央人民政府"},{"key":"B","text":"全國人民代表大會常務委員會"},{"key":"C","text":"全國人民代表大會"},{"key":"D","text":"澳門特別行政區立法會"}]', 'C', '《澳門特別行政區基本法》第一百四十四條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-8', 'law', '根據《澳門特別行政區基本法》，該法的解釋權屬於下列哪個機關？', '[{"key":"A","text":"中央人民政府"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"全國人民代表大會常務委員會"},{"key":"D","text":"澳門特別行政區終審法院"}]', 'C', '《澳門特別行政區基本法》第一百四十三條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-9', 'law', '根據《澳門特別行政區基本法》，行政長官因兩次拒絕簽署立法會通過的法案而解散立法會，重選的立法會仍以全體議員三分之二多數通過所爭議的原案，行政長官拒絕簽署時，行政長官必須：', '[{"key":"A","text":"再次解散立法會"},{"key":"B","text":"提請中央人民政府決定"},{"key":"C","text":"辭職"},{"key":"D","text":"將法案提交全民公投"}]', 'C', '《澳門特別行政區基本法》第五十四條（二）項。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-10', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區境內的土地和自然資源，除在澳門特別行政區成立以前已依法確認的私有土地外，屬於：', '[{"key":"A","text":"澳門特別行政區政府所有"},{"key":"B","text":"國家所有"},{"key":"C","text":"居民共有"},{"key":"D","text":"以上皆不是"}]', 'B', '《澳門特別行政區基本法》第七條：澳門特別行政區境內的土地和自然資源，除在澳門特別行政區成立以前已依法確認的私有土地外，屬於國家所有。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-11', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區可以「中國澳門」的名義參加不以國家為單位參加的國際組織和國際會議。此處「不以國家為單位」是指：', '[{"key":"A","text":"不以省為單位"},{"key":"B","text":"不以直轄市為單位"},{"key":"C","text":"不以國家為單位"},{"key":"D","text":"以上皆是"}]', 'C', '《澳門特別行政區基本法》第一百三十七條第二款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-12', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區成立時，澳門原有法律除由全國人民代表大會常務委員會宣布為同本法抵觸者外，採用為澳門特別行政區法律。如以後發現有的法律與本法抵觸，應如何處理？', '[{"key":"A","text":"由澳門特別行政區立法會自行修改或停止生效"},{"key":"B","text":"由全國人民代表大會常務委員會修改或停止生效"},{"key":"C","text":"由中央人民政府修改或停止生效"},{"key":"D","text":"維持不變"}]', 'B', '《澳門特別行政區基本法》第一百四十五條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-13', 'law', '根據《澳門特別行政區基本法》，下列哪類人員在就職時須依法宣誓效忠中華人民共和國澳門特別行政區？', '[{"key":"A","text":"行政長官、主要官員、立法會主席"},{"key":"B","text":"法官、檢察官"},{"key":"C","text":"行政會委員、立法會議員"},{"key":"D","text":"以上皆是"}]', 'D', '《澳門特別行政區基本法》第一百零一條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-14', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區立法會通過的法案，須經行政長官簽署、公佈後方能生效。若行政長官認為立法會通過的法案不符合澳門特別行政區的整體利益，可如何處理？', '[{"key":"A","text":"直接廢除該法案"},{"key":"B","text":"在九十日內將法案發回立法會審議"},{"key":"C","text":"提請中央人民政府裁決"},{"key":"D","text":"交由終審法院裁決"}]', 'B', '《澳門特別行政區基本法》第五十一條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-15', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區的行政機關、立法機關和司法機關除使用中文外，還可使用葡文。葡文是否為正式語文？', '[{"key":"A","text":"否"},{"key":"B","text":"是"},{"key":"C","text":"僅在司法程序中為正式語文"},{"key":"D","text":"僅在立法程序中為正式語文"}]', 'B', '《澳門特別行政區基本法》第九條：澳門特別行政區的正式語文為中文和葡文。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-16', 'law', '根據《澳門特別行政區基本法》，全國人民代表大會常務委員會在徵詢其所屬的澳門特別行政區基本法委員會的意見後，如認為澳門特別行政區立法機關制定的任何法律不符合基本法關於中央管理的事務及中央和澳門特別行政區關係的條款，可作何處理？', '[{"key":"A","text":"直接廢除該法律"},{"key":"B","text":"將有關法律發回，但不作修改"},{"key":"C","text":"將有關法律發回，發回即失效"},{"key":"D","text":"提請全國人民代表大會裁決"}]', 'C', '《澳門特別行政區基本法》第十七條第三款：發回的法律立即失效。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-17', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區的法官的選任和免職，由誰依照法定程序進行？', '[{"key":"A","text":"終審法院院長"},{"key":"B","text":"檢察長"},{"key":"C","text":"立法會"},{"key":"D","text":"行政長官"}]', 'D', '《澳門特別行政區基本法》第八十七條第二款、第八十八條第二款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-basic-extra-18', 'law', '根據《澳門特別行政區基本法》，澳門特別行政區檢察院獨立行使檢察職能，不受任何干涉。檢察長由誰任命？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"立法會"},{"key":"C","text":"中央人民政府"},{"key":"D","text":"全國人民代表大會常務委員會"}]', 'C', '《澳門特別行政區基本法》第九十條第二款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-1', 'law', '根據《中華人民共和國憲法》，中華人民共和國是下列哪種性質的國家？', '[{"key":"A","text":"工人階級領導的、以工農聯盟為基礎的人民民主專政的社會主義國家"},{"key":"B","text":"資產階級領導的資本主義國家"},{"key":"C","text":"多黨輪流執政的議會制國家"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國憲法》第一條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-2', 'law', '根據《中華人民共和國憲法》，中華人民共和國的一切權力屬於誰？', '[{"key":"A","text":"中國共產黨"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"人民"},{"key":"D","text":"國務院"}]', 'C', '《中華人民共和國憲法》第二條第一款：中華人民共和國的一切權力屬於人民。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-3', 'law', '根據《中華人民共和國憲法》，人民行使國家權力的機關是下列哪項？', '[{"key":"A","text":"國務院和地方各級人民政府"},{"key":"B","text":"全國人民代表大會和地方各級人民代表大會"},{"key":"C","text":"最高人民法院和地方各級人民法院"},{"key":"D","text":"中央軍事委員會"}]', 'B', '《中華人民共和國憲法》第二條第二款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-4', 'law', '根據《中華人民共和國憲法》，國家機構實行下列哪項原則？', '[{"key":"A","text":"三權分立原則"},{"key":"B","text":"民主集中制原則"},{"key":"C","text":"聯邦制原則"},{"key":"D","text":"君主立憲原則"}]', 'B', '《中華人民共和國憲法》第三條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-5', 'law', '根據《中華人民共和國憲法》，中華人民共和國實行依法治國，建設下列哪類國家？', '[{"key":"A","text":"社會主義法治國家"},{"key":"B","text":"資本主義法治國家"},{"key":"C","text":"人治國家"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國憲法》第五條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-6', 'law', '根據《中華人民共和國憲法》，國家在必要時得設立特別行政區。在特別行政區內實行的制度按照具體情況由下列哪個機關以法律規定？', '[{"key":"A","text":"國務院"},{"key":"B","text":"全國人民代表大會常務委員會"},{"key":"C","text":"全國人民代表大會"},{"key":"D","text":"中央人民政府"}]', 'C', '《中華人民共和國憲法》第三十一條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-7', 'law', '根據《中華人民共和國憲法》，中華人民共和國全國人民代表大會是下列哪類機關？', '[{"key":"A","text":"最高國家行政機關"},{"key":"B","text":"最高國家權力機關"},{"key":"C","text":"最高國家審判機關"},{"key":"D","text":"最高國家檢察機關"}]', 'B', '《中華人民共和國憲法》第五十七條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-8', 'law', '根據《中華人民共和國憲法》，全國人民代表大會的常設機關是下列哪項？', '[{"key":"A","text":"國務院"},{"key":"B","text":"中央軍事委員會"},{"key":"C","text":"全國人民代表大會常務委員會"},{"key":"D","text":"國家監察委員會"}]', 'C', '《中華人民共和國憲法》第五十七條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-9', 'law', '根據《中華人民共和國憲法》，有權修改憲法的機關是下列哪項？', '[{"key":"A","text":"全國人民代表大會常務委員會"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"國務院"},{"key":"D","text":"最高人民法院"}]', 'B', '《中華人民共和國憲法》第六十二條（一）項：全國人民代表大會行使修改憲法的職權。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-10', 'law', '根據《中華人民共和國憲法》，有權解釋憲法的機關是下列哪項？', '[{"key":"A","text":"全國人民代表大會"},{"key":"B","text":"全國人民代表大會常務委員會"},{"key":"C","text":"最高人民法院"},{"key":"D","text":"國務院"}]', 'B', '《中華人民共和國憲法》第六十七條（一）項。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-11', 'law', '根據《中華人民共和國憲法》，中華人民共和國國務院，即中央人民政府，是下列哪類機關？', '[{"key":"A","text":"最高國家權力機關"},{"key":"B","text":"最高國家權力機關的執行機關，是最高國家行政機關"},{"key":"C","text":"最高國家審判機關"},{"key":"D","text":"最高國家檢察機關"}]', 'B', '《中華人民共和國憲法》第八十五條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-12', 'law', '根據《中華人民共和國憲法》，中華人民共和國中央軍事委員會領導下列哪項？', '[{"key":"A","text":"全國監察工作"},{"key":"B","text":"全國武裝力量"},{"key":"C","text":"全國行政工作"},{"key":"D","text":"全國司法工作"}]', 'B', '《中華人民共和國憲法》第九十三條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-13', 'law', '根據《中華人民共和國憲法》，中華人民共和國各級監察委員會是國家的下列哪類機關？', '[{"key":"A","text":"審判機關"},{"key":"B","text":"檢察機關"},{"key":"C","text":"監察機關"},{"key":"D","text":"行政機關"}]', 'C', '《中華人民共和國憲法》第一百二十三條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-14', 'law', '根據《中華人民共和國憲法》，最高人民法院是下列哪類機關？', '[{"key":"A","text":"最高國家行政機關"},{"key":"B","text":"最高審判機關"},{"key":"C","text":"最高監察機關"},{"key":"D","text":"最高立法機關"}]', 'B', '《中華人民共和國憲法》第一百二十七條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-15', 'law', '根據《中華人民共和國憲法》，中華人民共和國國旗是下列哪項？', '[{"key":"A","text":"五星紅旗"},{"key":"B","text":"青天白日滿地紅旗"},{"key":"C","text":"蓮花綠旗"},{"key":"D","text":"以上皆不是"}]', 'A', '《中華人民共和國憲法》第一百三十四條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-16', 'law', '根據《中華人民共和國憲法》，中華人民共和國國徽，中間是五星照耀下的下列哪個建築，周圍是穀穗和齒輪？', '[{"key":"A","text":"人民大會堂"},{"key":"B","text":"天安門"},{"key":"C","text":"故宮"},{"key":"D","text":"長城"}]', 'B', '《中華人民共和國憲法》第一百三十五條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-17', 'law', '根據《中華人民共和國憲法》，中華人民共和國國歌是下列哪首歌曲？', '[{"key":"A","text":"《東方紅》"},{"key":"B","text":"《義勇軍進行曲》"},{"key":"C","text":"《歌唱祖國》"},{"key":"D","text":"《我的祖國》"}]', 'B', '《中華人民共和國憲法》第一百三十六條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-18', 'law', '根據《中華人民共和國憲法》，中華人民共和國首都是下列哪個城市？', '[{"key":"A","text":"上海"},{"key":"B","text":"廣州"},{"key":"C","text":"北京"},{"key":"D","text":"南京"}]', 'C', '《中華人民共和國憲法》第一百三十七條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-19', 'law', '根據《中華人民共和國憲法》，中華人民共和國主席、副主席由下列哪個機關選舉？', '[{"key":"A","text":"全國人民代表大會常務委員會"},{"key":"B","text":"全國人民代表大會"},{"key":"C","text":"國務院"},{"key":"D","text":"中央軍事委員會"}]', 'B', '《中華人民共和國憲法》第六十二條（四）項、第七十九條第一款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-constitution-extra-20', 'law', '根據《中華人民共和國憲法》，最高人民檢察院是下列哪類機關？', '[{"key":"A","text":"最高審判機關"},{"key":"B","text":"最高行政機關"},{"key":"C","text":"最高檢察機關"},{"key":"D","text":"最高監察機關"}]', 'C', '《中華人民共和國憲法》第一百二十七條第二款。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-1', 'law', '第2/1999號法律《政府組織綱要法》自何日起生效？', '[{"key":"A","text":"1999年12月19日"},{"key":"B","text":"1999年12月20日"},{"key":"C","text":"1999年12月25日"},{"key":"D","text":"2000年1月1日"}]', 'B', '第2/1999號法律公布於1999年12月20日《澳門特別行政區公報》，自公布之日起生效。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-2', 'law', '根據《政府組織綱要法》，廉政專員對誰負責？', '[{"key":"A","text":"立法會"},{"key":"B","text":"終審法院院長"},{"key":"C","text":"行政長官"},{"key":"D","text":"中央人民政府"}]', 'C', '第2/1999號法律第六條：廉政公署、審計署獨立工作，廉政專員、審計長對行政長官負責。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-3', 'law', '根據《政府組織綱要法》，審計長對誰負責？', '[{"key":"A","text":"立法會"},{"key":"B","text":"終審法院院長"},{"key":"C","text":"行政長官"},{"key":"D","text":"中央人民政府"}]', 'C', '第2/1999號法律第六條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-4', 'law', '根據《政府組織綱要法》，行政長官短期不能履行職務時，依法定順序由各司司長臨時代理。若行政法務司司長亦缺位，則由哪個司的司長代理？', '[{"key":"A","text":"保安司"},{"key":"B","text":"社會文化司"},{"key":"C","text":"經濟財政司"},{"key":"D","text":"運輸工務司"}]', 'C', '第2/1999號法律第十一條：按第五條各司排列順序，行政法務司、經濟財政司、保安司、社會文化司、運輸工務司，故第二順序為經濟財政司司長。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-5', 'law', '根據《政府組織綱要法》，本法依據《澳門特別行政區基本法》的哪一項規定制定？', '[{"key":"A","text":"第四十八條"},{"key":"B","text":"第五十條"},{"key":"C","text":"第七十一條"},{"key":"D","text":"第九十條"}]', 'C', '第2/1999號法律序言：立法會根據《澳門特別行政區基本法》第七十一條（一）項，制定本法律。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-6', 'law', '根據《政府組織綱要法》，政府架構由上而下依次序設司、局、廳、處。其中「廳」與「處」的關係為：', '[{"key":"A","text":"廳高於處"},{"key":"B","text":"處高於廳"},{"key":"C","text":"廳與處同級"},{"key":"D","text":"以上皆不是"}]', 'A', '第2/1999號法律第三條：司、局、廳、處，由上而下，故廳高於處。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-7', 'law', '根據《政府組織綱要法》，澳門特別行政區政府各司的排列順序，第二個為：', '[{"key":"A","text":"行政法務司"},{"key":"B","text":"經濟財政司"},{"key":"C","text":"保安司"},{"key":"D","text":"社會文化司"}]', 'B', '第2/1999號法律第五條第一款：行政法務司、經濟財政司、保安司、社會文化司及運輸工務司。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-8', 'law', '根據《政府組織綱要法》，下列哪一項屬於政府主要官員？', '[{"key":"A","text":"立法會主席"},{"key":"B","text":"終審法院院長"},{"key":"C","text":"海關關長"},{"key":"D","text":"檢察長"}]', 'C', '第2/1999號法律第四條：主要官員包括各司司長、廉政專員、審計長、警察總局局長、海關關長等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-9', 'law', '根據《政府組織綱要法》，行政長官及主要官員自何時起履行職務？', '[{"key":"A","text":"任命之日起"},{"key":"B","text":"就任之日起"},{"key":"C","text":"宣誓之日起"},{"key":"D","text":"公布之日起"}]', 'B', '第2/1999號法律第九條：行政長官及主要官員自就任之日起履行職務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-10', 'law', '根據《政府組織綱要法》，政府對立法會負責，其中每年至少向立法會作幾次施政報告？', '[{"key":"A","text":"零次"},{"key":"B","text":"一次"},{"key":"C","text":"兩次"},{"key":"D","text":"四次"}]', 'B', '第2/1999號法律第十三條：政府每年至少向立法會作施政報告一次。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-11', 'law', '根據《政府組織綱要法》，行政長官出缺時，在新的行政長官產生前，由誰代理行政長官職務？', '[{"key":"A","text":"立法會主席"},{"key":"B","text":"各司司長按順序輪流"},{"key":"C","text":"終審法院院長"},{"key":"D","text":"中央人民政府指定"}]', 'B', '第2/1999號法律第十二條：行政長官出缺時，由各司司長按第五條規定的順序代理。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-12', 'law', '根據《政府組織綱要法》，澳門特別行政區設立廉政公署及審計署，兩者在工作上：', '[{"key":"A","text":"從屬於政府各司"},{"key":"B","text":"獨立工作"},{"key":"C","text":"對立法會負責"},{"key":"D","text":"對終審法院負責"}]', 'B', '第2/1999號法律第六條：廉政公署、審計署獨立工作。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-13', 'law', '根據《政府組織綱要法》，政府可根據需要設立諮詢組織。除法規另有規定外，該等組織的意見：', '[{"key":"A","text":"對政府具約束力"},{"key":"B","text":"對政府不具約束力"},{"key":"C","text":"對立法會具約束力"},{"key":"D","text":"對行政長官具約束力"}]', 'B', '第2/1999號法律第十九條第二款：諮詢組織的意見除法律另有規定外，不具約束力。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-14', 'law', '根據《政府組織綱要法》，行政長官向立法會宣讀施政報告的時機為：', '[{"key":"A","text":"每屆立法會任期開始時"},{"key":"B","text":"每年立法會會期開始時"},{"key":"C","text":"每月一次"},{"key":"D","text":"以上皆不是"}]', 'B', '第2/1999號法律第十四條：行政長官每年向立法會作施政報告，向立法會宣讀施政報告。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-gov-extra-15', 'law', '根據《政府組織綱要法》，澳門特別行政區政府由上而下設司、局、廳、處。下列哪一級別不屬於該架構？', '[{"key":"A","text":"司"},{"key":"B","text":"局"},{"key":"C","text":"科"},{"key":"D","text":"廳"}]', 'C', '第2/1999號法律第三條：架構為司、局、廳、處；科、組為局、廳下屬的內部單位，非法律明列的「四級」架構。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-1', 'law', '第6/1999號行政法規《政府部門及實體的組織、職權與運作》是行政長官根據《澳門特別行政區基本法》的哪一項規定制定的？', '[{"key":"A","text":"第五十條"},{"key":"B","text":"第六十二條"},{"key":"C","text":"第六十四條"},{"key":"D","text":"第七十一條"}]', 'C', '第6/1999號行政法規序言：行政長官根據《澳門特別行政區基本法》第六十四條，經徵詢行政會意見，制定本行政法規。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-2', 'law', '第6/1999號行政法規《政府部門及實體的組織、職權與運作》由誰制定？', '[{"key":"A","text":"立法會"},{"key":"B","text":"行政長官"},{"key":"C","text":"行政會"},{"key":"D","text":"中央人民政府"}]', 'B', '第6/1999號行政法規序言：行政長官根據《澳門特別行政區基本法》第六十四條，經徵詢行政會意見，制定本行政法規。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-3', 'law', '根據第6/1999號行政法規，行政長官制定本行政法規前須徵詢下列哪個機關的意見？', '[{"key":"A","text":"立法會"},{"key":"B","text":"終審法院"},{"key":"C","text":"行政會"},{"key":"D","text":"檢察院"}]', 'C', '第6/1999號行政法規序言：經徵詢行政會意見，制定本行政法規。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-4', 'law', '根據第6/1999號行政法規，本行政法規的補充規定由誰核准？', '[{"key":"A","text":"立法會"},{"key":"B","text":"行政會"},{"key":"C","text":"行政長官"},{"key":"D","text":"各司司長"}]', 'C', '第6/1999號行政法規第七條：本行政法規的補充規定由行政長官核准。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-5', 'law', '根據第6/1999號行政法規，政府各部門及實體的組織法由誰核准？', '[{"key":"A","text":"立法會"},{"key":"B","text":"行政會"},{"key":"C","text":"行政長官"},{"key":"D","text":"各司司長"}]', 'C', '第6/1999號行政法規第八條：各部門及實體的組織法由行政長官核准；其他補充規定由行政長官批示為之。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-6', 'law', '第6/1999號行政法規《政府部門及實體的組織、職權與運作》自何日起生效？', '[{"key":"A","text":"1999年12月19日"},{"key":"B","text":"1999年12月20日"},{"key":"C","text":"1999年12月21日"},{"key":"D","text":"2000年1月1日"}]', 'C', '第6/1999號行政法規第十一條：本行政法規自公佈翌日起生效。公報日期為1999年12月20日，「翌日」即次日，故生效日為1999年12月21日。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-7', 'law', '根據第6/1999號行政法規，下列哪個司的司長在「法律推廣；司法援助」領域行使職權？', '[{"key":"A","text":"經濟財政司"},{"key":"B","text":"保安司"},{"key":"C","text":"行政法務司"},{"key":"D","text":"社會文化司"}]', 'C', '第6/1999號行政法規第二條：行政法務司司長職權包括法律推廣、司法援助等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-8', 'law', '根據第6/1999號行政法規，下列哪個司的司長在「貨幣、匯兌及金融體系」領域行使職權？', '[{"key":"A","text":"行政法務司"},{"key":"B","text":"經濟財政司"},{"key":"C","text":"保安司"},{"key":"D","text":"運輸工務司"}]', 'B', '第6/1999號行政法規第三條：經濟財政司司長職權包括貨幣、匯兌及金融體系，包括保險業務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-9', 'law', '根據第6/1999號行政法規，下列哪個司的司長在「澳門特別行政區的內部治安；刑事偵查」領域行使職權？', '[{"key":"A","text":"行政法務司"},{"key":"B","text":"經濟財政司"},{"key":"C","text":"保安司"},{"key":"D","text":"社會文化司"}]', 'C', '第6/1999號行政法規第四條：保安司司長職權包括內部治安、刑事偵查。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-10', 'law', '根據第6/1999號行政法規，下列哪個司的司長在「教育；衛生；文化」領域行使職權？', '[{"key":"A","text":"經濟財政司"},{"key":"B","text":"保安司"},{"key":"C","text":"社會文化司"},{"key":"D","text":"運輸工務司"}]', 'C', '第6/1999號行政法規第五條：社會文化司司長職權包括教育、衛生、文化、體育、社會保障等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-11', 'law', '根據第6/1999號行政法規，下列哪個司的司長在「土地的整治；基礎建設及公共工程；氣象」領域行使職權？', '[{"key":"A","text":"行政法務司"},{"key":"B","text":"經濟財政司"},{"key":"C","text":"社會文化司"},{"key":"D","text":"運輸工務司"}]', 'D', '第6/1999號行政法規第六條：運輸工務司司長職權包括土地的整治、基礎建設及公共工程、氣象等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-12', 'law', '第6/1999號行政法規規範的對象除「政府部門」外，還包括「實體」。下列哪項通常屬該法規所指的「實體」？', '[{"key":"A","text":"立法會"},{"key":"B","text":"法院"},{"key":"C","text":"自治基金組織及項目組等附屬單位"},{"key":"D","text":"中央人民政府駐澳機構"}]', 'C', '第6/1999號行政法規名稱及條文：規範政府部門及實體的組織、職權與運作；實體包括自治基金、項目組、工作組等附屬單位。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-dept-extra-13', 'law', '根據第6/1999號行政法規，各司司長職權的補充或變更，須依何種程序為之？', '[{"key":"A","text":"立法會法律"},{"key":"B","text":"行政長官批示"},{"key":"C","text":"行政會決議"},{"key":"D","text":"各司司長自行決定"}]', 'B', '第6/1999號行政法規第二至六條均規定：補充或變更職權須由行政長官批示為之，並須遵守該行政法規的規定。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-1', 'law', '《行政程序法典》由下列哪一項法令核准？', '[{"key":"A","text":"第56/99/M號法令"},{"key":"B","text":"第57/99/M號法令"},{"key":"C","text":"第58/99/M號法令"},{"key":"D","text":"第59/99/M號法令"}]', 'B', '十月十一日第57/99/M號法令核准《行政程序法典》。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-2', 'law', '根據《行政程序法典》的結構，該法典分為幾個部分？', '[{"key":"A","text":"兩個部分"},{"key":"B","text":"三個部分"},{"key":"C","text":"四個部分"},{"key":"D","text":"五個部分"}]', 'C', '《行政程序法典》分為四部分：第一部分總則、第二部分主體、第三部分行政程序、第四部分行政行為。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-3', 'law', '《行政程序法典》第一部分「總則」包括下列哪些編？', '[{"key":"A","text":"序言及定義、公共行政當局"},{"key":"B","text":"行政程序、行政行為"},{"key":"C","text":"主體、行政合同"},{"key":"D","text":"以上皆不是"}]', 'A', '第一部分總則包括第一編序言及定義、第二編公共行政當局。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-4', 'law', '根據《行政程序法典》，「一合意，基於此合意而設定、變更或消滅一行政法律關係」是下列哪一項用語的概念？', '[{"key":"A","text":"行政行為"},{"key":"B","text":"行政卷宗"},{"key":"C","text":"行政程序"},{"key":"D","text":"行政合同"}]', 'D', '《行政程序法典》第一百六十五條第一款：行政合同係指一合意，基於此合意而設定、變更或消滅一行政法律關係。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-5', 'law', '根據《行政程序法典》，除特別法另有規定外，行政程序是否須繳付費用？', '[{"key":"A","text":"有償"},{"key":"B","text":"無償"},{"key":"C","text":"由行政當局自由裁量"},{"key":"D","text":"由利害關係人選擇"}]', 'B', '《行政程序法典》第十三條：除特別法另有規定外，行政程序為無償。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-6', 'law', '根據《行政程序法典》，行政程序得依職權開始，或應下列何者之申請而開始？', '[{"key":"A","text":"僅限利害關係人"},{"key":"B","text":"利害關係人及以維護其利益為宗旨之團體"},{"key":"C","text":"僅限公共部門"},{"key":"D","text":"以上皆不是"}]', 'B', '《行政程序法典》規定程序得依職權開始，或應利害關係人及以維護其利益為宗旨之團體之申請而開始。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-7', 'law', '根據《行政程序法典》，必要訴願應向下列哪一機關提起？', '[{"key":"A","text":"作出行為者"},{"key":"B","text":"作出行為者之上級"},{"key":"C","text":"終審法院"},{"key":"D","text":"立法會"}]', 'B', '《行政程序法典》第一百五十五條：必要訴願向作出行為者之上級提起。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-8', 'law', '根據《行政程序法典》，在法律特別規定的情況下，在為作出決定而定之期間內，如有權限之行政機關未對向其提出之要求作出最終決定，則可產生下列哪一效果？', '[{"key":"A","text":"推定該要求被駁回"},{"key":"B","text":"推定該要求獲默示批准"},{"key":"C","text":"推定該要求仍然待決"},{"key":"D","text":"推定程序消滅"}]', 'B', '《行政程序法典》第一百零二條：無特別法規定時推定默示駁回；法律特別規定時則可產生默示批准等效果。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-9', 'law', '根據《行政程序法典》，合議機關之主席除擔任會議主持外，尚有權：', '[{"key":"A","text":"代任秘書"},{"key":"B","text":"將會議紀要存檔"},{"key":"C","text":"在表決時投決定性一票"},{"key":"D","text":"以上皆是"}]', 'C', '《行政程序法典》第十六條等：主席在表決時投決定性一票（票數相同時）。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-10', 'law', '根據《行政程序法典》，授權者得隨時收回授權；授權之收回須公布於下列何處？', '[{"key":"A","text":"報章"},{"key":"B","text":"《澳門政府公報》"},{"key":"C","text":"政府入口網站"},{"key":"D","text":"部門告示板"}]', 'B', '《行政程序法典》第三十九條：授權或轉授權行為須公布於《澳門政府公報》；收回亦然。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-11', 'law', '根據《行政程序法典》，行政行為在產生效力前，應自何時起通知相對人？', '[{"key":"A","text":"作出之日起"},{"key":"B","text":"作出之翌日起"},{"key":"C","text":"公布之日起"},{"key":"D","text":"法律另有規定者從其規定"}]', 'D', '《行政程序法典》第一百一十九條等：行政行為須通知相對人；法律對生效或通知另有規定者從其規定。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-12', 'law', '根據《行政程序法典》，可撤銷之行政行為在未經有權限機關撤銷前：', '[{"key":"A","text":"不產生任何效力"},{"key":"B","text":"產生效力"},{"key":"C","text":"僅產生部分效力"},{"key":"D","text":"視乎相對人是否知悉而定"}]', 'B', '可撤銷之行政行為在未經撤銷前仍產生效力；無效之行政行為則不產生效力。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-13', 'law', '根據《行政程序法典》，利害關係人申請之補正：行政機關應定出不少於多少日之期間，讓利害關係人補正申請內之缺陷或呈交未附同之文件？', '[{"key":"A","text":"七日"},{"key":"B","text":"十日"},{"key":"C","text":"十五日"},{"key":"D","text":"二十日"}]', 'B', '《行政程序法典》規定應定出不少於十日之期間讓利害關係人補正。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-14', 'law', '根據《行政程序法典》第四部分，行政行為之「通知」與「公布」之區別，下列何者正確？', '[{"key":"A","text":"通知針對特定相對人，公布針對不特定人"},{"key":"B","text":"公布針對特定相對人，通知針對不特定人"},{"key":"C","text":"兩者完全相同"},{"key":"D","text":"僅法律行為須通知，無須公布"}]', 'A', '通知係向特定相對人作出；公布係將行政行為之內容使不特定人知悉（如刊登公報）。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-proc-extra-15', 'law', '根據《行政程序法典》，監督上訴係針對下列何者所作之行政行為提起？', '[{"key":"A","text":"作出行為者之上級"},{"key":"B","text":"受監督或監管之公法人"},{"key":"C","text":"私法人"},{"key":"D","text":"立法會"}]', 'B', '《行政程序法典》第一百六十四條：監督上訴之標的為受監督或監管之公法人所作之行政行為。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-1', 'law', '現行《澳門公共行政工作人員通則》由下列哪一項法令核准？', '[{"key":"A","text":"第86/89/M號法令"},{"key":"B","text":"第87/89/M號法令"},{"key":"C","text":"第88/89/M號法令"},{"key":"D","text":"第89/89/M號法令"}]', 'B', '《澳門公共行政工作人員通則》由第87/89/M號法令核准，公佈於第51/1989號《澳門政府公報》。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-2', 'law', '《澳門公共行政工作人員通則》最初公佈於哪一年《澳門政府公報》？', '[{"key":"A","text":"1988年"},{"key":"B","text":"1989年"},{"key":"C","text":"1990年"},{"key":"D","text":"1991年"}]', 'B', '該通則公佈於1989年12月21日第51/1989號《澳門政府公報》。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-3', 'law', '根據《澳門公共行政工作人員通則》，「公務員」係指以何種方式任用之工作人員？', '[{"key":"A","text":"僅以編制外合同"},{"key":"B","text":"僅以散位合同"},{"key":"C","text":"以確定委任、定期委任或臨時委任方式"},{"key":"D","text":"以個人勞動合同"}]', 'C', '通則第二條：公務員係指以確定委任、定期委任或臨時委任方式任用之工作人員。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-4', 'law', '根據《澳門公共行政工作人員通則》，「服務人員」係指以何種方式任用之工作人員？', '[{"key":"A","text":"確定委任"},{"key":"B","text":"定期委任"},{"key":"C","text":"臨時委任"},{"key":"D","text":"編制外合同或散位合同"}]', 'D', '通則第二條：服務人員係指以編制外合同或散位合同方式任用之工作人員。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-5', 'law', '根據《澳門公共行政工作人員通則》，除領導及主管人員外，進入編制內職位之臨時委任期滿後，如符合法定條件，可轉為：', '[{"key":"A","text":"定期委任"},{"key":"B","text":"編制外合同"},{"key":"C","text":"確定委任"},{"key":"D","text":"散位合同"}]', 'C', '通則規定，臨時委任期滿且符合條件者，可轉為確定委任。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-6', 'law', '根據《澳門公共行政工作人員通則》，公務員之「徵用」係指：', '[{"key":"A","text":"在保留原職位之情況下，暫時在另一部門或實體擔任職務"},{"key":"B","text":"確定性轉往另一部門"},{"key":"C","text":"因工作需要而派往外地"},{"key":"D","text":"以上皆不是"}]', 'A', '徵用係指在保留原職位之情況下，暫時在另一部門或實體擔任職務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-7', 'law', '根據《澳門公共行政工作人員通則》，公務員之「派駐」係指：', '[{"key":"A","text":"在保留原職位之情況下，暫時在另一部門擔任職務"},{"key":"B","text":"確定性調往另一部門之編制內職位"},{"key":"C","text":"僅在澳門特別行政區以外工作"},{"key":"D","text":"以上皆不是"}]', 'A', '派駐係指在保留原職位之情況下，暫時在另一部門擔任職務；調任係確定性轉往另一部門之編制內職位。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-8', 'law', '根據《澳門公共行政工作人員通則》，服務時間對下列哪一項具重要性？', '[{"key":"A","text":"僅晉階"},{"key":"B","text":"僅退休"},{"key":"C","text":"晉階、晉升、假期之批給、退休及撫卹"},{"key":"D","text":"僅撫卹"}]', 'C', '通則第一百五十六條：服務時間對職程內之晉階及晉升、假期之批給、退休及撫卹等具重要性。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-9', 'law', '根據《澳門公共行政工作人員通則》，工作人員在紀律程序中被命令防範性停職，如其後未被科處處分，則防範性停職期間：', '[{"key":"A","text":"不視作實際服務時間"},{"key":"B","text":"視作實際服務時間"},{"key":"C","text":"按部門領導決定"},{"key":"D","text":"減半計算"}]', 'B', '通則第一百五十七條：如隨後被科處處分，防範性停職期間不視作實際服務時間；如未被科處處分，則視作實際服務時間。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-10', 'law', '根據《澳門公共行政工作人員通則》，退休人員之退休金計算公式中，服務年數最高為多少年？', '[{"key":"A","text":"三十年"},{"key":"B","text":"三十二年"},{"key":"C","text":"三十四年"},{"key":"D","text":"三十六年"}]', 'D', '通則第二百六十四條：退休金相等於作為計算基礎之薪俸之三十六分之一乘以為退休而計算之服務年數，服務年數最高為三十六年。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-11', 'law', '根據《澳門公共行政工作人員通則》，撫卹金權利人包括：', '[{"key":"A","text":"僅配偶"},{"key":"B","text":"僅尚存之配偶及直系血親尊親屬"},{"key":"C","text":"尚存之配偶、直系血親尊親屬及直系血親卑親屬等"},{"key":"D","text":"僅直系血親卑親屬"}]', 'C', '通則規定撫卹金權利人包括尚存之配偶、符合條件之直系血親尊親屬及直系血親卑親屬等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-12', 'law', '根據《澳門公共行政工作人員通則》，公務員或服務人員對因擔任職務而獲悉之非公開之事實負有何種義務？', '[{"key":"A","text":"服從之義務"},{"key":"B","text":"熱心之義務"},{"key":"C","text":"保密之義務"},{"key":"D","text":"守時之義務"}]', 'C', '通則第二百七十九條第七款：公務員或服務人員有義務對因擔任其職務而獲悉之非公開之事實保守職業秘密。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-13', 'law', '根據《澳門公共行政工作人員通則》，公務員或服務人員有義務以尊重、有教養之態度對待公共部門之使用者、同事、上級及下屬。此義務稱為：', '[{"key":"A","text":"無私之義務"},{"key":"B","text":"熱心之義務"},{"key":"C","text":"有禮之義務"},{"key":"D","text":"勤謹之義務"}]', 'C', '通則第二百七十九條第八款規定有禮之義務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-14', 'law', '根據《澳門公共行政工作人員通則》，除另有訂定之特別年齡限制外，錄取進入公職編制之最低年齡為：', '[{"key":"A","text":"十六歲"},{"key":"B","text":"十七歲"},{"key":"C","text":"十八歲"},{"key":"D","text":"二十歲"}]', 'C', '通則第十一條第一款：除另有訂定之特別年齡限制外，錄取進入公職編制之年齡限制為最低十八歲、最高五十歲。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-15', 'law', '根據《澳門公共行政工作人員通則》，撤職處分導致公務員或服務人員：', '[{"key":"A","text":"僅兩年內不得擔任公職"},{"key":"B","text":"喪失一切權利，且不影響法律規定之禁止"},{"key":"C","text":"僅喪失退休金"},{"key":"D","text":"以上皆不是"}]', 'B', '通則第三百一十一條：撤職處分導致公務員或服務人員喪失一切權利，且不影響法律規定之禁止。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-16', 'law', '根據《澳門公共行政工作人員通則》，與人員有關且影響其職務上之法律狀況之一切行為，有關部門應在多少日內通知行政公職局？', '[{"key":"A","text":"五日內"},{"key":"B","text":"十日內"},{"key":"C","text":"十五日內"},{"key":"D","text":"二十日內"}]', 'C', '通則第三十九條第一款：與人員有關且影響其職務上之法律狀況之一切行為，均應由有關部門在十五日內通知行政公職局。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-17', 'law', '根據《澳門公共行政工作人員通則》，下列哪一項不屬該通則適用範圍內之實體？', '[{"key":"A","text":"自治機關"},{"key":"B","text":"自治基金組織"},{"key":"C","text":"私人團體"},{"key":"D","text":"以上皆不是"}]', 'C', '通則第一條：適用於澳門行政當局公共部門之人員，包括自治機關及自治基金組織，不包括私人團體。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-estatuto-extra-18', 'law', '根據《澳門公共行政工作人員通則》，「當然兼任」係指因何者之規定而必須擔任另一職務？', '[{"key":"A","text":"行政法規"},{"key":"B","text":"法律"},{"key":"C","text":"行政長官批示"},{"key":"D","text":"部門領導批示"}]', 'B', '通則第十八條第一款：當然兼任係指擔任一公共職務時，因法律之規定而必須擔任另一職務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-1', 'law', '根據現行《公務人員職程制度》，薪俸以薪俸點訂定，其計算公式為：', '[{"key":"A","text":"Q = V ÷ I × 100"},{"key":"B","text":"Q = V × I ÷ 100"},{"key":"C","text":"Q = V + I"},{"key":"D","text":"Q = V − I"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第四條第二款：Q 為薪俸金額、V 為薪俸表內一百點的對應金額、I 為薪俸點；Q = V × I ÷ 100。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-2', 'law', '根據現行《公務人員職程制度》，薪俸表載於何處？', '[{"key":"A","text":"法律正文"},{"key":"B","text":"法律附件一"},{"key":"C","text":"行政法規"},{"key":"D","text":"行政公職局通告"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第四條第三款：薪俸表載於附件一，薪俸以薪俸點一百點的對應金額、乘以薪俸點計算。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-3', 'law', '根據現行《公務人員職程制度》，晉階所需的工作表現評核須取得不低於「滿意」的評語；如屬第一職等或第二職等，評核須與何者看齊？', '[{"key":"A","text":"第三職等"},{"key":"B","text":"第四職等"},{"key":"C","text":"其他職等"},{"key":"D","text":"無須看齊"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第五條第一款：如屬第一職等或第二職等，工作表現評核須與其他職等看齊。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-4', 'law', '根據現行《公務人員職程制度》，在該法律規定的情況下，晉階所需的工作表現評核能否以金錢代替？', '[{"key":"A","text":"可以"},{"key":"B","text":"經部門領導批准可以"},{"key":"C","text":"不可以"},{"key":"D","text":"法律無規定"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第五條第六款：晉階所需的工作表現評核不得以金錢代替。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-5', 'law', '根據現行《公務人員職程制度》，如人員在原職階的服務時間內的工作表現評核均取得「優異」的評語，可否縮短晉階所需的服務時間？', '[{"key":"A","text":"不可以"},{"key":"B","text":"可以，具體由行政法規訂定"},{"key":"C","text":"僅在垂直職程可以"},{"key":"D","text":"僅在橫向職程可以"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第五條第七款：如取得「優異」評語，可縮短晉階所需的服務時間，具體由行政法規訂定。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-6', 'law', '根據現行《公務人員職程制度》，除另有規定外，如屬晉階與晉級均須符合的情況，須如何處理？', '[{"key":"A","text":"僅符合晉階要件即可"},{"key":"B","text":"僅符合晉級要件即可"},{"key":"C","text":"須同時符合晉階及晉級的要件"},{"key":"D","text":"由部門選擇其一"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第五條第五款：如屬晉階與晉級均須符合的情況，須同時符合兩者的要件。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-7', 'law', '根據現行《公務人員職程制度》，人員進入職程須透過何種方式？', '[{"key":"A","text":"僅可透過開考"},{"key":"B","text":"僅可透過轉入"},{"key":"C","text":"透過開考或轉入"},{"key":"D","text":"由部門直接委任"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第十二條第一款：人員進入職程須透過開考或轉入。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-8', 'law', '根據現行《公務人員職程制度》，職務主管的擔任須透過何種方式？', '[{"key":"A","text":"部門領導直接委任"},{"key":"B","text":"僅透過開考"},{"key":"C","text":"透過開考或符合法定條件的轉任"},{"key":"D","text":"僅透過晉級"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第五十二條：職務主管須透過開考或符合法定條件的轉任方式擔任。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-9', 'law', '根據現行《公務人員職程制度》，法規草擬職務須由何人擔任？', '[{"key":"A","text":"任何編制內人員"},{"key":"B","text":"具法學學士學位且經開考錄取的人員"},{"key":"C","text":"僅由法務局人員"},{"key":"D","text":"僅由顧問"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第五十三條第一款：法規草擬職務須由具法學學士學位且經開考錄取的人員擔任。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-10', 'law', '根據現行《公務人員職程制度》，「特別職程」的正確定義為：', '[{"key":"A","text":"與各公共部門的共同工作範疇相對應的職程"},{"key":"B","text":"與一個或多個公共部門的特定職務相對應的職程，而基於相關職務內容的特徵，該等職程有本身的入職規定、進程及所需具備的資格要件或專業要件"},{"key":"C","text":"一系列不同的薪酬級別"},{"key":"D","text":"職務內容相同的各個職級的序列"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第二條（二）項：特別職程係指與一個或多個公共部門的特定職務相對應的職程，而基於相關職務內容的特徵，該等職程有本身的入職規定、進程及所需具備的資格要件或專業要件。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-11', 'law', '根據現行《公務人員職程制度》，技術員職務內容的一般特徵為：', '[{"key":"A","text":"創造"},{"key":"B","text":"應用"},{"key":"C","text":"執行"},{"key":"D","text":"領導"}]', 'B', '經第4/2017號法律修改的第14/2009號法律附件一表二：高級技術員為創造、技術員為應用、技術輔助人員為執行。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-12', 'law', '根據現行《公務人員職程制度》，高級技術員職程與特別職程的對應關係，下列何者正確？', '[{"key":"A","text":"公關督導員對應高級技術員"},{"key":"B","text":"傳譯及翻譯對應技術員"},{"key":"C","text":"登記及公證範疇由專有法規規範"},{"key":"D","text":"以上皆非"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第十九條第二款：教育、保安、衛生、司法、文贖、登記及公證等範疇的特別職程由專有法規規範。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-13', 'law', '根據現行《公務人員職程制度》，在橫向職程內晉升至第二職階，如在原職階的服務時間內的工作表現評核均取得「滿意」，須在原職階服務滿多少年？', '[{"key":"A","text":"半年"},{"key":"B","text":"一年"},{"key":"C","text":"二年"},{"key":"D","text":"三年"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第十三條第二款（一）項：如屬晉升至第二職階，須在原職階服務滿一年。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-14', 'law', '根據現行《公務人員職程制度》，除另有規定外，晉升至職程內的最高職等時，如人員在該段服務時間內的工作表現評核取得「十分滿意」，須在原職等服務滿多少年？', '[{"key":"A","text":"六年"},{"key":"B","text":"七年"},{"key":"C","text":"八年"},{"key":"D","text":"九年"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第十四條第一款（一）項：晉升至最高職等須在原職等服務滿九年且評核不低於「滿意」，或滿八年且評核不低於「十分滿意」。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-15', 'law', '根據現行《公務人員職程制度》，訂定一般職程及存在於多個公共部門的特別職程的職務內容的權限屬於：', '[{"key":"A","text":"法務局"},{"key":"B","text":"行政公職局"},{"key":"C","text":"各用人部門"},{"key":"D","text":"行政長官"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第三條第一款：行政公職局具有職權訂定一般職程及存在於多個公共部門的特別職程的職務內容。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-16', 'law', '根據現行《公務人員職程制度》，下列哪一項不屬該法律第一條第四款規定不適用的人員？', '[{"key":"A","text":"按專有人員通則獲任用的人員"},{"key":"B","text":"在澳門特別行政區駐外辦事處按其駐在地法例擔任職務的人員"},{"key":"C","text":"在公共部門按職程制度獲任用的人員"},{"key":"D","text":"由公共企業、公共團體任用的人員"}]', 'C', '經第4/2017號法律修改的第14/2009號法律第一條第四款：不適用於按專有人員通則獲任用、擔任顧問和專業技術職務、駐外辦事處人員、職務由專有法規規範者、公共企業等任用的人員；在公共部門按職程制度獲任用者則適用本法律。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-17', 'law', '根據現行《公務人員職程制度》，傳譯及翻譯職務的每月附加報酬的訂定方式為：', '[{"key":"A","text":"由行政法規訂定"},{"key":"B","text":"相當於薪俸表內薪俸點一百點的百分之五十"},{"key":"C","text":"與法規草擬職務相同"},{"key":"D","text":"由行政公職局訂定"}]', 'A', '經第4/2017號法律修改的第14/2009號法律第五十四條：傳譯及翻譯職務的附加報酬由行政法規訂定；法規草擬為一百點的百分之五十至一百；法律筆譯為一百點的百分之五十。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-career-extra-18', 'law', '根據現行《公務人員職程制度》，人員組別包括：', '[{"key":"A","text":"僅高級技術員、技術員"},{"key":"B","text":"高級技術員、技術員、技術輔助人員、工人"},{"key":"C","text":"僅領導及主管"},{"key":"D","text":"僅特別職程人員"}]', 'B', '經第4/2017號法律修改的第14/2009號法律第二條（五）項及附件一表二：人員組別按職務內容的一般特徵界定，包括高級技術員、技術員、技術輔助人員、工人等。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-1', 'law', '現行《公共部門勞動合同制度》的立法依據為：', '[{"key":"A","text":"《澳門公共行政工作人員通則》第六編"},{"key":"B","text":"《澳門公共行政工作人員通則》第七十一條"},{"key":"C","text":"《公務人員職程制度》"},{"key":"D","text":"《行政程序法典》"}]', 'B', '第12/2015號法律第一條：本法律訂定公共部門勞動合同制度；立法會根據《澳門特別行政區基本法》第七十一條（一）項制定本法律，源自通則第七十一條。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-2', 'law', '根據現行《公共部門勞動合同制度》，行政任用合同須以何種方式訂立？', '[{"key":"A","text":"口頭協議即可"},{"key":"B","text":"書面"},{"key":"C","text":"經公證書"},{"key":"D","text":"由行政長官批示核准"}]', 'B', '第12/2015號法律第四條第一款：行政任用合同須以書面訂立。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-3', 'law', '根據現行《公共部門勞動合同制度》，在試用期內，任一方可否單方終止行政任用合同？', '[{"key":"A","text":"不可以"},{"key":"B","text":"可以，且不構成無理解僱"},{"key":"C","text":"僅公共部門可以"},{"key":"D","text":"僅工作人員可以"}]', 'B', '第12/2015號法律第四條第二款：在試用期內，任一方可單方終止合同，且不構成無理解僱。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-4', 'law', '根據現行《公共部門勞動合同制度》，試用期是否計入為晉階及晉級而計算的服務時間？', '[{"key":"A","text":"全部計入"},{"key":"B","text":"計入一半"},{"key":"C","text":"不計入"},{"key":"D","text":"由部門決定"}]', 'C', '經第2/2021號法律等修改的第12/2015號法律第五條：試用期不計入為晉階及晉級而計算的服務時間。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-5', 'law', '根據現行《公共部門勞動合同制度》，行政任用合同首次訂立的期間一般不超過兩年；第一次續期的期間最長為：', '[{"key":"A","text":"六個月"},{"key":"B","text":"一年"},{"key":"C","text":"兩年"},{"key":"D","text":"三年"}]', 'C', '第12/2015號法律第六條：除特別規定外，行政任用合同的期間一般不超過兩年；續期可為兩年；滿兩年且兩次十分滿意後修改為長期三年。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-6', 'law', '根據現行《公共部門勞動合同制度》，下列何者屬行政任用合同的終止方式？', '[{"key":"A","text":"解除"},{"key":"B","text":"經雙方協議、由任一方提出、失效"},{"key":"C","text":"撤職"},{"key":"D","text":"開除"}]', 'B', '第12/2015號法律第十條：行政任用合同的終止方式為經雙方協議、由任一方提出、失效；「解除」並非終止方式之一。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-7', 'law', '根據現行《公共部門勞動合同制度》，公共部門在下列哪種情況下可解除行政任用合同？', '[{"key":"A","text":"合同期滿"},{"key":"B","text":"工作人員在試用期內的工作表現評核中取得「不滿意」的評語"},{"key":"C","text":"工作人員自行離職"},{"key":"D","text":"雙方協議終止"}]', 'B', '第12/2015號法律第十一條：僅在試用期內工作表現評核不滿意、或終止職務為實習或入職培訓制度所規定的後果等情況下，公共部門可解除合同。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-8', 'law', '根據現行《公共部門勞動合同制度》，公共部門經監督實體許可終止行政任用合同時，須最少提前多少日以書面通知工作人員？', '[{"key":"A","text":"三十日"},{"key":"B","text":"六十日"},{"key":"C","text":"九十日"},{"key":"D","text":"一百二十日"}]', 'B', '第12/2015號法律第十二條第二款：經公共部門所屬的監督實體許可，公共部門可在最少提前六十日以書面通知工作人員後終止行政任用合同。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-9', 'law', '根據現行《公共部門勞動合同制度》，行政任用合同在下列哪種情況下失效？', '[{"key":"A","text":"工作人員晉階"},{"key":"B","text":"工作人員達到擔任公職的最高年齡限制"},{"key":"C","text":"部門改組"},{"key":"D","text":"合同續期"}]', 'B', '第12/2015號法律第十五條：失效情況包括當工作人員達到擔任公職的最高年齡限制、處於長期絕對無擔任職務的能力、屬調職時自新合同開始擔任職務之日起。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-10', 'law', '根據現行《公共部門勞動合同制度》，屬調職的情況，原行政任用合同自何時起失效？', '[{"key":"A","text":"提出調職申請之日"},{"key":"B","text":"監督實體許可之日"},{"key":"C","text":"工作人員按新行政任用合同開始擔任職務之日起"},{"key":"D","text":"原部門發出同意書之日"}]', 'C', '第12/2015號法律第十五條（三）項：屬調職的情況下，則自該工作人員按新行政任用合同開始擔任職務之日起失效。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-11', 'law', '根據現行《公共部門勞動合同制度》，以個人勞動合同任用工作人員以滿足臨時性或緊急性需求時，合同期間除例外續期外，不可超過：', '[{"key":"A","text":"六個月"},{"key":"B","text":"一年"},{"key":"C","text":"十八個月"},{"key":"D","text":"兩年"}]', 'B', '第12/2015號法律第二十一條第一款：除特別情況外，任用工作人員以滿足臨時性或緊急性需求的合同的期間不可超過一年。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-12', 'law', '根據現行《公共部門勞動合同制度》，個人勞動合同終止後，在多少期間內公共部門不可與同一名工作人員訂立新的個人勞動合同？', '[{"key":"A","text":"一個月"},{"key":"B","text":"三個月"},{"key":"C","text":"六個月"},{"key":"D","text":"十二個月"}]', 'B', '第12/2015號法律第二十一條第四款：個人勞動合同於終止後三個月內，公共部門不可與同一名工作人員訂立新的個人勞動合同。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-13', 'law', '根據現行《公共部門勞動合同制度》，以行政任用合同任用的工作人員，除該法律另有規定外，適用下列何者？', '[{"key":"A","text":"勞動關係法"},{"key":"B","text":"公職法律制度"},{"key":"C","text":"僅個人勞動合同條款"},{"key":"D","text":"民法典"}]', 'B', '第12/2015號法律第七條：除本法律另有規定外，以行政任用合同任用的工作人員適用公職法律制度的規定。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-14', 'law', '根據現行《公共部門勞動合同制度》，本法律生效之日已以編制外合同或預先訂定期間的數位合同制度任用的工作人員，均視為以何種合同任用？', '[{"key":"A","text":"個人勞動合同"},{"key":"B","text":"行政任用合同"},{"key":"C","text":"散位合同"},{"key":"D","text":"提供勞務合同"}]', 'B', '第12/2015號法律第二十四條第一款：在本法律生效之日以編制外合同或預先訂定期間的數位合同制度任用的工作人員，均視為以行政任用合同任用。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-15', 'law', '根據現行《公共部門勞動合同制度》，僅在專業人員短缺或擬聘用的人員具特別才能的情況下，方可以個人勞動合同聘用人員擔任：', '[{"key":"A","text":"一般行政職務"},{"key":"B","text":"顧問或專業技術職務"},{"key":"C","text":"勤雜人員"},{"key":"D","text":"技術輔助人員"}]', 'B', '第12/2015號法律第十七條：僅在專業人員短缺或擬聘用的人員具特別才能的情況下，方可以個人勞動合同聘用澳門特別行政區或以外的工作人員擔任顧問或專業技術職務。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-16', 'law', '根據現行《公共部門勞動合同制度》，經十二月二十一日第87/89/M號法令核准的《澳門公共行政工作人員通則》第六編規定的紀律制度，適用於下列哪類以個人勞動合同聘用的人員？', '[{"key":"A","text":"為滿足臨時性或緊急性需求而聘用的人員"},{"key":"B","text":"擔任顧問或專業技術職務的人員"},{"key":"C","text":"僅編制內人員"},{"key":"D","text":"以上皆不適用"}]', 'B', '第12/2015號法律第二十二條第二款：通則第六編規定的紀律制度規範受聘擔任顧問或專業技術職務的工作人員。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-17', 'law', '根據現行《公共部門勞動合同制度》，工作人員以不具期限的行政任用合同提供服務，如由工作人員提出或經雙方協議而終止合同，可在終止日起計多少時間內向原公共部門申請重新聘用？', '[{"key":"A","text":"一年內"},{"key":"B","text":"兩年內"},{"key":"C","text":"三年內"},{"key":"D","text":"五年內"}]', 'B', '第12/2015號法律第八條第一款：如不具期限的行政任用合同由工作人員提出或經雙方協議而終止，工作人員可在行政任用合同終止日起計兩年內向原公共部門申請重新聘用。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-contract-extra-18', 'law', '根據現行《公共部門勞動合同制度》，重新聘用除須由公共部門所屬的監督實體許可外，申請人在終止行政任用合同之日緊接前多少年的工作表現評核中均須取得不低於「十分滿意」的評語？', '[{"key":"A","text":"三年"},{"key":"B","text":"五年"},{"key":"C","text":"七年"},{"key":"D","text":"十年"}]', 'B', '第12/2015號法律第八條第二款（二）項：申請人在終止行政任用合同之日緊接前五年的工作表現評核中均須取得不低於「十分滿意」的評語。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-1', 'law', '現行《公共行政工作人員的工作表現評核一般制度》是根據下列何者制定的補足規定？', '[{"key":"A","text":"第14/2009號法律"},{"key":"B","text":"第8/2004號法律"},{"key":"C","text":"第12/2015號法律"},{"key":"D","text":"第2/2001號法律"}]', 'B', '第31/2004號行政法規第一條：本行政法規訂定公共行政工作人員的工作表現評核一般制度的補足規定；根據第8/2004號法律《公共行政工作人員通則》第四條第二款的規定，經考慮諮詢組織的意見，制定本行政法規。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-2', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評核諮詢委員會的性質為：', '[{"key":"A","text":"決策機關"},{"key":"B","text":"執行機關"},{"key":"C","text":"具諮詢性質"},{"key":"D","text":"監督機關"}]', 'C', '第31/2004號行政法規第二條第一款：為適用本行政法規的規定，在每一公共部門或實體設立一個具諮詢性質的評核諮詢委員會。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-3', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核應以何種方式進行？', '[{"key":"A","text":"公開方式"},{"key":"B","text":"無私方式"},{"key":"C","text":"簡化方式"},{"key":"D","text":"書面方式"}]', 'B', '第31/2004號行政法規第三條第一款：工作表現評核應以無私方式進行。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-4', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核的結果是以質量評語表述。下列哪一組分數與質量評語的對應正確？', '[{"key":"A","text":"優異：7 至 8 分"},{"key":"B","text":"十分滿意：9 至 10 分"},{"key":"C","text":"滿意：5 至 6 分"},{"key":"D","text":"不大滿意：1 至 2 分"}]', 'C', '第31/2004號行政法規第七條第二款：按所得分數給予質量評語，通常優異為 9-10 分、十分滿意為 7-8 分、滿意為 5-6 分、不大滿意為 3-4 分、不滿意為 1-2 分。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-5', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，下列哪項屬質量評語？', '[{"key":"A","text":"劣等"},{"key":"B","text":"優異"},{"key":"C","text":"及格"},{"key":"D","text":"不及格"}]', 'B', '第31/2004號行政法規第七條第二款：質量評語包括優異、十分滿意、滿意、不大滿意、不滿意；「劣等」不屬該制度規定的質量評語。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-6', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評核的種類包括：', '[{"key":"A","text":"平常評核、特別評核、簡要評核、主管人員評核"},{"key":"B","text":"僅平常評核與特別評核"},{"key":"C","text":"僅定期評核與臨時評核"},{"key":"D","text":"僅年度評核與季度評核"}]', 'A', '第31/2004號行政法規規定評核種類包括平常評核、特別評核、簡要評核及主管人員評核制度。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-7', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，「簡要評核」在下列哪種情況下進行？', '[{"key":"A","text":"實際服務時間滿六個月時"},{"key":"B","text":"實際服務時間不足六個月時"},{"key":"C","text":"僅對主管人員"},{"key":"D","text":"僅對合同人員"}]', 'B', '第31/2004號行政法規第十一條：簡要評核僅供在其後緊接進行平常評核或特別評核時按比例計分，通常適用於實際服務時間不足六個月等情況。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-8', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，平常評核及特別評核的程序包括「認可」階段。認可由誰作出？', '[{"key":"A","text":"評核人"},{"key":"B","text":"被評核人"},{"key":"C","text":"負責認可的主管機關據位人"},{"key":"D","text":"評核諮詢委員會"}]', 'C', '第31/2004號行政法規第十二條第一款：程序階段包括指定評核人、評核人會議、評核會議、自我評核、評分、認可；認可由負責認可的主管機關據位人作出。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-9', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，對認可及對由負責認可的主管機關據位人在程序中擔任評核人而給予的評核結果，被評核人可提起的訴願為：', '[{"key":"A","text":"必要訴願"},{"key":"B","text":"任意訴願"},{"key":"C","text":"僅可聲明異議"},{"key":"D","text":"僅可司法上訴"}]', 'B', '第31/2004號行政法規第二十三條第一款：對認可及對由負責認可的主管機關據位人在程序中擔任評核人而給予的評核結果，被評核人可向有關部門或實體所屬施政領域的政府主要官員提起任意訴願。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-10', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，被評核人提起的訴願應向誰提出？', '[{"key":"A","text":"行政長官"},{"key":"B","text":"行政公職局"},{"key":"C","text":"有關部門或實體所屬施政領域的政府主要官員"},{"key":"D","text":"評核諮詢委員會"}]', 'C', '第31/2004號行政法規第二十三條第一款：被評核人可向有關部門或實體所屬施政領域的政府主要官員提起任意訴願。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-11', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評分表須經誰批示核准？', '[{"key":"A","text":"行政法務司司長"},{"key":"B","text":"行政公職局局長"},{"key":"C","text":"行政長官"},{"key":"D","text":"部門領導"}]', 'C', '第31/2004號行政法規第六條第一款：工作表現的評核結果是以填寫經行政長官批示核准的評分表方式表述。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-12', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，由負責認可的主管機關據位人擔任評核人時，對評核結果提出的聲明異議作決定前，必須聽取哪個委員會的意見？', '[{"key":"A","text":"績效諮詢委員會"},{"key":"B","text":"技術諮詢委員會"},{"key":"C","text":"評核諮詢委員會"},{"key":"D","text":"紀律委員會"}]', 'C', '第31/2004號行政法規第二十條第三款：由負責認可的主管機關據位人擔任評核人時，對聲明異議作決定前，必須聽取評核諮詢委員會的意見。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-13', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評分制度內工作人員必須接受評核的項目包括「不斷改善工作」、「工作時間的管理」以及：', '[{"key":"A","text":"電子產品應用能力"},{"key":"B","text":"工作成效、適應性及靈活性、責任感、工作上的人際關係"},{"key":"C","text":"僅團隊工作"},{"key":"D","text":"僅與公眾的關係"}]', 'B', '第31/2004號行政法規第五條第一款：必須評核項目包括工作成效、適應性及靈活性、不斷改善工作、責任感、工作時間的管理、工作上的人際關係等；電子產品應用能力不屬必須項目。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-14', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，除另有規定外，評核人與被評核人舉行評核會議的期限為評核人會議後至翌年何日？', '[{"key":"A","text":"十二月三十一日"},{"key":"B","text":"十一月三十日"},{"key":"C","text":"一月十五日"},{"key":"D","text":"四月一日"}]', 'C', '第31/2004號行政法規第十六條第一款：除另有規定外，評核程序包括在評核人會議後至翌年一月十五日由評核人與被評核人舉行評核會議。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-15', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，以合同受聘而於首兩年提供服務的工作人員，如在評核所針對的年度內實際服務時間至少為六個月，須接受何種評核？', '[{"key":"A","text":"平常評核"},{"key":"B","text":"簡要評核"},{"key":"C","text":"特別評核"},{"key":"D","text":"主管人員評核"}]', 'C', '第31/2004號行政法規第十條第一款（二）項：以合同受聘而於首兩年提供服務者，如在評核所針對的年度內實際服務時間至少為六個月，須接受特別評核。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-16', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核的結果對下列哪項具效力？', '[{"key":"A","text":"僅晉階"},{"key":"B","text":"僅晉級"},{"key":"C","text":"晉階、晉級及職程制度所定的其他效力"},{"key":"D","text":"僅用於培訓"}]', 'C', '第31/2004號行政法規規定評核結果對晉階、晉級及職程制度所定的其他效力具重要性。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-17', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，下列哪類人員不須接受工作表現評核？', '[{"key":"A","text":"以編制外合同任用的人員"},{"key":"B","text":"以散位合同任用的人員"},{"key":"C","text":"擔任領導或等同領導官職的人員"},{"key":"D","text":"處於臨時委任的人員"}]', 'C', '第31/2004號行政法規第一條第二款：擔任領導或等同領導官職的人員、警察總局及海關顧問官職的據位人、以臨時定期委任制度執行職務的人員等不須接受工作表現評核。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('law-perf-extra-18', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，評分表須附有何種指引？', '[{"key":"A","text":"《評語指引》"},{"key":"B","text":"《評分指引》"},{"key":"C","text":"《績效指引》"},{"key":"D","text":"《晉階指引》"}]', 'B', '第31/2004號行政法規第六條第三款：將工作表現的評核結果表述出來的評分表須附有《評分指引》。', '["260","430","both"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-math-3', 'math', '若 5x + 7 = 22，則 x = ?', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]', 'B', '5x = 22 - 7 = 15，故 x = 3。', '["430"]');
