INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-401', 'chart', 'Excel 儲存格要固定欄與列不隨複製改變，應使用？', '[{"key":"A","text":"相對參照"},{"key":"B","text":"絕對參照 $A$1"},{"key":"C","text":"混合參照"},{"key":"D","text":"名稱管理員"}]', 'B', '絕對參照以 $ 鎖定欄列，如 $A$1。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-402', 'chart', 'Excel 中 B2 公式 =A1*A2，複製到 C3 後，C3 公式變為？', '[{"key":"A","text":"=A1*A2"},{"key":"B","text":"=B2*B3"},{"key":"C","text":"=C2*C3"},{"key":"D","text":"=A2*A3"}]', 'B', '相對參照：列、欄各+1，故 C3 為 B2/B3。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-403', 'chart', '下列哪種格式的影片可直接插入 PowerPoint 投影片？', '[{"key":"A","text":"MP3"},{"key":"B","text":"WMV"},{"key":"C","text":"WMA"},{"key":"D","text":"MID"}]', 'B', 'PowerPoint 支援 WMV 等視訊格式；MP3/WMA 為音訊。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-404', 'chart', 'Word「合併列印」可選取的文件類型不包括？', '[{"key":"A","text":"信函"},{"key":"B","text":"信封"},{"key":"C","text":"標籤"},{"key":"D","text":"目錄"}]', 'D', '合併列印常用信函、信封、標籤，目錄通常不經合併列印產生。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-405', 'chart', 'Excel 中 $A1 表示？', '[{"key":"A","text":"絕對欄 A、相對列"},{"key":"B","text":"相對欄、絕對列 1"},{"key":"C","text":"絕對欄與列"},{"key":"D","text":"錯誤公式"}]', 'A', '$A1 為混合參照：欄 A 固定、列隨複製改變。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-406', 'chart', '要讓 Excel 公式中的列不隨複製改變，應寫成？', '[{"key":"A","text":"A$1"},{"key":"B","text":"$A1"},{"key":"C","text":"A1"},{"key":"D","text":"$A$1"}]', 'A', 'A$1 表示列 1 固定、欄隨複製改變。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-407', 'chart', 'PowerPoint 投影片可嵌入下列哪種視訊格式？', '[{"key":"A","text":"MP4"},{"key":"B","text":"FLAC"},{"key":"C","text":"WMA"},{"key":"D","text":"MID"}]', 'A', 'PowerPoint 支援 MP4、WMV 等視訊格式。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-408', 'chart', 'Excel 儲存格 A1=10、A2=20，B1 公式 =A1+A2，複製 B1 到 C2 後 C2 公式為？', '[{"key":"A","text":"=A1+A2"},{"key":"B","text":"=B2+B3"},{"key":"C","text":"=A2+A3"},{"key":"D","text":"=B1+B2"}]', 'B', '相對參照：B1→C2 欄+1、列+1，故 A1→B2、A2→B3。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-409', 'chart', 'Word 郵件合併時「選取收件者」不包含？', '[{"key":"A","text":"建立新清單"},{"key":"B","text":"使用現有清單"},{"key":"C","text":"從 Outlook 連絡人選擇"},{"key":"D","text":"從網絡郵件連絡人選擇"}]', 'D', 'Word 合併列印收件者來源不含「從網絡郵件連絡人選擇」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-410', 'chart', 'Excel 中若要計算 A1 到 A10 總和，公式應為？', '[{"key":"A","text":"=SUM(A1:A10)"},{"key":"B","text":"=TOTAL(A1:A10)"},{"key":"C","text":"=ADD(A1:A10)"},{"key":"D","text":"=A1+A10"}]', 'A', 'SUM 為加總函數，A1:A10 為範圍。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-411', 'chart', '下列何者為 Excel 的絕對參照寫法？', '[{"key":"A","text":"A1"},{"key":"B","text":"$A$1"},{"key":"C","text":"A$1"},{"key":"D","text":"1A"}]', 'B', '絕對參照以 $ 鎖定欄與列：$A$1。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-412', 'chart', 'PowerPoint 可插入的媒體類型不包括？', '[{"key":"A","text":"影片"},{"key":"B","text":"音訊"},{"key":"C","text":"螢幕錄製"},{"key":"D","text":"資料庫連線"}]', 'D', '投影片可插入影片、音訊、螢幕錄製，不直接插入資料庫連線。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-413', 'chart', 'Excel 儲存格顯示 #DIV/0! 表示？', '[{"key":"A","text":"除數為零"},{"key":"B","text":"參照錯誤"},{"key":"C","text":"數值溢位"},{"key":"D","text":"格式錯誤"}]', 'A', '#DIV/0! 表示公式中有除以零。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-414', 'chart', 'Word 合併列印「插入合併欄位」用途為？', '[{"key":"A","text":"插入固定文字"},{"key":"B","text":"插入資料來源欄位"},{"key":"C","text":"插入圖片"},{"key":"D","text":"插入表格"}]', 'B', '合併欄位會從資料來源（如 Excel）帶入對應欄位值。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-415', 'chart', 'Excel 中 A1=5、B1=3，C1 公式 =A1*B1，複製 C1 到 D2 後 D2 公式為？', '[{"key":"A","text":"=A1*B1"},{"key":"B","text":"=B2*C2"},{"key":"C","text":"=A2*B2"},{"key":"D","text":"=C1*D1"}]', 'B', '相對參照：C1→D2，A1→B2、B1→C2。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-416', 'chart', '下列哪種檔案可作為 Word 合併列印的資料來源？', '[{"key":"A","text":"Excel 活頁簿"},{"key":"B","text":"PDF"},{"key":"C","text":"圖片"},{"key":"D","text":"影片"}]', 'A', '合併列印常用 Excel 或 Access 等作為資料來源。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-417', 'chart', 'Excel 中 A2 輸入 100，B2 公式 =$A2*2，複製 B2 到 C3 後 C3 公式為？', '[{"key":"A","text":"=$A2*2"},{"key":"B","text":"=$A3*2"},{"key":"C","text":"=$B3*2"},{"key":"D","text":"=A3*2"}]', 'B', '$A 鎖定欄、列不鎖定，故複製到 C3 仍為 $A3*2。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-418', 'chart', 'PowerPoint 投影片放映時按 B 鍵會？', '[{"key":"A","text":"下一張"},{"key":"B","text":"上一張"},{"key":"C","text":"黑屏"},{"key":"D","text":"結束放映"}]', 'C', '放映時 B 鍵可切換黑屏、W 鍵可切換白屏。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-419', 'chart', 'Excel 中 A1:A5 為 10,20,30,40,50，=AVERAGE(A1:A5) 結果為？', '[{"key":"A","text":"30"},{"key":"B","text":"35"},{"key":"C","text":"150"},{"key":"D","text":"25"}]', 'A', '平均 = (10+20+30+40+50)/5 = 30。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-420', 'chart', 'Word 中「目錄」功能通常依據？', '[{"key":"A","text":"手動輸入"},{"key":"B","text":"標題樣式"},{"key":"C","text":"字型大小"},{"key":"D","text":"粗體"}]', 'B', '目錄依標題樣式（如標題 1、標題 2）自動產生。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-421', 'chart', 'Excel 儲存格顯示 ##### 可能表示？', '[{"key":"A","text":"除零錯誤"},{"key":"B","text":"欄寬不足"},{"key":"C","text":"參照錯誤"},{"key":"D","text":"公式錯誤"}]', 'B', '數值過長、欄寬不足時會顯示 #####。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-422', 'chart', '下列何者不是 PowerPoint 可插入的物件？', '[{"key":"A","text":"圖表"},{"key":"B","text":"方程式"},{"key":"C","text":"視訊"},{"key":"D","text":"資料庫查詢"}]', 'D', '投影片可插入圖表、方程式、視訊，不直接插入資料庫查詢。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-423', 'chart', 'Excel 中 =COUNT(A1:A10) 會計算？', '[{"key":"A","text":"總和"},{"key":"B","text":"平均"},{"key":"C","text":"數值儲存格個數"},{"key":"D","text":"最大值"}]', 'C', 'COUNT 計算範圍內含數值的儲存格個數。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-424', 'chart', 'Word 表格中要將多個儲存格合併為一個，應使用？', '[{"key":"A","text":"分割儲存格"},{"key":"B","text":"合併儲存格"},{"key":"C","text":"插入列"},{"key":"D","text":"刪除欄"}]', 'B', '「合併儲存格」可將選取的多格合併為一格。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-425', 'chart', 'Excel 中 =MAX(A1:A5) 會傳回？', '[{"key":"A","text":"總和"},{"key":"B","text":"平均"},{"key":"C","text":"最大值"},{"key":"D","text":"個數"}]', 'C', 'MAX 傳回範圍內最大值。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-426', 'chart', 'PowerPoint 投影片編號可透過何處插入？', '[{"key":"A","text":"插入→頁首及頁尾"},{"key":"B","text":"設計→主題"},{"key":"C","text":"動畫"},{"key":"D","text":"轉場"}]', 'A', '「插入」→「頁首及頁尾」可勾選投影片編號。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-427', 'chart', 'Excel 中 A1=8、A2=12，=A1+A2 結果為？', '[{"key":"A","text":"8"},{"key":"B","text":"12"},{"key":"C","text":"20"},{"key":"D","text":"96"}]', 'C', '8 + 12 = 20。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-428', 'chart', 'Word 中要讓每頁顯示相同標題列，應使用？', '[{"key":"A","text":"分節符號"},{"key":"B","text":"重複標題列"},{"key":"C","text":"頁首"},{"key":"D","text":"書籤"}]', 'B', '表格「版面配置」→「重複標題列」可在每頁重複表頭。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-429', 'chart', 'Excel 中 =MIN(A1:A5) 會傳回？', '[{"key":"A","text":"總和"},{"key":"B","text":"平均"},{"key":"C","text":"最小值"},{"key":"D","text":"個數"}]', 'C', 'MIN 傳回範圍內最小值。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-430', 'chart', '下列哪種為 Excel 的範圍參照？', '[{"key":"A","text":"A1"},{"key":"B","text":"A1:A10"},{"key":"C","text":"$A$1"},{"key":"D","text":"A1+B1"}]', 'B', 'A1:A10 表示從 A1 到 A10 的範圍。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-431', 'chart', 'PowerPoint 中「母片」的用途為？', '[{"key":"A","text":"單張投影片動畫"},{"key":"B","text":"統一設定所有投影片版式"},{"key":"C","text":"插入影片"},{"key":"D","text":"轉場效果"}]', 'B', '母片可統一設定版式、字型、位置等。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-432', 'chart', 'Excel 中 =SUM(A1,A3,A5) 會計算？', '[{"key":"A","text":"A1 到 A5 總和"},{"key":"B","text":"A1、A3、A5 三格總和"},{"key":"C","text":"平均"},{"key":"D","text":"個數"}]', 'B', 'SUM(A1,A3,A5) 只加總這三個儲存格。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-433', 'chart', 'Word 中「分欄」功能在何處？', '[{"key":"A","text":"插入"},{"key":"B","text":"版面配置"},{"key":"C","text":"參考資料"},{"key":"D","text":"校閱"}]', 'B', '「版面配置」→「欄」可設定分欄。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-434', 'chart', 'Excel 儲存格格式為「數值」、輸入 0.5，若顯示 50%，表示？', '[{"key":"A","text":"格式錯誤"},{"key":"B","text":"儲存格格式為百分比"},{"key":"C","text":"公式錯誤"},{"key":"D","text":"參照錯誤"}]', 'B', '百分比格式會將 0.5 顯示為 50%。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-435', 'chart', 'PowerPoint 投影片可設定「切換」效果，即？', '[{"key":"A","text":"動畫"},{"key":"B","text":"轉場"},{"key":"C","text":"母片"},{"key":"D","text":"版面配置"}]', 'B', '「切換」或「轉場」為投影片之間的過場效果。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-436', 'chart', 'Excel 中 =ROUND(3.14159,2) 結果為？', '[{"key":"A","text":"3"},{"key":"B","text":"3.14"},{"key":"C","text":"3.141"},{"key":"D","text":"3.1"}]', 'B', 'ROUND(數值,2) 四捨五入到小數第 2 位。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-437', 'chart', 'Word 中「醒目提示」用途為？', '[{"key":"A","text":"標記文字背景色"},{"key":"B","text":"插入註解"},{"key":"C","text":"追蹤修訂"},{"key":"D","text":"字型顏色"}]', 'A', '醒目提示可為文字加上背景色標記。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-438', 'chart', 'Excel 中 A1=100，B1 公式 =A1*0.1，則 B1 顯示？', '[{"key":"A","text":"10"},{"key":"B","text":"100"},{"key":"C","text":"0.1"},{"key":"D","text":"1000"}]', 'A', '100 × 0.1 = 10。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-439', 'chart', 'PowerPoint 中「動畫」與「轉場」的差異為？', '[{"key":"A","text":"相同"},{"key":"B","text":"動畫作用於物件、轉場作用於投影片切換"},{"key":"C","text":"僅轉場可設定"},{"key":"D","text":"僅動畫可設定"}]', 'B', '動畫用於單一物件；轉場用於投影片之間的切換。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-440', 'chart', 'Excel 中 =IF(A1>60,"及格","不及格")，若 A1=70 則結果為？', '[{"key":"A","text":"不及格"},{"key":"B","text":"及格"},{"key":"C","text":"70"},{"key":"D","text":"錯誤"}]', 'B', '70>60 為真，故傳回「及格」。', '["430"]');
