INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-chart-442', 'chart', 'Excel 中 =COUNTIF(A1:A10,">50") 會計算？', '[{"key":"A","text":"總和"},{"key":"B","text":"大於 50 的儲存格個數"},{"key":"C","text":"平均"},{"key":"D","text":"最大值"}]', 'B', 'COUNTIF 依條件計算符合的儲存格個數。', '["430"]');
