INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-121', 'logic', '所有哺乳類動物都是胎生的，所有牛都是哺乳類動物。那麼：', '[{"key":"A","text":"所有哺乳類動物都是牛"},{"key":"B","text":"所有牛都是胎生的"},{"key":"C","text":"所有四肢哺乳類都是胎生的"},{"key":"D","text":"以上皆非"}]', 'B', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-122', 'logic', '所有哺乳類動物都是不下蛋的，沒有母雞不會下蛋。那麼：', '[{"key":"A","text":"所有母雞是哺乳類動物"},{"key":"B","text":"有些母雞是哺乳類動物"},{"key":"C","text":"所有母雞都不是哺乳類動物"},{"key":"D","text":"以上皆非"}]', 'C', '哺乳類都不下蛋，母雞都下蛋 ⇒ 母雞不屬於哺乳類。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-123', 'logic', '凡是北極的生物都是白色的。所有白色的動物都不是胎生的。由此可以推論出？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-124', 'logic', '已知所有牛油都是新鮮的，新鮮的都不昂貴。以下哪一項正確？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆錯"}]', 'A', '牛油→新鮮→不昂貴。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-125', 'logic', '已知「所有哺乳類都不下蛋」且「所有母雞都會下蛋」。由此可推論？', '[{"key":"A","text":"所有母雞都不是哺乳類"},{"key":"B","text":"有些母雞是哺乳類"},{"key":"C","text":"所有哺乳類都是母雞"},{"key":"D","text":"以上皆非"}]', 'A', '哺乳類不下蛋、母雞下蛋 ⇒ 母雞不屬於哺乳類。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-126', 'logic', '已知「凡是北極的生物都是白色的」且「所有白色的動物都不是胎生的」。由此可推論？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-127', 'logic', '已知「所有牛油都是新鮮的」且「新鮮的都不昂貴」。由此可推論？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆非"}]', 'A', '牛油→新鮮→不昂貴。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-128', 'logic', '已知「所有優秀的學生都不上課」且「不努力的學生都去上課」。由此可推論？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的都是優秀的學生"},{"key":"C","text":"不努力的學生是優秀的"},{"key":"D","text":"以上皆非"}]', 'A', '上課⇒不優秀（逆否：優秀⇒不上課）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-129', 'logic', '已知「所有 律師 都是 專業人士」且「所有 專業人士 都是 受過高等教育」。由此可推論？', '[{"key":"A","text":"所有 律師 都是 受過高等教育"},{"key":"B","text":"有些 律師 是 受過高等教育"},{"key":"C","text":"沒有 律師 是 受過高等教育"},{"key":"D","text":"以上皆非"}]', 'A', 'A⊂B⊂C ⇒ 所有 A 都是 C。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-130', 'logic', '已知「所有 金屬 都是 導電體」且「沒有 導電體 是 可導電」。由此可推論？', '[{"key":"A","text":"所有 金屬 都是 可導電"},{"key":"B","text":"沒有 金屬 是 可導電"},{"key":"C","text":"有些 金屬 是 可導電"},{"key":"D","text":"以上皆非"}]', 'B', 'A⊂B 且 B∩C=∅ ⇒ 沒有 A 是 C。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-131', 'logic', '已知「沒有 鳥 是 有翼」且「所有 會飛 都是 有翼」。由此可推論？', '[{"key":"A","text":"沒有 鳥 是 會飛"},{"key":"B","text":"所有 鳥 都是 會飛"},{"key":"C","text":"有些 會飛 是 鳥"},{"key":"D","text":"以上皆非"}]', 'A', 'A∩B=∅ 且 C⊂B ⇒ A∩C=∅。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-132', 'logic', '已知「所有哺乳類都是胎生的」且「所有牛都是哺乳類」。由此可推論？', '[{"key":"A","text":"所有牛都是胎生的"},{"key":"B","text":"所有哺乳類都是牛"},{"key":"C","text":"有些牛不是胎生的"},{"key":"D","text":"以上皆非"}]', 'A', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-133', 'logic', '已知「所有哺乳類都不下蛋」且「所有母雞都會下蛋」。由此可推論？', '[{"key":"A","text":"所有母雞都不是哺乳類"},{"key":"B","text":"有些母雞是哺乳類"},{"key":"C","text":"所有哺乳類都是母雞"},{"key":"D","text":"以上皆非"}]', 'A', '哺乳類不下蛋、母雞下蛋 ⇒ 母雞不屬於哺乳類。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-134', 'logic', '已知「凡是北極的生物都是白色的」且「所有白色的動物都不是胎生的」。由此可推論？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-135', 'logic', '已知「所有牛油都是新鮮的」且「新鮮的都不昂貴」。由此可推論？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆非"}]', 'A', '牛油→新鮮→不昂貴。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-136', 'logic', '已知「所有優秀的學生都不上課」且「不努力的學生都去上課」。由此可推論？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的都是優秀的學生"},{"key":"C","text":"不努力的學生是優秀的"},{"key":"D","text":"以上皆非"}]', 'A', '上課⇒不優秀（逆否：優秀⇒不上課）。', '["430"]');
