INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-215', 'logic', '已知「所有牛油都是新鮮的」且「新鮮的都不昂貴」。由此可推論？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆非"}]', 'A', '牛油→新鮮→不昂貴。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-216', 'logic', '已知「所有優秀的學生都不上課」且「不努力的學生都去上課」。由此可推論？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的都是優秀的學生"},{"key":"C","text":"不努力的學生是優秀的"},{"key":"D","text":"以上皆非"}]', 'A', '上課⇒不優秀（逆否：優秀⇒不上課）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-217', 'logic', '已知「所有 A 都是 B」且「所有 B 都是 C」。由此可推論？', '[{"key":"A","text":"所有 A 都是 C"},{"key":"B","text":"有些 A 是 C"},{"key":"C","text":"沒有 A 是 C"},{"key":"D","text":"以上皆非"}]', 'A', 'A⊂B⊂C ⇒ 所有 A 都是 C。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-218', 'logic', '已知「所有 貓 都是 動物」且「沒有 動物 是 生物」。由此可推論？', '[{"key":"A","text":"所有 貓 都是 生物"},{"key":"B","text":"沒有 貓 是 生物"},{"key":"C","text":"有些 貓 是 生物"},{"key":"D","text":"以上皆非"}]', 'B', 'A⊂B 且 B∩C=∅ ⇒ 沒有 A 是 C。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-219', 'logic', '已知「沒有 律師 是 專業人士」且「所有 受過高等教育 都是 專業人士」。由此可推論？', '[{"key":"A","text":"沒有 律師 是 受過高等教育"},{"key":"B","text":"所有 律師 都是 受過高等教育"},{"key":"C","text":"有些 受過高等教育 是 律師"},{"key":"D","text":"以上皆非"}]', 'A', 'A∩B=∅ 且 C⊂B ⇒ A∩C=∅。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-220', 'logic', '已知「所有哺乳類都是胎生的」且「所有牛都是哺乳類」。由此可推論？', '[{"key":"A","text":"所有牛都是胎生的"},{"key":"B","text":"所有哺乳類都是牛"},{"key":"C","text":"有些牛不是胎生的"},{"key":"D","text":"以上皆非"}]', 'A', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-221', 'logic', '己是戊的母親，乙的女兒是己，丁的妹妹是戊，丁不是甲的兒子。問戊是乙的誰？', '[{"key":"A","text":"外孫女"},{"key":"B","text":"姐妹"},{"key":"C","text":"外祖母"},{"key":"D","text":"以上皆非"}]', 'A', '乙的女兒是己，己是戊的母親 ⇒ 戊是乙的外孫女。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-222', 'logic', '張先生說：「她的母親是我父親的獨生子的妻子。」張先生是某人的？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"無法判斷"}]', 'A', '我父親的獨生子即張先生自己，他的妻子即張太太；她的母親是張太太，則某人為張先生與張太太的兒子。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-223', 'logic', '甲是乙的母親，乙是丙的哥哥，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"丈夫"},{"key":"C","text":"妻子"},{"key":"D","text":"無法確定"}]', 'B', '乙是丙的哥哥⇒乙、丙同輩；丙是丁的兒子⇒丁是丙的父親；甲是乙的母親⇒丁是甲的丈夫。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-224', 'logic', '李先生的媳婦介紹某人：「她的父親是李先生的獨生子。」那個人是李先生媳婦的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"女兒"},{"key":"C","text":"姊妹"},{"key":"D","text":"無法確定"}]', 'B', '李先生的獨生子是「她」的父親⇒「她」是李先生媳婦的女兒。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-225', 'logic', '一男子指著甲向他人介紹：「他的兄弟的爸爸是我女兒的父親。」問我是甲的？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"祖父"},{"key":"D","text":"叔伯"}]', 'B', '我女兒的父親=我；他的兄弟的爸爸=甲的父親⇒甲的父親=我，故我是甲的父親。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-226', 'logic', '一名男士說：「我是甲的爸爸的獨生子的兒子。」請問這位男士是甲的什麼身份？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"叔父"},{"key":"D","text":"兄弟"}]', 'A', '甲的爸爸的獨生子=甲；其兒子=男士⇒男士是甲的兒子。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-227', 'logic', '一位女士指著甲說：「她的母親是我母親的獨生女。」問甲是女士的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"妹妹"},{"key":"C","text":"女兒"},{"key":"D","text":"姨媽"}]', 'C', '我母親的獨生女=女士本人；她的母親是女士⇒甲是女士的女兒。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-228', 'logic', '甲是乙的父親，乙是丙的母親，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"曾孫"},{"key":"B","text":"孫子"},{"key":"C","text":"兒子"},{"key":"D","text":"兄弟"}]', 'A', '乙是丙的母親⇒丙是乙的子女；丙是丁的兒子⇒丁是丙的子女⇒丁是甲的曾孫。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-229', 'logic', '王先生的父親是李女士的獨生子。問李女士是王先生的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"祖母"},{"key":"C","text":"外祖母"},{"key":"D","text":"姑母"}]', 'B', '李女士的獨生子=王先生的父親⇒李女士是王先生的祖母。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-230', 'logic', '「他是我妹妹的祖母的獨生子的妻子的兒子。」問「他」是該男子的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"表兄弟"}]', 'C', '妹妹的祖母的獨生子=妹妹的父親=該男子；其妻子的兒子=該男子與妻之子⇒「他」與該男子之子為兄弟，依題意多解為兄弟。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-231', 'logic', '己是戊的母親，乙的女兒是己，丁的妹妹是戊，丁不是甲的兒子。問戊是乙的誰？', '[{"key":"A","text":"外孫女"},{"key":"B","text":"姐妹"},{"key":"C","text":"外祖母"},{"key":"D","text":"以上皆非"}]', 'A', '乙的女兒是己，己是戊的母親 ⇒ 戊是乙的外孫女。', '["430"]');
