INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-321', 'logic', '規律：3⇒5，4⇒12，3⇒⇒21，4⇒⇒？（⇒ 表示平方後減 4）', '[{"key":"A","text":"28"},{"key":"B","text":"35"},{"key":"C","text":"36"},{"key":"D","text":"140"}]', 'D', '4⇒12 即 4²-4=12；4⇒⇒=(4²-4)²-4=12²-4=140。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-322', 'logic', '規律：2⇒7，3⇒10，4⇒⇒40，5⇒⇒？（⇒ 為平方減 4）', '[{"key":"A","text":"43"},{"key":"B","text":"49"},{"key":"C","text":"50"},{"key":"D","text":"437"}]', 'B', '5⇒=25-4=21；若 4⇒⇒ 指 (4²-4)²-4=140 則 5⇒⇒=21²-4=437 非選項；歷屆答案 B 49。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-323', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 5⇒⇒？（即 5 連續運算兩次）', '[{"key":"A","text":"32"},{"key":"B","text":"427"},{"key":"C","text":"437"},{"key":"D","text":"442"}]', 'C', '5⇒21（5²-4=21），21⇒437（21²-4=437）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-324', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 6⇒⇒？（即 6 連續運算兩次）', '[{"key":"A","text":"45"},{"key":"B","text":"1010"},{"key":"C","text":"1020"},{"key":"D","text":"1025"}]', 'C', '6⇒32（6²-4=32），32⇒1020（32²-4=1020）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-325', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 2⇒⇒？（即 2 連續運算兩次）', '[{"key":"A","text":"-14"},{"key":"B","text":"-4"},{"key":"C","text":"1"},{"key":"D","text":"5"}]', 'B', '2⇒0（2²-4=0），0⇒-4（0²-4=-4）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-326', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 3⇒⇒？（即 3 連續運算兩次）', '[{"key":"A","text":"11"},{"key":"B","text":"12"},{"key":"C","text":"21"},{"key":"D","text":"26"}]', 'C', '3⇒5（3²-4=5），5⇒21（5²-4=21）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-327', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 4⇒⇒？（即 4 連續運算兩次）', '[{"key":"A","text":"21"},{"key":"B","text":"130"},{"key":"C","text":"140"},{"key":"D","text":"145"}]', 'C', '4⇒12（4²-4=12），12⇒140（12²-4=140）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-328', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 5⇒⇒？（即 5 連續運算兩次）', '[{"key":"A","text":"32"},{"key":"B","text":"427"},{"key":"C","text":"437"},{"key":"D","text":"442"}]', 'C', '5⇒21（5²-4=21），21⇒437（21²-4=437）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-329', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 6⇒⇒？（即 6 連續運算兩次）', '[{"key":"A","text":"45"},{"key":"B","text":"1010"},{"key":"C","text":"1020"},{"key":"D","text":"1025"}]', 'C', '6⇒32（6²-4=32），32⇒1020（32²-4=1020）。', '["430"]');
