INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-378', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 5⇒⇒？（即 5 連續運算兩次）', '[{"key":"A","text":"32"},{"key":"B","text":"427"},{"key":"C","text":"437"},{"key":"D","text":"442"}]', 'C', '5⇒21（5²-4=21），21⇒437（21²-4=437）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-379', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 6⇒⇒？（即 6 連續運算兩次）', '[{"key":"A","text":"45"},{"key":"B","text":"1010"},{"key":"C","text":"1020"},{"key":"D","text":"1025"}]', 'C', '6⇒32（6²-4=32），32⇒1020（32²-4=1020）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-380', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 2⇒⇒？（即 2 連續運算兩次）', '[{"key":"A","text":"-14"},{"key":"B","text":"-4"},{"key":"C","text":"1"},{"key":"D","text":"5"}]', 'B', '2⇒0（2²-4=0），0⇒-4（0²-4=-4）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-381', 'logic', '戊第一個衝線，甲不是緊隨戊的，己緊跟丙後面，丁與丙差不多同步，乙跑尾二。問誰跑最尾？', '[{"key":"A","text":"甲"},{"key":"B","text":"己"},{"key":"C","text":"丙"},{"key":"D","text":"無法估計"}]', 'A', '順序可推為：戊、丁、丙、己、乙、甲；甲最尾。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-382', 'logic', '甲、乙、丙、丁排隊。已知：甲在乙前，丙在丁前，乙不是最後。問排第一的是誰？', '[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"丁"}]', 'A', '依條件可推順序為：甲、乙、丙、丁，故第一為 甲。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-383', 'logic', '甲、乙、丙、丁、戊排隊。已知：戊第一，甲不是第二，乙在丙前，丁最後。問排第一的是誰？', '[{"key":"A","text":"戊"},{"key":"B","text":"甲"},{"key":"C","text":"乙"},{"key":"D","text":"丙"}]', 'A', '依條件可推順序為：戊、甲、乙、丙、丁，故第一為 戊。', '["430"]');
