INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-461', 'logic', '「理論：實驗：現象」的類比，與下列哪組關係相同？', '[{"key":"A","text":"習慣：使用：工具"},{"key":"B","text":"診斷：治療：癥狀"},{"key":"C","text":"學習：測驗：成績"},{"key":"D","text":"努力：成功：困難"}]', 'C', '理論透過實驗得出現象；學習透過測驗得出成績。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-462', 'logic', '「總結、引言」的關係，就如「附錄」跟下列哪項的關係？', '[{"key":"A","text":"章節"},{"key":"B","text":"序"},{"key":"C","text":"索引"},{"key":"D","text":"文章"}]', 'B', '總結與引言在文首文尾；附錄與序亦然。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-463', 'logic', '「方向」對「？」、「？」對「秤」。與「方向」同一類的是？', '[{"key":"A","text":"南；公斤"},{"key":"B","text":"指南針；重量"},{"key":"C","text":"方位；陀"},{"key":"D","text":"東；天平"}]', 'B', '方向用指南針測量，重量用秤測量。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-464', 'logic', '若以下假設成立，可以證明「人力成本是最大支出」：公司支出最大部分係員工薪俸。', '[{"key":"A","text":"在經濟不景氣時，各大上市公司都減人資支出及福利"},{"key":"B","text":"在經濟繁榮時，各大上市公司都增人資支出"},{"key":"C","text":"以上皆是"},{"key":"D","text":"以上皆非"}]', 'A', '不景氣時減人資支出，反映人資佔比大。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-465', 'logic', '「遲暮」對「襁褓」，那麼「除夕」對？', '[{"key":"A","text":"新年"},{"key":"B","text":"冬至"},{"key":"C","text":"端午"},{"key":"D","text":"中秋"}]', 'A', '遲暮對襁褓為老人對嬰兒；除夕對新年為年尾對年頭。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-466', 'logic', '「氧：銅綠：銅」的關係（銅被氧氧化成銅綠），與下列相同的是？', '[{"key":"A","text":"氣體：固體：固體"},{"key":"B","text":"空氣：鐵鏽：釘子"},{"key":"C","text":"二氧化碳：環保：地球"},{"key":"D","text":"水：淘金：金子"}]', 'B', '釘子被空氣氧化成鐵鏽。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-467', 'logic', '「石油：生物沉積」的關係，與「____：骨頭」相同。空格應為？', '[{"key":"A","text":"關節"},{"key":"B","text":"礦物質"},{"key":"C","text":"化石"},{"key":"D","text":"牙齒"}]', 'C', '石油由生物沉積形成；化石由骨頭等形成。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-468', 'logic', '日蝕的時候貓一定會叫；貓不會叫的時候月亮會有發光。下列哪一個對？', '[{"key":"A","text":"日蝕的時候月亮會發光"},{"key":"B","text":"日蝕的時候月亮不會發光"},{"key":"C","text":"日蝕的時候有時月亮會發光"},{"key":"D","text":"以上皆錯"}]', 'D', '日蝕⇒貓叫；貓不叫⇒月發光。日蝕時貓叫，無法推月發光與否。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-logic-469', 'logic', '「公務員須依法辦事，不得徇私。」句中「徇私」之意最接近：', '[{"key":"A","text":"公正無私"},{"key":"B","text":"因私情而偏袒"},{"key":"C","text":"公開透明"},{"key":"D","text":"依法裁量"}]', 'B', '徇私指為私情而偏袒、不公正。', '["430"]');
