INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-221', 'reading', '《人到無求品自高》。小明品格高尚。下列哪句正確？', '[{"key":"A","text":"小明已達到無求的境界，所以品格自然高尚"},{"key":"B","text":"小明無所求"},{"key":"C","text":"無法判斷"},{"key":"D","text":"小明遵從「人到無求品自高」"}]', 'C', '品格高尚可能由其他原因造成，無法推得小明一定「無求」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-222', 'reading', '文章結論：「現在的樓價就是合理的樓價。」論點包括：現價交易仍高、填海延期、新移民等。下列哪個論點最支持該結論？', '[{"key":"A","text":"有人買就是合理價格"},{"key":"B","text":"阻止填海，土地供應不足所以貴"},{"key":"C","text":"新移民政策"},{"key":"D","text":"買了樓的人不會抗議樓價高"}]', 'A', '有人買即市場接受，支持「合理價格」。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-223', 'reading', '網絡欺凌文章：主旨為？', '[{"key":"A","text":"校園欺凌"},{"key":"B","text":"網絡欺凌"},{"key":"C","text":"青少年欺凌"},{"key":"D","text":"以上皆是"}]', 'B', '文章以網絡欺凌為主。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-224', 'reading', '網絡欺凌：欺凌者主要目的為？', '[{"key":"A","text":"失眠"},{"key":"B","text":"情緒病"},{"key":"C","text":"身體傷害"},{"key":"D","text":"以上皆不是"}]', 'D', '目的多為令受害人難堪、羞愧，非失眠等結果。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-225', 'reading', '公職人員寫文件時，職銜應該寫在？（發文者職銜位置）', '[{"key":"A","text":"上款"},{"key":"B","text":"正文"},{"key":"C","text":"下款"},{"key":"D","text":"祝頌詞"}]', 'C', '發文者職銜通常位於下款（簽署處）。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-226', 'reading', '「行政機關應依職權或依申請作出行為。」句中「依職權」意謂：', '[{"key":"A","text":"僅依申請"},{"key":"B","text":"無須申請即可主動為之"},{"key":"C","text":"依上級指示"},{"key":"D","text":"依法院判決"}]', 'B', '依職權指機關得主動為之。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-227', 'reading', '「除法律另有規定外，行政行為自通知日起生效。」「通知日」指：', '[{"key":"A","text":"發文日"},{"key":"B","text":"收受者知悉或可知悉之日"},{"key":"C","text":"公告日"},{"key":"D","text":"施行日"}]', 'B', '通知日為收受者知悉或可知悉之日。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-228', 'reading', '「當事人得就行政行為提出聲明異議。」「聲明異議」屬：', '[{"key":"A","text":"司法上訴"},{"key":"B","text":"向原機關提出之救濟"},{"key":"C","text":"僅供參考"},{"key":"D","text":"不具效力"}]', 'B', '聲明異議為向原機關提出之救濟。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-229', 'reading', '「送達」之方式可包括：', '[{"key":"A","text":"僅親收"},{"key":"B","text":"親收、掛號郵遞、公告等法律允許之方式"},{"key":"C","text":"僅公告"},{"key":"D","text":"僅電子方式"}]', 'B', '送達方式由法律規定。', '["430"]');
