INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-232', 'reading', '「一事不再理」原則指：', '[{"key":"A","text":"同一事件可重複處罰"},{"key":"B","text":"同一事件經終局決定後不得就同一事由再為審理"},{"key":"C","text":"僅適用民事"},{"key":"D","text":"僅適用刑事"}]', 'B', '同一事件經終局決定後不再審理。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-233', 'reading', '「比例原則」要求：', '[{"key":"A","text":"手段與目的無須關聯"},{"key":"B","text":"手段須與目的相當、不得過度"},{"key":"C","text":"僅適用於罰則"},{"key":"D","text":"僅適用於授益行為"}]', 'B', '手段須與目的相當、不得過度。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-234', 'reading', '「平等原則」要求：', '[{"key":"A","text":"相同情況得差別對待"},{"key":"B","text":"相同情況應相同對待"},{"key":"C","text":"一律相同對待無例外"},{"key":"D","text":"僅適用於立法"}]', 'B', '相同情況應相同對待。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-235', 'reading', '「誠實信用」原則在行政法上：', '[{"key":"A","text":"不適用"},{"key":"B","text":"當事人與機關均應遵守"},{"key":"C","text":"僅機關遵守"},{"key":"D","text":"僅當事人遵守"}]', 'B', '雙方均應遵守誠實信用。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-236', 'reading', '「公共利益」在行政法常指：', '[{"key":"A","text":"僅個人利益"},{"key":"B","text":"社會整體或國家之利益"},{"key":"C","text":"僅機關利益"},{"key":"D","text":"僅多數人利益"}]', 'B', '公共利益為社會整體或國家利益。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-237', 'reading', '「法律保留」指：', '[{"key":"A","text":"行政機關可任意創設處罰"},{"key":"B","text":"某些事項須由法律規定"},{"key":"C","text":"法律可授權行政機關任意為之"},{"key":"D","text":"無須法律依據"}]', 'B', '某些事項須由法律規定。', '["430"]');
