INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-239', 'reading', '「默示批准」指：', '[{"key":"A","text":"明示拒絕"},{"key":"B","text":"法定期限內未表態視為批准"},{"key":"C","text":"無須申請"},{"key":"D","text":"僅適用於許可"}]', 'B', '法定期限內未表態視為批准。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-240', 'reading', '「訴願」通常向誰提起？', '[{"key":"A","text":"原機關"},{"key":"B","text":"原機關之上級或法律規定之機關"},{"key":"C","text":"法院"},{"key":"D","text":"立法機關"}]', 'B', '訴願向原機關之上級或法定機關提起。', '["430"]');
