INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-244', 'reading', '「說明理由」之義務：', '[{"key":"A","text":"行政行為無須說明理由"},{"key":"B","text":"法律規定或影響權益之行為應說明理由"},{"key":"C","text":"僅書面行為"},{"key":"D","text":"僅處罰行為"}]', 'B', '法律規定或影響權益之行為應說明理由。', '["430"]');
