INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-491', 'reading', '「疏漏」意謂：', '[{"key":"A","text":"嚴密"},{"key":"B","text":"疏忽遺漏"},{"key":"C","text":"疏通"},{"key":"D","text":"漏網"}]', 'B', '疏漏指疏忽遺漏。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-492', 'reading', '「嚴謹」指：', '[{"key":"A","text":"鬆散"},{"key":"B","text":"嚴密謹慎"},{"key":"C","text":"嚴格"},{"key":"D","text":"僅謹慎"}]', 'B', '嚴謹指嚴密謹慎。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-493', 'reading', '「簡明」意為：', '[{"key":"A","text":"冗長"},{"key":"B","text":"簡潔明確"},{"key":"C","text":"簡單"},{"key":"D","text":"明白"}]', 'B', '簡明指簡潔明確。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-494', 'reading', '「冗長」意謂：', '[{"key":"A","text":"簡短"},{"key":"B","text":"多餘而過長"},{"key":"C","text":"長篇"},{"key":"D","text":"冗餘"}]', 'B', '冗長指多餘而過長。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-495', 'reading', '「扼要」指：', '[{"key":"A","text":"詳盡"},{"key":"B","text":"抓住要點"},{"key":"C","text":"扼殺"},{"key":"D","text":"要點"}]', 'B', '扼要指抓住要點。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-496', 'reading', '「贅述」意為：', '[{"key":"A","text":"簡述"},{"key":"B","text":"多餘的敘述"},{"key":"C","text":"陳述"},{"key":"D","text":"敘述"}]', 'B', '贅述指多餘的敘述。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-497', 'reading', '「言簡意賅」意謂：', '[{"key":"A","text":"冗長"},{"key":"B","text":"言語簡短而意思完備"},{"key":"C","text":"簡略"},{"key":"D","text":"意賅言繁"}]', 'B', '言簡意賅指言語簡短意思完備。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-498', 'reading', '「開門見山」指：', '[{"key":"A","text":"迂迴"},{"key":"B","text":"直入主題"},{"key":"C","text":"開門"},{"key":"D","text":"見山"}]', 'B', '開門見山指直入主題。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-499', 'reading', '「離題」意為：', '[{"key":"A","text":"切題"},{"key":"B","text":"偏離主題"},{"key":"C","text":"離開"},{"key":"D","text":"題目"}]', 'B', '離題指偏離主題。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('430-reading-500', 'reading', '「切題」意謂：', '[{"key":"A","text":"離題"},{"key":"B","text":"緊扣主題"},{"key":"C","text":"切開"},{"key":"D","text":"題目"}]', 'B', '切題指緊扣主題。', '["430"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-law-1', 'law', '澳門特別行政區的官方語文為？', '[{"key":"A","text":"僅中文"},{"key":"B","text":"僅葡文"},{"key":"C","text":"中文和葡文"},{"key":"D","text":"中文、葡文和英文"}]', 'C', '根據《基本法》第九條，澳門特別行政區的行政機關、立法機關和司法機關除使用中文外，還可使用葡文，葡文也是正式語文。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-math-1', 'math', '一份文件共 24 頁，每頁平均 350 字。全文約多少字？', '[{"key":"A","text":"7200"},{"key":"B","text":"8400"},{"key":"C","text":"9600"},{"key":"D","text":"10800"}]', 'B', '24 × 350 = 8400 字。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-1', 'logic', '若「所有 A 都是 B」且「有些 B 是 C」，則可確定：', '[{"key":"A","text":"所有 A 都是 C"},{"key":"B","text":"有些 A 可能是 C"},{"key":"C","text":"所有 B 都是 A"},{"key":"D","text":"有些 C 不是 B"}]', 'B', '由「所有 A 都是 B」與「有些 B 是 C」，只能推得「有些 A 可能是 C」，無法推出「所有 A 都是 C」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-reading-1', 'reading', '「本局收到申請後，將於法定期限內作出決定。」「法定期限」意指：', '[{"key":"A","text":"申請人自訂的期限"},{"key":"B","text":"法律規定的期限"},{"key":"C","text":"行政長官指定的期限"},{"key":"D","text":"無固定期限"}]', 'B', '「法定期限」指法律所規定的期限。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-1', 'chart', '某表格欄位依序為：日期、部門、數量、備註。若要依「數量」由高至低排序，應以哪一欄為準？', '[{"key":"A","text":"日期"},{"key":"B","text":"部門"},{"key":"C","text":"數量"},{"key":"D","text":"備註"}]', 'C', '由高至低排序應以「數量」欄為排序鍵。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-law-1', 'law', '下列哪個機關有權決定特別行政區的設立？', '[{"key":"A","text":"全國人民代表大會"},{"key":"B","text":"國務院"},{"key":"C","text":"中華人民共和國主席"},{"key":"D","text":"中國人民政治協商會議"}]', 'A', '《憲法》規定特別行政區的設立由全國人民代表大會決定。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-law-2', 'law', '根據現行《行政程序法典》，行政機關有權限在尊重居民之權利及受法律保護之利益下，謀求：', '[{"key":"A","text":"行政利益"},{"key":"B","text":"公共利益"},{"key":"C","text":"私人利益"},{"key":"D","text":"社團利益"}]', 'B', '《行政程序法典》規定行政機關謀求公共利益。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-law-3', 'law', '根據《中華人民共和國澳門特別行政區基本法》，澳門特別行政區應自行立法禁止：', '[{"key":"A","text":"愛國行為"},{"key":"B","text":"團結國家行為"},{"key":"C","text":"叛國行為"},{"key":"D","text":"支持中央人民政府行為"}]', 'C', '《基本法》第二十三條規定澳門特別行政區應自行立法禁止叛國等行為。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-law-4', 'law', '澳門特別行政區的《政府組織綱要法》，由澳門特別行政區：', '[{"key":"A","text":"行政長官制定"},{"key":"B","text":"立法會制定"},{"key":"C","text":"法院制定"},{"key":"D","text":"以上皆不是"}]', 'B', '法律由立法會制定。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-law-5', 'law', '下列關於國旗、國歌、國徽和首都的表述錯誤的是？', '[{"key":"A","text":"中華人民共和國的國旗是五星紅旗"},{"key":"B","text":"中華人民共和國的國歌是《愛我中華》"},{"key":"C","text":"中華人民共和國的國徽中間是五星照耀下的天安門，周圍是谷穗和齒輪"},{"key":"D","text":"中華人民共和國的首都是北京"}]', 'B', '國歌應為《義勇軍進行曲》，不是《愛我中華》。題目問「錯誤」，故選 B。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-1', 'math', '陳華 X 歲，她的年齡比陳麗的 5 倍少 2 歲。問陳麗幾歲？', '[{"key":"A","text":"5(X+2)"},{"key":"B","text":"5(X-2)"},{"key":"C","text":"(X+2)/5"},{"key":"D","text":"(X-2)/5"}]', 'C', '陳華 = 5×陳麗 − 2 ⇒ X = 5×陳麗 − 2 ⇒ 陳麗 = (X+2)/5。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-2', 'math', '三位數和兩位數之最大差為？', '[{"key":"A","text":"900"},{"key":"B","text":"989"},{"key":"C","text":"990"},{"key":"D","text":"999"}]', 'B', '最大三位數 999 − 最小兩位數 10 = 989。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-3', 'math', '比較：I. 14/17 與 14+1/17+1  II. 14/17 與 14−1/17−1  III. 14/17 與 14−1/17+1。哪項正確？', '[{"key":"A","text":"僅 I"},{"key":"B","text":"I, II"},{"key":"C","text":"I, II, III"},{"key":"D","text":"II, III"}]', 'D', '14/17≈0.823，15/18≈0.833，故 I 錯（14/17 < 15/18）。歷屆思路：只計了 I 錯，選項中僅 D 不含 I，故選 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-logic-1', 'logic', '凡是北極的生物都是白色的。所有白色的動物都不是胎生。由此可以推論出？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生，故北極生物都不是胎生。歷屆有選 D 的爭議（生物與動物用詞），多數思路選 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-4', 'math', '運動前血壓 70–80，運動後血壓 160–180。血壓浮動範圍為？', '[{"key":"A","text":"(70, 110)"},{"key":"B","text":"(80, 110)"},{"key":"C","text":"(80, 100)"},{"key":"D","text":"(70, 100)"}]', 'B', '下限差 160−80=80，上限差 180−70=110，故 (80, 110)。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-5', 'math', '三月十八號是星期五，問三月二十八號到五月五號有幾個星期二？', '[{"key":"A","text":"5"},{"key":"B","text":"6"},{"key":"C","text":"7"},{"key":"D","text":"8"}]', 'B', '歷屆答案：6 個。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-6', 'math', '邊長 60 cm 正方體表面噴油漆後，切割為若干個邊長為 x 的小正方體，其中有 8 個小正方體沒有油漆。求 x。', '[{"key":"A","text":"10"},{"key":"B","text":"12"},{"key":"C","text":"15"},{"key":"D","text":"20"}]', 'C', '8 個無漆為中心 2×2×2；每邊 60/4=15 格，故 x=15。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-logic-2', 'logic', '一個男士向別人介紹甲說：「他是我妹妹的祖母的獨生子的妻子的兒子。」問甲是那個男人的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"表兄弟"}]', 'C', '妹妹的祖母的獨生子 = 妹妹的父親（即該男士自己）；其妻子 = 該男士之妻；其兒子 = 該男士與妻之子，即甲的兄弟；故甲與該男士之子為兄弟 ⇒ 甲是該男士的兒子。若「他」指甲，則甲 = 我妹妹的祖母的獨生子的妻子的兒子 = 我妹妹的兄弟 = 我（若獨生子指該男士）… 歷屆多選「兄弟」，依歷屆答案 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-logic-3', 'logic', '一位女士指著甲說：「她的母親是我母親的獨生女。」問甲是女士的誰？（題目為：甲是女士的什麼親戚關係）', '[{"key":"A","text":"母親"},{"key":"B","text":"妹妹"},{"key":"C","text":"女兒"},{"key":"D","text":"姨媽"}]', 'C', '我母親的獨生女 = 我（女士本人）。她的母親是我 ⇒ 甲的母亲是女士 ⇒ 女士是甲的母親 ⇒ 甲是女士的女兒。歷屆有母親/女兒/姨媽爭議，多票選女兒。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-7', 'math', '5×5 方格圖中，共有多少個正方形？（由 1×1 到 5×5 各尺寸）', '[{"key":"A","text":"25"},{"key":"B","text":"45"},{"key":"C","text":"55"},{"key":"D","text":"60"}]', 'C', '1²+2²+3²+4²+5² = 1+4+9+16+25 = 55。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-chart-1', 'chart', 'Excel：IF(AND(C2>=12,E2>=8),"是","否") 與 IF(AND(C2>=?,E2>=11),"是","否")，G6 最後會出現幾個「是」？', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"5"}]', 'C', '歷屆：第一個 IF 符合 2 個，第二個 IF 符合 2 個，共 4 個「是」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-chart-2', 'chart', 'Excel：B2 為出生日期，求「年齡」儲存格的公式應為？', '[{"key":"A","text":"=YEAR(TODAY())-YEAR(B2)"},{"key":"B","text":"=TODAY()-B2"},{"key":"C","text":"=YEAR(B2)"},{"key":"D","text":"=B2-TODAY()"}]', 'A', '年齡 = 今年 − 出生年，故 =YEAR(TODAY())-YEAR(B2)。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-chart-3', 'chart', '在 Microsoft PowerPoint 2016 中，以下哪個選項不屬於「插入」項？', '[{"key":"A","text":"表格"},{"key":"B","text":"圖案"},{"key":"C","text":"方程式"},{"key":"D","text":"快速組件"}]', 'D', '歷屆題目為「不屬於插入項」；快速組件可能歸於其他功能區，故選 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-8', 'math', '公司男女比例為 3:4，總人數可能為？', '[{"key":"A","text":"36"},{"key":"B","text":"48"},{"key":"C","text":"84"},{"key":"D","text":"100"}]', 'C', '3:4 即 7 的倍數，84 = 12×7，且 36+48=84，男 36 女 48 符合 3:4。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-reading-1', 'reading', '公職人員寫文件時，職銜應該寫在？（發放人職銜位置）', '[{"key":"A","text":"上款"},{"key":"B","text":"正文"},{"key":"C","text":"下款"},{"key":"D","text":"祝頌詞"}]', 'C', '發文者職銜通常位於下款（簽署處）。歷屆多選 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-reading-2', 'reading', '文章結論：「現在的樓價就是合理的樓價。」論點包括：現價交易仍高於市場 30%、填海計劃延期、新移民等。下列哪個論點最支持該結論？', '[{"key":"A","text":"有人買就是合理價格"},{"key":"B","text":"阻止填海，土地供應不足，所以貴"},{"key":"C","text":"新移民政策"},{"key":"D","text":"買了樓宇的人不會抗議樓價高"}]', 'A', '歷屆思路：有人買即市場接受，支持「合理價格」；移民、土地屬因果，未必直接支持「合理」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-reading-3', 'reading', '網絡欺凌文章：主旨為？', '[{"key":"A","text":"校園欺凌"},{"key":"B","text":"網絡欺凌"},{"key":"C","text":"青少年欺凌"},{"key":"D","text":"以上皆是"}]', 'B', '歷屆：文章以網絡欺凌為主，選 B。有討論選 D，主旨題通常擇一。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-reading-4', 'reading', '網絡欺凌：欺凌者主要目的為？', '[{"key":"A","text":"失眠"},{"key":"B","text":"情緒病"},{"key":"C","text":"身體傷害"},{"key":"D","text":"以上皆不是"}]', 'D', '歷屆：目的為令受害人難堪、羞愧，非失眠或情緒病等結果，故選 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2023-math-9', 'math', '2018 年物理科：合格線 50 分，只有 1 人不合格。已知最低 10、最高 75、平均 50、人數 40。成績排第二高者最多幾分？', '[{"key":"A","text":"51"},{"key":"B","text":"65"},{"key":"C","text":"74"},{"key":"D","text":"75"}]', 'B', '總分 50×40=2000。扣最高、最低：2000−75−10=1915；其餘 38 人若皆 50 則 1900，故第二高至少 1915−1900=15… 若僅 1 人不及格，為令平均 50，設第二高為 x，(75+10+x)/3≈50 時 x≈65；或 2000−75−10−50×37=1915−1850=65。歷屆答案 B。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-1', 'law', '澳門各級法院法官由誰任命？', '[{"key":"A","text":"終審法院院長"},{"key":"B","text":"行政長官"},{"key":"C","text":"檢察長"},{"key":"D","text":"立法會主席"}]', 'B', '《基本法》規定澳門特別行政區各級法院法官由行政長官任命。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-2', 'law', '政府開考向學校借場地，用哪種文件？', '[{"key":"A","text":"傳閱式公函"},{"key":"B","text":"通告"},{"key":"C","text":"建議書"},{"key":"D","text":"以上皆非"}]', 'D', '傳閱式公函用於部門內部；對外借場應用公函等，歷屆選 D（以上皆非）。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-3', 'law', '根據《基本法》，任命澳門特別行政區各級法院法官的是：', '[{"key":"A","text":"終審法院院長"},{"key":"B","text":"檢察長"},{"key":"C","text":"立法會主席"},{"key":"D","text":"行政長官"}]', 'D', '《中華人民共和國澳門特別行政區基本法》規定由行政長官任命法官。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-4', 'law', '以下哪項是現行《公共部門勞動合同制度》規定的行政任用合同失效的情況？', '[{"key":"A","text":"當工作人員達到擔任公職的最高年齡限制"},{"key":"B","text":"當工作人員處於長期絕對無擔任職務的能力"},{"key":"C","text":"屬調職時自新合同開始擔任職務之日起"},{"key":"D","text":"以上皆是"}]', 'D', '上述皆屬合同失效規定。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-5', 'law', '根據現行《公共行政工作人員的工作表現評核一般制度》，工作表現評核程序屬：', '[{"key":"A","text":"公開"},{"key":"B","text":"部分公開"},{"key":"C","text":"部分保密"},{"key":"D","text":"保密"}]', 'D', '工作表現評核程序屬保密。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-6', 'law', '根據現行《澳門公共行政工作人員通則》，對於經證明無專業能力的公務員或服務人員可科處以下哪項紀律處分？', '[{"key":"A","text":"書面申誡"},{"key":"B","text":"罰款"},{"key":"C","text":"停職"},{"key":"D","text":"強迫退休或撤職"}]', 'D', '無專業能力可科處較重處分如強迫退休或撤職。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-law-7', 'law', '根據現行《澳門公共行政工作人員通則》，公務員或服務人員在執行職務時有勤謹之義務，係指：', '[{"key":"A","text":"正常及持續地在部門工作"},{"key":"B","text":"正常及間歇地在部門工作"},{"key":"C","text":"隨意地到部門上班"},{"key":"D","text":"以上皆不是"}]', 'A', '勤謹義務指正常及持續地在部門工作。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-1', 'math', 'A 與 B 每週隨機上班 2 天（週一至週五）。A 與 B 每週最少一日相遇的機率為多少？', '[{"key":"A","text":"0.3"},{"key":"B","text":"0.4"},{"key":"C","text":"0.7"},{"key":"D","text":"0.8"}]', 'C', 'P(至少一日相遇)=1−P(完全錯開)。A 選 2 日 C(5,2)=10 種，B 完全不遇僅能從 A 未選的 3 日選 2 日 C(3,2)=3 種，故 P(錯開)=3/10=0.3，P(相遇)=0.7。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-2', 'math', '正方體邊長增加 10%，正方體體積增加多少？', '[{"key":"A","text":"10%"},{"key":"B","text":"21%"},{"key":"C","text":"30%"},{"key":"D","text":"33%"}]', 'D', '體積比 = (1.1)³ = 1.331，增加約 33.1%。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-3', 'math', '以下哪一個數結果最大？A. 77×7  B. 777×0.7  C. 7777×0.07', '[{"key":"A","text":"77×7"},{"key":"B","text":"777×0.7"},{"key":"C","text":"7777×0.07"},{"key":"D","text":"一樣"}]', 'C', '77×7=539；777×0.7=543.9；7777×0.07=544.39，故 C 最大。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-4', 'math', '5 條是非題，小明完全不會做，求至少答對一題的機率？', '[{"key":"A","text":"15/16"},{"key":"B","text":"1"},{"key":"C","text":"31/32"},{"key":"D","text":"1/2"}]', 'C', '1 − (1/2)^5 = 1 − 1/32 = 31/32。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-5', 'math', '5 人中 3 男 2 女，從中抽 2 次每次 1 人（不放回），2 人性別相同的機率？', '[{"key":"A","text":"2/5"},{"key":"B","text":"1/3"},{"key":"C","text":"2/3"},{"key":"D","text":"3/5"}]', 'A', 'P(兩男)+P(兩女)= (3/5)(2/4)+(2/5)(1/4)=6/20+2/20=8/20=2/5。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-6', 'math', '扭蛋機有 3 種動物：A  ​10 個、B 50 個、C 100 個。運氣最差需扭多少次才可集齊三種？', '[{"key":"A","text":"3"},{"key":"B","text":"61"},{"key":"C","text":"111"},{"key":"D","text":"151"}]', 'D', '最壞先扭光兩種：100+50=150，再 1 次得第三種，共 151。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-7', 'math', '已知 6 > (3−X) > −1，求 X 範圍？', '[{"key":"A","text":"x>3"},{"key":"B","text":"3<x<4"},{"key":"C","text":"x>4"},{"key":"D","text":"-3<x<4"}]', 'D', '6>3−X>−1 ⇒ 3>−X>−4 ⇒ −3<x<4。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-8', 'math', '火車由甲城到乙城需時 5 小時。若速度增加 25%，則所需時間減少幾多？', '[{"key":"A","text":"20%"},{"key":"B","text":"25%"},{"key":"C","text":"40%"},{"key":"D","text":"視乎路程長短"}]', 'A', 't′=s/(1.25v)=t/1.25=4h；(5−4)/5=20%。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-1', 'logic', '一男子指著甲向他人介紹：「他的兄弟的爸爸是我女兒的父親。」問我是甲的？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"祖父"},{"key":"D","text":"叔伯"}]', 'B', '我女兒的父親 = 我；他的兄弟的爸爸 = 甲的父親 ⇒ 甲的父親 = 我，故我是甲的父親。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-2', 'logic', '一名男士說：「我是甲的爸爸的獨生子的兒子。」請問這位男士是甲的什麼身份？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"叔父"},{"key":"D","text":"兄弟"}]', 'A', '甲的爸爸的獨生子 = 甲（獨生子指唯一兒子）；其兒子 = 男士 ⇒ 男士是甲的兒子。歷屆思路選 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-3', 'logic', '一名男人指住甲介紹：「他是我兄弟的爸爸的女兒的父親。」問甲與該男人的關係？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"兄弟"},{"key":"D","text":"以上皆非"}]', 'A', '我兄弟的爸爸 = 我父親；其女兒的父親 = 我父親（女兒的父親即我父親本人）⇒ 甲 = 我父親？ 或：我兄弟的爸爸的女兒 = 我姊妹，其父親 = 我父親；題問「甲的關係」，若甲 = 該男人，則矛盾。若「他」指甲，則甲 = 我兄弟的爸爸的女兒的父親 = 我父親 ⇒ 甲是該男人的父親，選 B。歷屆思路：「甲是他的父親，他是甲的兒子」⇒ 選 A 兒子（指甲是該男人的兒子，即該男人是甲的父親）。依歷屆選 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-9', 'math', 'X 為偶數，Y 為奇數，下列哪個運算結果為偶數？', '[{"key":"A","text":"X+Y"},{"key":"B","text":"X−Y"},{"key":"C","text":"X×Y"},{"key":"D","text":"X÷Y"}]', 'C', '偶×奇=偶。X+Y、X−Y 可能為奇；X/Y 未必整數。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-10', 'math', '蘋果、橙、梨比例 4:5:6。蘋果減少 20%、橙增加 8%、梨減少 10% 後，新比例為？', '[{"key":"A","text":"16:27:27"},{"key":"B","text":"16:23:27"},{"key":"C","text":"33:52:54"},{"key":"D","text":"32:54:54"}]', 'A', '4×0.8 : 5×1.08 : 6×0.9 = 3.2 : 5.4 : 5.4 = 32:54:54 = 16:27:27。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-11', 'math', '定義 S_{x,m}(k)=k/(x+m)。求 S_{4,3}(S_{3,2}(12)) = ?', '[{"key":"A","text":"1.5"},{"key":"B","text":"3"},{"key":"C","text":"4.5"},{"key":"D","text":"6"}]', 'C', 'S_{3,2}(12)=12/(3+2)=2.4；S_{4,3}(2.4)=2.4/(4+3) 非選項。若 S_{3,2}(12)=12/3+2=6（題意或為 k/x + m），則 S_{4,3}(6)=6/4+3=1.5+3=4.5。歷屆答案 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-12', 'math', '陳先生把每月收入 1/3 給陳太太後，二人收入相等。原陳先生和陳太太收入比例為？', '[{"key":"A","text":"1:3"},{"key":"B","text":"3:1"},{"key":"C","text":"5:4"},{"key":"D","text":"4:5"}]', 'B', '設陳生 X、陳太 Y。(2/3)X = Y + (1/3)X ⇒ (1/3)X = Y ⇒ X:Y = 3:1。或代 30、10 驗算。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-13', 'math', '一個橙約 70–100 克，一個蘋果約 160–220 克。兩個橙加一個蘋果大約重量？', '[{"key":"A","text":"230–320"},{"key":"B","text":"300–420"},{"key":"C","text":"330–440"},{"key":"D","text":"360–450"}]', 'B', '兩橙 140–200，加一蘋果 160–220 ⇒ 總 300–420 克。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-14', 'math', '已知 K<1，X>Y。以下正確的是？', '[{"key":"A","text":"K+X<K+Y"},{"key":"B","text":"K−X<K−Y"},{"key":"C","text":"KX>KY"},{"key":"D","text":"以上都不是"}]', 'D', 'K<1 可能為 0 或負，KX>KY 在 K<0 時反號。歷屆註：存在爭議，另一版本選 B（K−X<K−Y）。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-15', 'math', '比較大小：A. 10.1×9.9  B. √(101×99)  C. 100。哪個最大？', '[{"key":"A","text":"A"},{"key":"B","text":"B"},{"key":"C","text":"C"},{"key":"D","text":"一樣大"}]', 'C', 'A=100−0.01=99.99；B=√9999<100；C=100 最大。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-16', 'math', '袋中有 10 個橙，其中 7 個新鮮、3 個爛。抽 2 個都抽到新鮮的機率？（不放回）', '[{"key":"A","text":"7/15"},{"key":"B","text":"49/100"},{"key":"C","text":"7/10"},{"key":"D","text":"6/9"}]', 'A', '(7/10)×(6/9)=42/90=7/15。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-17', 'math', '貨品售價比成本高 3600 元。若打 10% 折扣後售價為 2X，成本為 X。求 X 的方程式？', '[{"key":"A","text":"0.9X=2X"},{"key":"B","text":"0.9(X+3600)=2X"},{"key":"C","text":"X+3600=2X"},{"key":"D","text":"0.9(X+3600)=2X/1.1"}]', 'B', '售價 Y=X+3600；打 9 折後 0.9Y=2X ⇒ 0.9(X+3600)=2X。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-18', 'math', '甲、乙、丙、丁皆正整數，和為 90。若甲+2、乙−2、丙×2、丁÷2 後四數相同，問甲為多少？', '[{"key":"A","text":"8"},{"key":"B","text":"16"},{"key":"C","text":"18"},{"key":"D","text":"22"}]', 'C', '設相同結果為 k，則甲=k−2、乙=k+2、丙=k/2、丁=2k；和 (k−2)+(k+2)+k/2+2k=90 ⇒ 4.5k=90 ⇒ k=20，甲=18。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-19', 'math', '小明和小強平均身高 164 cm，小強和小芳 168 cm，小芳和小明 165 cm。小強身高？', '[{"key":"A","text":"149"},{"key":"B","text":"161"},{"key":"C","text":"163"},{"key":"D","text":"167"}]', 'D', '明+強=328，強+芳=336，芳+明=330；三式相加 2(明+強+芳)=994 ⇒ 明+強+芳=497；強=497−330=167。歷屆答案 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-20', 'math', '某城市 100 人：男性 60 人，持駕照 30 人，女性沒駕照 32 人。問男性持駕照人數？', '[{"key":"A","text":"22"},{"key":"B","text":"30"},{"key":"C","text":"8"},{"key":"D","text":"38"}]', 'A', '女性 40 人，女性持駕照 40−32=8；男性持駕照 30−8=22。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-21', 'math', '北京來回機票淡季 $2000–$3500，旺季 $4000–$6000。淡旺季價錢浮動範圍？', '[{"key":"A","text":"$500–$6000"},{"key":"B","text":"$2000–$2500"},{"key":"C","text":"$500–$4000"},{"key":"D","text":"$2750–$5000"}]', 'C', '最小浮動 4000−3500=500；最大浮動 6000−2000=4000。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-math-22', 'math', '大雞蛋 120 個（10 打）、小雞蛋 50 打。大雞蛋每打 10.5 元，小雞蛋每打 9.5 元。總價？', '[{"key":"A","text":"475"},{"key":"B","text":"580"},{"key":"C","text":"105"},{"key":"D","text":"1050"}]', 'B', '10×10.5+50×9.5=105+475=580 元。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-4', 'logic', '已知所有牛油都是新鮮的，新鮮的都不昂貴。以下哪一項正確？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆錯"}]', 'A', '牛油→新鮮→不昂貴，故所有牛油都不昂貴。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-5', 'logic', '日蝕的時候貓一定會叫；貓不會叫的時候月亮會有發光。下列哪一個對？', '[{"key":"A","text":"日蝕的時候月亮會發光"},{"key":"B","text":"日蝕的時候月亮不會發光"},{"key":"C","text":"日蝕的時候有時月亮會發光"},{"key":"D","text":"以上皆錯"}]', 'D', '日蝕⇒貓叫；貓不叫⇒月發光。日蝕時貓叫，無法推月發光與否；歷屆思路選 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-logic-6', 'logic', '所有優秀的學生都不上課，不努力的學生都去上課。下列哪一個對？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的並不是優秀的學生"},{"key":"C","text":"不努力的學生並不是優秀的學生"},{"key":"D","text":"以上皆錯"}]', 'A', '上課⇒不優秀（逆否：優秀⇒不上課）。故所有上課的學生都不優秀。另一卷選項表述不同有選 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-1', 'chart', '政府某部門舉行活動人手不足，需各局派人幫手，用哪種文件？', '[{"key":"A","text":"內部通知"},{"key":"B","text":"建議書"},{"key":"C","text":"申請書"},{"key":"D","text":"公函"}]', 'D', '跨部門協調通常用公函。歷屆選 E 公函，選項中為 D。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-2', 'chart', '政府某部門要買影印機，現向主管回報以向商家報價，用哪種文件？', '[{"key":"A","text":"部門公告"},{"key":"B","text":"通知"},{"key":"C","text":"建議書"},{"key":"D","text":"申請書"}]', 'C', '向上級建議採購用建議書。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-3', 'chart', '以下哪種格式的影音文檔能放進 PowerPoint？', '[{"key":"A","text":"MP3"},{"key":"B","text":"WMV"},{"key":"C","text":"WMA"},{"key":"D","text":"MID"}]', 'B', 'PowerPoint 支援 WMV 等視訊格式；MP3/WMA 為音訊，MID 為 MIDI 指令非錄音。歷屆選 WMV。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-4', 'chart', 'Excel 複製貼上時要令儲存格參照不變（如 A2/E3），應使用？', '[{"key":"A","text":"$A$2/$E$3"},{"key":"B","text":"!A!2/!E!3"},{"key":"C","text":"&A&2/&E&3"},{"key":"D","text":"=A2/E3"}]', 'A', '絕對參照用 $A$2/$E$3。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-5', 'chart', 'Excel 儲存格 B1 公式 =A1/A2，複製貼上到 C2 後，C2 公式為？', '[{"key":"A","text":"A1/A2"},{"key":"B","text":"B2/B3"},{"key":"C","text":"C1/C2"},{"key":"D","text":"A2/A3"}]', 'B', '相對參照：列、欄各+1，故 C2 為 B2/B3。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-2020-chart-6', 'chart', '以下不屬於 MS Word「合併列印」中可選取的文件類型為？', '[{"key":"A","text":"日曆"},{"key":"B","text":"標籤"},{"key":"C","text":"信封"},{"key":"D","text":"目錄"}]', 'D', '合併列印常用信函、信封、標籤等，目錄通常不經合併列印產生。另一版本答案為 A（日曆）。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-word-1', 'chart', 'Word「郵件」選取收件者，下列哪項不正確？', '[{"key":"A","text":"建立新清單"},{"key":"B","text":"使用現有清單"},{"key":"C","text":"從 Outlook 連絡人選擇"},{"key":"D","text":"從網絡郵件連絡人選擇"}]', 'D', '歷屆思路：從網絡郵件連絡人選擇不屬 Word 合併列印收件者選項，故不正確。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-math-1', 'math', '數獨：每行每列和為 45。問中間問號？
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-math-2', 'math', '生日 1977 年 7 月，執照領取時間 2005 年 11 月。問他在多少歲時領取執照？', '[{"key":"A","text":"27"},{"key":"B","text":"28"},{"key":"C","text":"31"},{"key":"D","text":"無法計算"}]', 'B', '2005−1977=28；11 月已過 7 月生日，故 28 歲。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-logic-1', 'logic', '甲、乙、丙、丁、戊、己面向圓枱中心坐。已知丁不與丙和戊相鄰，丙和甲、乙相鄰。請問丁與誰相鄰？', '[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"戊"}]', 'B', '圓桌排列：丙與甲乙相鄰，丁不與丙、戊相鄰 ⇒ 丁與甲或乙相鄰。歷屆常見答案為乙。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-chart-1', 'chart', 'Excel：B1 入職日期，B2 離職日期（未離職則空白）。求在職總日數的公式應為？', '[{"key":"A","text":"B2-B1"},{"key":"B","text":"IF(ISNUMBER(B2),B2-B1,TODAY()-B1)"},{"key":"C","text":"IF(ISNUMBER(B2),B2-B1,TODAY()-B1)+1"},{"key":"D","text":"COUNTIF(...)"}]', 'C', '若 B2 為數字則 B2−B1，否則 TODAY()−B1；含入職當日故 +1。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-math-3', 'math', '圖中有多少個不同的三角形？（由 1 個、2 個、4 個小三角形組成）', '[{"key":"A","text":"16"},{"key":"B","text":"14"},{"key":"C","text":"8"},{"key":"D","text":"15"}]', 'A', '歷屆思路：1 個三角形 8 個、2 個組成 4 個、4 個組成 4 個，共 16 個。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-chart-2', 'chart', 'Excel 表格內容為「1,2,3 / 4,5,6 / 7,8,9」改為「1 2 3 / 4 5 6 / 7 8 9」（以空格分隔），應用何種功能？', '[{"key":"A","text":"資料分割"},{"key":"B","text":"儲存格格式"},{"key":"C","text":"格式化設定"},{"key":"D","text":"取代"}]', 'A', '以分隔符號（逗號）分割欄位後可得多欄。歷屆思路選 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-chart-3', 'chart', 'Excel 表格由 A 欄（110、120、130）轉為 B 欄（Mop110、Mop120、Mop130），應用何種方法？', '[{"key":"A","text":"資料剖析"},{"key":"B","text":"儲存格格式"},{"key":"C","text":"格式化設定"},{"key":"D","text":"公式"}]', 'B', '自訂儲存格格式可顯示為「Mop」+ 數字。歷屆思路選 B。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-chart-4', 'chart', 'Excel 數字 123，將「1」取代成「2020」後，數字變成？', '[{"key":"A","text":"20203"},{"key":"B","text":"202023"},{"key":"C","text":"12020"},{"key":"D","text":"2020123"}]', 'A', '取代「1」為「2020」：123 → 202023 若只取代第一個字元；題意常為首位 1 取代為 2020 得 20203。歷屆答案 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-math-4', 'math', 'X=0.006，Y=√0.0036，Z=6/10000。請由大到小排列。', '[{"key":"A","text":"X>Y>Z"},{"key":"B","text":"X>Z>Y"},{"key":"C","text":"Y>X>Z"},{"key":"D","text":"Y>Z>X"}]', 'C', 'X=0.006，Y=0.06，Z=0.0006 ⇒ Y>X>Z。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-math-5', 'math', '2≤X≤3 時，√(X−2)+√(X−1)=？', '[{"key":"A","text":"−3"},{"key":"B","text":"3"},{"key":"C","text":"5−2x"},{"key":"D","text":"2x−5"}]', 'B', 'X≥2 時 X−2≥0，X≥1 時 X−1≥0，兩根號皆非負，和為非負。2≤X≤3 時 √(X−2)+√(X−1)=√(X−2)+√(X−1)，常考結果為 3（或需依題意代入）。歷屆選 B。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-logic-2', 'logic', '電飯煲功能鍵順序：正常→煲粥→整蛋糕→加熱→循環。目前為「加熱」，按 100 下後會到哪個功能？', '[{"key":"A","text":"正常"},{"key":"B","text":"煲粥"},{"key":"C","text":"整蛋糕"},{"key":"D","text":"加熱"}]', 'D', '4 個功能一循環，100÷4=25 餘 0，故仍在加熱。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-logic-3', 'logic', '已知 X+2>3−Y，下列哪項正確？', '[{"key":"A","text":"X+Y>1"},{"key":"B","text":"X+Y>5"},{"key":"C","text":"X−Y>1"},{"key":"D","text":"X−Y>5"}]', 'A', 'X+2>3−Y ⇒ X+Y>1。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-logic-4', 'logic', '甲、乙、丙、丁、戊、己跑步。戊第一個衝線，甲不是緊隨戊的，己緊跟丙後面，丁與丙差不多同步，乙跑尾二。問誰跑最尾？', '[{"key":"A","text":"甲"},{"key":"B","text":"己"},{"key":"C","text":"丙"},{"key":"D","text":"無法估計"}]', 'A', '順序可推為：戊、丁、丙、己、乙、甲；甲最尾。歷屆答案 A。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-past-pdf2-chart-5', 'chart', '圖表顯示 4 間市場 2012 與 2013 年大雞蛋和小雞蛋一打價錢及漲幅%。問四間市場的大雞蛋上漲率平均數？', '[{"key":"A","text":"7.3%"},{"key":"B","text":"7.9%"},{"key":"C","text":"8.0%"},{"key":"D","text":"8.5%"}]', 'B', '需依圖表計算四市場大雞蛋漲幅後取平均。歷屆答案 B（7.9%）。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-math-2', 'math', '若 3x - 4 = 11，則 x = ?', '[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"7"}]', 'B', '3x = 11 + 4 = 15，故 x = 5。', '["260"]');
