INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-381', 'chart', 'Excel 複製貼上時要令儲存格參照不變（如 A2），應使用？', '[{"key":"A","text":"相對參照"},{"key":"B","text":"絕對參照 $A$2"},{"key":"C","text":"混合參照"},{"key":"D","text":"名稱管理員"}]', 'B', '絕對參照以 $ 鎖定欄列，如 $A$2。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-382', 'chart', 'Excel 儲存格 B1 公式 =A1/A2，複製貼上到 C2 後，C2 公式為？', '[{"key":"A","text":"A1/A2"},{"key":"B","text":"B2/B3"},{"key":"C","text":"C1/C2"},{"key":"D","text":"A2/A3"}]', 'B', '相對參照：列、欄各+1，故 C2 為 B2/B3。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-383', 'chart', '以下哪種格式的影音文檔能放進 PowerPoint？', '[{"key":"A","text":"MP3"},{"key":"B","text":"WMV"},{"key":"C","text":"WMA"},{"key":"D","text":"MID"}]', 'B', 'PowerPoint 支援 WMV 等視訊格式；MP3/WMA 為音訊。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-384', 'chart', '以下不屬於 MS Word「合併列印」中可選取的文件類型為？', '[{"key":"A","text":"日曆"},{"key":"B","text":"標籤"},{"key":"C","text":"信封"},{"key":"D","text":"目錄"}]', 'D', '合併列印常用信函、信封、標籤等，目錄通常不經合併列印產生。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-385', 'chart', 'Excel 中 $A1 表示？', '[{"key":"A","text":"絕對欄 A、相對列"},{"key":"B","text":"相對欄、絕對列 1"},{"key":"C","text":"絕對欄與列"},{"key":"D","text":"錯誤公式"}]', 'A', '$A1 為混合參照：欄 A 固定、列隨複製改變。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-386', 'chart', '要讓 Excel 公式中的列不隨複製改變，應寫成？', '[{"key":"A","text":"A$1"},{"key":"B","text":"$A1"},{"key":"C","text":"A1"},{"key":"D","text":"$A$1"}]', 'A', 'A$1 表示列 1 固定、欄隨複製改變。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-387', 'chart', 'Excel 中若要計算 A1 到 A10 總和，公式應為？', '[{"key":"A","text":"=SUM(A1:A10)"},{"key":"B","text":"=TOTAL(A1:A10)"},{"key":"C","text":"=ADD(A1:A10)"},{"key":"D","text":"=A1+A10"}]', 'A', 'SUM 為加總函數，A1:A10 為範圍。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-388', 'chart', '下列何者為 Excel 的絕對參照寫法？', '[{"key":"A","text":"A1"},{"key":"B","text":"$A$1"},{"key":"C","text":"A$1"},{"key":"D","text":"1A"}]', 'B', '絕對參照以 $ 鎖定欄與列：$A$1。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-389', 'chart', 'Excel 儲存格顯示 #DIV/0! 表示？', '[{"key":"A","text":"除數為零"},{"key":"B","text":"參照錯誤"},{"key":"C","text":"數值溢位"},{"key":"D","text":"格式錯誤"}]', 'A', '#DIV/0! 表示公式中有除以零。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-390', 'chart', 'Word 合併列印「插入合併欄位」用途為？', '[{"key":"A","text":"插入固定文字"},{"key":"B","text":"插入資料來源欄位"},{"key":"C","text":"插入圖片"},{"key":"D","text":"插入表格"}]', 'B', '合併欄位會從資料來源帶入對應欄位值。', '["260"]');
