INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-chart-393', 'chart', 'Excel 中 A1:A5 為 10,20,30,40,50，=AVERAGE(A1:A5) 結果為？', '[{"key":"A","text":"30"},{"key":"B","text":"35"},{"key":"C","text":"150"},{"key":"D","text":"25"}]', 'A', '平均 = (10+20+30+40+50)/5 = 30。', '["260"]');
