INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-101', 'logic', '若「所有 A 都是 B」且「有些 B 是 C」，則可確定：', '[{"key":"A","text":"所有 A 都是 C"},{"key":"B","text":"有些 A 可能是 C"},{"key":"C","text":"所有 B 都是 A"},{"key":"D","text":"有些 C 不是 B"}]', 'B', '由「所有 A 都是 B」與「有些 B 是 C」，只能推得「有些 A 可能是 C」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-102', 'logic', '所有哺乳類動物都是胎生的，所有牛都是哺乳類動物。那麼：', '[{"key":"A","text":"所有哺乳類動物都是牛"},{"key":"B","text":"所有牛都是胎生的"},{"key":"C","text":"所有四肢哺乳類都是胎生的"},{"key":"D","text":"以上皆非"}]', 'B', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-103', 'logic', '凡是北極的生物都是白色的。所有白色的動物都不是胎生的。由此可以推論出？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-104', 'logic', '已知「沒有 金屬 是 導電體」且「所有 可導電 都是 導電體」。由此可推論？', '[{"key":"A","text":"沒有 金屬 是 可導電"},{"key":"B","text":"所有 金屬 都是 可導電"},{"key":"C","text":"有些 可導電 是 金屬"},{"key":"D","text":"以上皆非"}]', 'A', 'A∩B=∅ 且 C⊂B ⇒ A∩C=∅。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-105', 'logic', '已知「所有哺乳類都是胎生的」且「所有牛都是哺乳類」。由此可推論？', '[{"key":"A","text":"所有牛都是胎生的"},{"key":"B","text":"所有哺乳類都是牛"},{"key":"C","text":"有些牛不是胎生的"},{"key":"D","text":"以上皆非"}]', 'A', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-106', 'logic', '已知「所有哺乳類都不下蛋」且「所有母雞都會下蛋」。由此可推論？', '[{"key":"A","text":"所有母雞都不是哺乳類"},{"key":"B","text":"有些母雞是哺乳類"},{"key":"C","text":"所有哺乳類都是母雞"},{"key":"D","text":"以上皆非"}]', 'A', '哺乳類不下蛋、母雞下蛋 ⇒ 母雞不屬於哺乳類。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-107', 'logic', '已知「凡是北極的生物都是白色的」且「所有白色的動物都不是胎生的」。由此可推論？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-108', 'logic', '已知「所有牛油都是新鮮的」且「新鮮的都不昂貴」。由此可推論？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆非"}]', 'A', '牛油→新鮮→不昂貴。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-109', 'logic', '已知「所有優秀的學生都不上課」且「不努力的學生都去上課」。由此可推論？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的都是優秀的學生"},{"key":"C","text":"不努力的學生是優秀的"},{"key":"D","text":"以上皆非"}]', 'A', '上課⇒不優秀。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-110', 'logic', '已知「所有 金屬 都是 導電體」且「有些 導電體 是 可導電」。由此可推論？', '[{"key":"A","text":"所有 金屬 都是 可導電"},{"key":"B","text":"有些 金屬 可能是 可導電"},{"key":"C","text":"沒有 金屬 是 可導電"},{"key":"D","text":"以上皆非"}]', 'B', '所有 A 都是 B、有些 B 是 C ⇒ 只能推得「有些 A 可能是 C」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-111', 'logic', '已知「所有 鳥 都是 有翼」且「所有 有翼 都是 會飛」。由此可推論？', '[{"key":"A","text":"所有 鳥 都是 會飛"},{"key":"B","text":"有些 鳥 是 會飛"},{"key":"C","text":"沒有 鳥 是 會飛"},{"key":"D","text":"以上皆非"}]', 'A', 'A⊂B⊂C ⇒ 所有 A 都是 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-112', 'logic', '已知「所有 公務員 都是 依法辦事」且「沒有 依法辦事 是 不得徇私」。由此可推論？', '[{"key":"A","text":"所有 公務員 都是 不得徇私"},{"key":"B","text":"沒有 公務員 是 不得徇私"},{"key":"C","text":"有些 公務員 是 不得徇私"},{"key":"D","text":"以上皆非"}]', 'B', 'A⊂B 且 B∩C=∅ ⇒ 沒有 A 是 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-113', 'logic', '已知「沒有 A 是 B」且「所有 C 都是 B」。由此可推論？', '[{"key":"A","text":"沒有 A 是 C"},{"key":"B","text":"所有 A 都是 C"},{"key":"C","text":"有些 C 是 A"},{"key":"D","text":"以上皆非"}]', 'A', 'A∩B=∅ 且 C⊂B ⇒ A∩C=∅。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-114', 'logic', '已知「所有哺乳類都是胎生的」且「所有牛都是哺乳類」。由此可推論？', '[{"key":"A","text":"所有牛都是胎生的"},{"key":"B","text":"所有哺乳類都是牛"},{"key":"C","text":"有些牛不是胎生的"},{"key":"D","text":"以上皆非"}]', 'A', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-115', 'logic', '已知「所有哺乳類都不下蛋」且「所有母雞都會下蛋」。由此可推論？', '[{"key":"A","text":"所有母雞都不是哺乳類"},{"key":"B","text":"有些母雞是哺乳類"},{"key":"C","text":"所有哺乳類都是母雞"},{"key":"D","text":"以上皆非"}]', 'A', '哺乳類不下蛋、母雞下蛋 ⇒ 母雞不屬於哺乳類。', '["260"]');
