INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-193', 'logic', '已知「所有 律師 都是 專業人士」且「沒有 專業人士 是 受過高等教育」。由此可推論？', '[{"key":"A","text":"所有 律師 都是 受過高等教育"},{"key":"B","text":"沒有 律師 是 受過高等教育"},{"key":"C","text":"有些 律師 是 受過高等教育"},{"key":"D","text":"以上皆非"}]', 'B', 'A⊂B 且 B∩C=∅ ⇒ 沒有 A 是 C。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-194', 'logic', '已知「沒有 金屬 是 導電體」且「所有 可導電 都是 導電體」。由此可推論？', '[{"key":"A","text":"沒有 金屬 是 可導電"},{"key":"B","text":"所有 金屬 都是 可導電"},{"key":"C","text":"有些 可導電 是 金屬"},{"key":"D","text":"以上皆非"}]', 'A', 'A∩B=∅ 且 C⊂B ⇒ A∩C=∅。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-195', 'logic', '已知「所有哺乳類都是胎生的」且「所有牛都是哺乳類」。由此可推論？', '[{"key":"A","text":"所有牛都是胎生的"},{"key":"B","text":"所有哺乳類都是牛"},{"key":"C","text":"有些牛不是胎生的"},{"key":"D","text":"以上皆非"}]', 'A', '牛⊂哺乳類⊂胎生 ⇒ 所有牛都是胎生的。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-196', 'logic', '已知「所有哺乳類都不下蛋」且「所有母雞都會下蛋」。由此可推論？', '[{"key":"A","text":"所有母雞都不是哺乳類"},{"key":"B","text":"有些母雞是哺乳類"},{"key":"C","text":"所有哺乳類都是母雞"},{"key":"D","text":"以上皆非"}]', 'A', '哺乳類不下蛋、母雞下蛋 ⇒ 母雞不屬於哺乳類。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-197', 'logic', '已知「凡是北極的生物都是白色的」且「所有白色的動物都不是胎生的」。由此可推論？', '[{"key":"A","text":"每種北極的生物都不是胎生的"},{"key":"B","text":"北極的生物都是胎生的"},{"key":"C","text":"每種白色的生物都在北極"},{"key":"D","text":"以上皆非"}]', 'A', '北極生物→白色→非胎生。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-198', 'logic', '已知「所有牛油都是新鮮的」且「新鮮的都不昂貴」。由此可推論？', '[{"key":"A","text":"所有牛油都不昂貴"},{"key":"B","text":"牛油有些是昂貴的"},{"key":"C","text":"所有新鮮的都是牛油"},{"key":"D","text":"以上皆非"}]', 'A', '牛油→新鮮→不昂貴。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-199', 'logic', '已知「所有優秀的學生都不上課」且「不努力的學生都去上課」。由此可推論？', '[{"key":"A","text":"所有上課的學生都不優秀"},{"key":"B","text":"所有上課的都是優秀的學生"},{"key":"C","text":"不努力的學生是優秀的"},{"key":"D","text":"以上皆非"}]', 'A', '上課⇒不優秀。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-200', 'logic', '已知「所有 金屬 都是 導電體」且「有些 導電體 是 可導電」。由此可推論？', '[{"key":"A","text":"所有 金屬 都是 可導電"},{"key":"B","text":"有些 金屬 可能是 可導電"},{"key":"C","text":"沒有 金屬 是 可導電"},{"key":"D","text":"以上皆非"}]', 'B', '所有 A 都是 B、有些 B 是 C ⇒ 只能推得「有些 A 可能是 C」。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-201', 'logic', '己是戊的母親，乙的女兒是己，丁的妹妹是戊。問戊是乙的誰？', '[{"key":"A","text":"外孫女"},{"key":"B","text":"姐妹"},{"key":"C","text":"外祖母"},{"key":"D","text":"以上皆非"}]', 'A', '乙的女兒是己，己是戊的母親 ⇒ 戊是乙的外孫女。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-202', 'logic', '甲是乙的母親，乙是丙的哥哥，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"丈夫"},{"key":"C","text":"妻子"},{"key":"D","text":"無法確定"}]', 'B', '乙是丙的哥哥⇒乙、丙同輩；丙是丁的兒子⇒丁是丙的父親；甲是乙的母親⇒丁是甲的丈夫。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-203', 'logic', '李先生的媳婦介紹某人：「她的父親是李先生的獨生子。」那個人是李先生媳婦的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"女兒"},{"key":"C","text":"姊妹"},{"key":"D","text":"無法確定"}]', 'B', '李先生的獨生子是「她」的父親⇒「她」是李先生媳婦的女兒。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-204', 'logic', '一男子指著甲向他人介紹：「他的兄弟的爸爸是我女兒的父親。」問我是甲的？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"祖父"},{"key":"D","text":"叔伯"}]', 'B', '我女兒的父親=我；他的兄弟的爸爸=甲的父親⇒我是甲的父親。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-205', 'logic', '一名男士說：「我是甲的爸爸的獨生子的兒子。」請問這位男士是甲的什麼身份？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"叔父"},{"key":"D","text":"兄弟"}]', 'A', '甲的爸爸的獨生子=甲；其兒子=男士⇒男士是甲的兒子。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-206', 'logic', '一位女士指著甲說：「她的母親是我母親的獨生女。」問甲是女士的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"妹妹"},{"key":"C","text":"女兒"},{"key":"D","text":"姨媽"}]', 'C', '我母親的獨生女=女士本人；她的母親是女士⇒甲是女士的女兒。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-207', 'logic', '甲是乙的父親，乙是丙的母親，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"曾孫"},{"key":"B","text":"孫子"},{"key":"C","text":"兒子"},{"key":"D","text":"兄弟"}]', 'A', '乙是丙的母親⇒丙是乙的子女；丙是丁的兒子⇒丁是甲的曾孫。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-208', 'logic', '王先生的父親是李女士的獨生子。問李女士是王先生的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"祖母"},{"key":"C","text":"外祖母"},{"key":"D","text":"姑母"}]', 'B', '李女士的獨生子=王先生的父親⇒李女士是王先生的祖母。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-209', 'logic', '一個男士向別人介紹甲說：「他是我妹妹的祖母的獨生子的妻子的兒子。」問甲是那個男人的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"表兄弟"}]', 'C', '妹妹的祖母的獨生子=妹妹的父親=該男士；其妻子的兒子=該男士與妻之子⇒甲與其子為兄弟，依歷屆答案為兄弟。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-210', 'logic', '張先生說：「她的母親是我父親的獨生子的妻子。」張先生是某人的？', '[{"key":"A","text":"父親"},{"key":"B","text":"兒子"},{"key":"C","text":"兄弟"},{"key":"D","text":"無法判斷"}]', 'A', '我父親的獨生子即張先生自己，他的妻子即張太太；她的母親是張太太，則某人為張先生與張太太的兒子。', '["260"]');
