INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-271', 'logic', '己是戊的母親，乙的女兒是己，丁的妹妹是戊。問戊是乙的誰？', '[{"key":"A","text":"外孫女"},{"key":"B","text":"姐妹"},{"key":"C","text":"外祖母"},{"key":"D","text":"以上皆非"}]', 'A', '乙的女兒是己，己是戊的母親 ⇒ 戊是乙的外孫女。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-272', 'logic', '甲是乙的母親，乙是丙的哥哥，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"父親"},{"key":"B","text":"丈夫"},{"key":"C","text":"妻子"},{"key":"D","text":"無法確定"}]', 'B', '乙是丙的哥哥⇒乙、丙同輩；丙是丁的兒子⇒丁是丙的父親；甲是乙的母親⇒丁是甲的丈夫。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-273', 'logic', '李先生的媳婦介紹某人：「她的父親是李先生的獨生子。」那個人是李先生媳婦的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"女兒"},{"key":"C","text":"姊妹"},{"key":"D","text":"無法確定"}]', 'B', '李先生的獨生子是「她」的父親⇒「她」是李先生媳婦的女兒。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-274', 'logic', '一男子指著甲向他人介紹：「他的兄弟的爸爸是我女兒的父親。」問我是甲的？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"祖父"},{"key":"D","text":"叔伯"}]', 'B', '我女兒的父親=我；他的兄弟的爸爸=甲的父親⇒我是甲的父親。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-275', 'logic', '一名男士說：「我是甲的爸爸的獨生子的兒子。」請問這位男士是甲的什麼身份？', '[{"key":"A","text":"兒子"},{"key":"B","text":"父親"},{"key":"C","text":"叔父"},{"key":"D","text":"兄弟"}]', 'A', '甲的爸爸的獨生子=甲；其兒子=男士⇒男士是甲的兒子。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-276', 'logic', '一位女士指著甲說：「她的母親是我母親的獨生女。」問甲是女士的誰？', '[{"key":"A","text":"母親"},{"key":"B","text":"妹妹"},{"key":"C","text":"女兒"},{"key":"D","text":"姨媽"}]', 'C', '我母親的獨生女=女士本人；她的母親是女士⇒甲是女士的女兒。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-277', 'logic', '甲是乙的父親，乙是丙的母親，丙是丁的兒子。問丁是甲的誰？', '[{"key":"A","text":"曾孫"},{"key":"B","text":"孫子"},{"key":"C","text":"兒子"},{"key":"D","text":"兄弟"}]', 'A', '乙是丙的母親⇒丙是乙的子女；丙是丁的兒子⇒丁是甲的曾孫。', '["260"]');
