INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-301', 'logic', '規律：3⇒5，4⇒12，3⇒⇒21，4⇒⇒？（⇒ 表示平方後減 4）', '[{"key":"A","text":"28"},{"key":"B","text":"35"},{"key":"C","text":"36"},{"key":"D","text":"140"}]', 'D', '4⇒12 即 4²-4=12；4⇒⇒=(4²-4)²-4=12²-4=140。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-302', 'logic', '定義 a⇒b 表示「a 的平方減 4 等於 b」。則 4⇒⇒？（即 4 連續運算兩次）', '[{"key":"A","text":"21"},{"key":"B","text":"130"},{"key":"C","text":"140"},{"key":"D","text":"145"}]', 'C', '4⇒12，12⇒140。', '["260"]');
