INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-405', 'logic', '甲、乙、丙、丁、戊排隊。已知：五人排隊，甲排第一，戊排最後，乙在丙前，丁在乙前。問排第一的是誰？', '[{"key":"A","text":"甲"},{"key":"B","text":"丁"},{"key":"C","text":"乙"},{"key":"D","text":"丙"}]', 'A', '依條件可推順序為：甲、丁、乙、丙、戊，故第一為 甲。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-406', 'logic', '甲、乙、丙、丁排隊。已知：丙第一，甲在乙前，丁最後。問排第一的是誰？', '[{"key":"A","text":"丙"},{"key":"B","text":"甲"},{"key":"C","text":"乙"},{"key":"D","text":"丁"}]', 'A', '依條件可推順序為：丙、甲、乙、丁，故第一為 丙。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-407', 'logic', '甲、乙、丙、丁排隊。已知：乙不是第一，甲在丙前，丁在最後。問排第一的是誰？', '[{"key":"A","text":"甲"},{"key":"B","text":"丙"},{"key":"C","text":"乙"},{"key":"D","text":"丁"}]', 'A', '依條件可推順序為：甲、丙、乙、丁，故第一為 甲。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-408', 'logic', '甲、乙、丙、丁排隊。已知：丁第一，甲在乙前，丙最後。問排第一的是誰？', '[{"key":"A","text":"丁"},{"key":"B","text":"甲"},{"key":"C","text":"乙"},{"key":"D","text":"丙"}]', 'A', '依條件可推順序為：丁、甲、乙、丙，故第一為 丁。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-409', 'logic', '甲、乙、丙、丁排隊。已知：甲、乙、丙、丁四人，甲不是最後，乙在丙前，丁不是第一。問排第一的是誰？', '[{"key":"A","text":"甲"},{"key":"B","text":"丁"},{"key":"C","text":"乙"},{"key":"D","text":"丙"}]', 'A', '依條件可推順序為：甲、丁、乙、丙，故第一為 甲。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-410', 'logic', '甲、乙、丙、丁、戊排隊。已知：戊第一，丁最後，乙在甲前，丙在甲後。問排第一的是誰？', '[{"key":"A","text":"戊"},{"key":"B","text":"乙"},{"key":"C","text":"甲"},{"key":"D","text":"丙"}]', 'A', '依條件可推順序為：戊、乙、甲、丙、丁，故第一為 戊。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-411', 'logic', '「理論：實驗：現象」的類比，與下列哪組關係相同？', '[{"key":"A","text":"習慣：使用：工具"},{"key":"B","text":"診斷：治療：癥狀"},{"key":"C","text":"學習：測驗：成績"},{"key":"D","text":"努力：成功：困難"}]', 'C', '理論透過實驗得出現象；學習透過測驗得出成績。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-412', 'logic', '「總結、引言」的關係，就如「附錄」跟下列哪項的關係？', '[{"key":"A","text":"章節"},{"key":"B","text":"序"},{"key":"C","text":"索引"},{"key":"D","text":"文章"}]', 'B', '總結與引言在文首文尾；附錄與序亦然。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-413', 'logic', '「方向」對「？」、「？」對「秤」。與「方向」同一類的是？', '[{"key":"A","text":"南；公斤"},{"key":"B","text":"指南針；重量"},{"key":"C","text":"方位；陀"},{"key":"D","text":"東；天平"}]', 'B', '方向用指南針測量，重量用秤測量。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-414', 'logic', '若以下假設成立，可以證明「人力成本是最大支出」：公司支出最大部分係員工薪俸。', '[{"key":"A","text":"在經濟不景氣時，各大上市公司都減人資支出及福利"},{"key":"B","text":"在經濟繁榮時，各大上市公司都增人資支出"},{"key":"C","text":"以上皆是"},{"key":"D","text":"以上皆非"}]', 'A', '不景氣時減人資支出，反映人資佔比大。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-415', 'logic', '「遲暮」對「襁褓」，那麼「除夕」對？', '[{"key":"A","text":"新年"},{"key":"B","text":"冬至"},{"key":"C","text":"端午"},{"key":"D","text":"中秋"}]', 'A', '遲暮對襁褓為老人對嬰兒；除夕對新年為年尾對年頭。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-416', 'logic', '與「氧：銅綠：銅」關係相同的是？（銅被氧氧化成銅綠）', '[{"key":"A","text":"氣體：固體：固體"},{"key":"B","text":"空氣：鐵鏽：釘子"},{"key":"C","text":"二氧化碳：環保：地球"},{"key":"D","text":"水：淘金：金子"}]', 'B', '釘子被空氣氧化成鐵鏽。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-417', 'logic', '「石油：生物沉積」的關係，與「____：骨頭」相同。空格應為？', '[{"key":"A","text":"關節"},{"key":"B","text":"礦物質"},{"key":"C","text":"化石"},{"key":"D","text":"牙齒"}]', 'C', '石油由生物沉積形成；化石由骨頭等形成。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-418', 'logic', '日蝕的時候貓一定會叫；貓不會叫的時候月亮會有發光。下列哪一個對？', '[{"key":"A","text":"日蝕的時候月亮會發光"},{"key":"B","text":"日蝕的時候月亮不會發光"},{"key":"C","text":"日蝕的時候有時月亮會發光"},{"key":"D","text":"以上皆錯"}]', 'D', '日蝕⇒貓叫；貓不叫⇒月發光。日蝕時貓叫，無法推月發光與否。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-419', 'logic', '「公務員須依法辦事，不得徇私。」句中「徇私」之意最接近：', '[{"key":"A","text":"公正無私"},{"key":"B","text":"因私情而偏袒"},{"key":"C","text":"公開透明"},{"key":"D","text":"依法裁量"}]', 'B', '徇私指為私情而偏袒、不公正。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-420', 'logic', '「蘋果⊂酸⊂糖」若成立（不考慮現實），可推得？', '[{"key":"A","text":"所有蘋果都是糖"},{"key":"B","text":"所有糖都是蘋果"},{"key":"C","text":"有些蘋果不是糖"},{"key":"D","text":"以上皆非"}]', 'A', '蘋果⊂酸⊂糖 ⇒ 所有蘋果都是糖。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-421', 'logic', '「醫學」：「耳鼻喉科」=「法律」：「？」', '[{"key":"A","text":"生意夥伴"},{"key":"B","text":"司法"},{"key":"C","text":"刑事法"},{"key":"D","text":"法官"}]', 'C', '耳鼻喉科為醫學專科；刑事法為法律一大類。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-422', 'logic', '「飄雪」與「暴風雪」的關係，正如「感冒」和下列哪項？', '[{"key":"A","text":"傷風"},{"key":"B","text":"肺炎"},{"key":"C","text":"咳嗽"},{"key":"D","text":"噴嚏"}]', 'B', '暴風雪為飄雪之加強；肺炎可視為感冒之嚴重後果。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-423', 'logic', '「陰：太極：陽」的類比，與下列哪組相同？', '[{"key":"A","text":"落選：應徵：當選"},{"key":"B","text":"月亮：天體：太陽"},{"key":"C","text":"黑色：顏色：白色"},{"key":"D","text":"以上皆是"}]', 'A', '太極僅陰陽兩極；應徵結果為落選或當選。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-424', 'logic', '「書：章節」相當於「法律：？」', '[{"key":"A","text":"條文"},{"key":"B","text":"法官"},{"key":"C","text":"法院"},{"key":"D","text":"律師"}]', 'A', '書由章節組成；法律由條文組成。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-425', 'logic', '「醫生：醫院」相當於「教師：？」', '[{"key":"A","text":"學校"},{"key":"B","text":"學生"},{"key":"C","text":"課本"},{"key":"D","text":"考試"}]', 'A', '醫生在醫院工作；教師在學校工作。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-426', 'logic', '「高：低」相當於「熱：？」', '[{"key":"A","text":"溫"},{"key":"B","text":"冷"},{"key":"C","text":"暖"},{"key":"D","text":"涼"}]', 'B', '高與低為反義；熱與冷為反義。', '["260"]');
