INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-495', 'logic', '「公務員須依法辦事，不得徇私。」句中「徇私」之意最接近：', '[{"key":"A","text":"公正無私"},{"key":"B","text":"因私情而偏袒"},{"key":"C","text":"公開透明"},{"key":"D","text":"依法裁量"}]', 'B', '徇私指為私情而偏袒、不公正。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-496', 'logic', '「蘋果⊂酸⊂糖」若成立（不考慮現實），可推得？', '[{"key":"A","text":"所有蘋果都是糖"},{"key":"B","text":"所有糖都是蘋果"},{"key":"C","text":"有些蘋果不是糖"},{"key":"D","text":"以上皆非"}]', 'A', '蘋果⊂酸⊂糖 ⇒ 所有蘋果都是糖。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-497', 'logic', '「醫學」：「耳鼻喉科」=「法律」：「？」', '[{"key":"A","text":"生意夥伴"},{"key":"B","text":"司法"},{"key":"C","text":"刑事法"},{"key":"D","text":"法官"}]', 'C', '耳鼻喉科為醫學專科；刑事法為法律一大類。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-498', 'logic', '「飄雪」與「暴風雪」的關係，正如「感冒」和下列哪項？', '[{"key":"A","text":"傷風"},{"key":"B","text":"肺炎"},{"key":"C","text":"咳嗽"},{"key":"D","text":"噴嚏"}]', 'B', '暴風雪為飄雪之加強；肺炎可視為感冒之嚴重後果。', '["260"]');
INSERT INTO questions (id, category, question, options, correct_key, explanation, exam_types) VALUES ('260-logic-499', 'logic', '「陰：太極：陽」的類比，與下列哪組相同？', '[{"key":"A","text":"落選：應徵：當選"},{"key":"B","text":"月亮：天體：太陽"},{"key":"C","text":"黑色：顏色：白色"},{"key":"D","text":"以上皆是"}]', 'A', '太極僅陰陽兩極；應徵結果為落選或當選。', '["260"]');
